          </View>
        </View>
        <View style={[styles.rightSegment, compact && styles.rightSegmentCompact]}>
          <Icon
            name={resolvedIconName}
            size={resolvedIconSize}
            color={resolvedIconColor}
          />
        </View>
      </TouchableOpacity>
    </Animated.View>
  );
};

