import React, { createContext, useState, useContext } from 'react';
import SummaryApi from '../common';
// Create context
const AuthContext = createContext();
// Provider component
export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(JSON.parse(localStorage.getItem('user')) || null);
  const [loading, setLoading] = useState(false);
  
  // Login function
  const login = async (username, password) => {
    setLoading(true);
    try {
      const response = await fetch(SummaryApi.logIn.url, {
        method: SummaryApi.logIn.method,
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username, password }),
      });
     
      const data = await response.json();
     
      if (data.success) {
        // Store user data in localStorage and state
        localStorage.setItem('user', JSON.stringify(data.data));
        setUser(data.data);
        return { success: true };
      } else {
        return { success: false, message: data.message };
      }
    } catch (error) {
      console.error('Login error:', error);
      return { success: false, message: 'Server error' };
    } finally {
      setLoading(false);
    }
  };
  // Logout function
  const logout = async () => {
    try {
      // Clear user from localStorage and state
      localStorage.removeItem('user');
      setUser(null);
    } catch (error) {
      console.error('Logout error:', error);
    }
  };

  // New function to update user context
  const updateUserContext = (updatedUserData) => {
    if (!user) return;
    
    const updatedUser = { ...user, ...updatedUserData };
    localStorage.setItem('user', JSON.stringify(updatedUser));
    setUser(updatedUser);
  };

  // Context values to be provided
  const value = {
    user,
    loading,
    login,
    logout,
    updateUserContext,
    isAuthenticated: !!user
  };
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};
// Custom hook to use auth context
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, {createContext, useState, useCallback} from 'react';
import {Platform, ToastAndroid} from 'react-native';

export const ToastContext = createContext();

export const ToastProvider = ({children}) => {
  const [toasts, setToasts] = useState([]);

  const showToast = useCallback((message, type = 'success', duration = 2000) => {
    if (Platform.OS === 'android') {
      const toastDuration =
        duration && duration <= 2000
          ? ToastAndroid.SHORT
          : ToastAndroid.LONG;
      ToastAndroid.showWithGravity(
        message,
        toastDuration,
        ToastAndroid.BOTTOM
      );
      return null;
    }
    const id = Math.random().toString(36).substr(2, 9);
    const toast = {id, message, type, duration};

    setToasts(prev => [...prev, toast]);

    setTimeout(() => {
      dismissToast(id);
    }, duration);

    return id;
  }, []);

  const dismissToast = useCallback((id) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const value = {
    showToast,
    showUniversalToast: showToast,
    dismissToast,
    toasts,
  };

  return (
    <ToastContext.Provider value={value}>
      {children}
    </ToastContext.Provider>
  );
};

import React, {useState, useEffect, useMemo} from 'react';
import {StyleSheet, TouchableOpacity, Text} from 'react-native';
import {createBottomTabNavigator} from '@react-navigation/bottom-tabs';
import Icon from 'react-native-vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import {useSafeAreaInsets} from 'react-native-safe-area-context';

import DashboardStackNavigator from './DashboardStackNavigator';
import LedgerStackNavigator from './LedgerStackNavigator';
import Header from '../components/Header';
import {fontSize} from '../utils/theme';
import {auth} from '../config/firebase';
import {saveUserData} from '../services/database';
import TexturedSurface from '../components/TexturedSurface';
import {useHeaderTextureTheme} from '../context/HeaderTextureContext';
import {
  DEFAULT_TAB_DASHBOARD,
  DEFAULT_TAB_FALLBACK,
  DEFAULT_TAB_LEDGER,
  readDefaultTabPreference,
} from '../utils/defaultTabPreference';

const Tab = createBottomTabNavigator();
const MoreTabPlaceholder = () => null;

const MainTabNavigator = ({route, navigation}) => {
  const insets = useSafeAreaInsets();
  const {
    user: initialUser,
    showTutorial,
    suppressSetupPopupOnce = false,
    initialTabOverride = '',
  } = route.params || {};
  const {themeId: tabTextureId} = useHeaderTextureTheme();
  const [user, setUser] = useState(initialUser || null);
  const [showHeader, setShowHeader] = useState(true);
  const [initialTab, setInitialTab] = useState(DEFAULT_TAB_FALLBACK);
  const [isInitialTabReady, setIsInitialTabReady] = useState(false);
  const baseTabBarStyle = {
    backgroundColor: 'transparent',
    borderTopWidth: 1,
    borderTopColor: '#5A7468',
    height: 60 + insets.bottom,
    paddingBottom: Math.max(8, insets.bottom),
    paddingTop: 8,
  };

  useEffect(() => {
    if (!user) {
      loadUserData();
    }
  }, [user]);

  useEffect(() => {
    let isMounted = true;

    const loadInitialTab = async () => {
      const normalizedOverride = String(initialTabOverride || '').trim();
      if (
        normalizedOverride === DEFAULT_TAB_DASHBOARD ||
        normalizedOverride === DEFAULT_TAB_LEDGER
      ) {
        if (!isMounted) {
          return;
        }
        setInitialTab(normalizedOverride);
        setIsInitialTabReady(true);
        return;
      }
      const storedTab = await readDefaultTabPreference();
      if (!isMounted) {
        return;
      }
      setInitialTab(
        storedTab === DEFAULT_TAB_LEDGER
          ? DEFAULT_TAB_LEDGER
          : DEFAULT_TAB_DASHBOARD,
      );
      setIsInitialTabReady(true);
    };

    loadInitialTab();

    return () => {
      isMounted = false;
    };
  }, [initialTabOverride]);

  const loadUserData = async () => {
    try {
      const userData = await AsyncStorage.getItem('user');
      if (userData) {
        setUser(JSON.parse(userData));
      }
    } catch (error) {
      console.error('Error loading user data:', error);
    }
  };

  const tabBarBackground = useMemo(
    () => () => (
      <TexturedSurface
        style={styles.tabTextureWrap}
        themeId={tabTextureId}
      />
    ),
    [tabTextureId]
  );

  const handleProfileUpdate = async updates => {
    try {
      const updatedUser = {
        ...(user || {}),
        ...updates,
      };
      setUser(updatedUser);

      const currentUser = auth().currentUser;
      if (currentUser) {
        await currentUser.updateProfile({
          displayName: updatedUser.displayName || '',
          photoURL: updatedUser.photoURL || '',
        });
      }

      await AsyncStorage.setItem('user', JSON.stringify(updatedUser));
      saveUserData(updatedUser);
      return {success: true};
    } catch (error) {
      console.error('Failed to update profile:', error);
      return {success: false, message: 'Failed to update profile'};
    }
  };
  const showSetupRibbon = showHeader && user?.setupComplete !== true;

  const handleSetupNowPress = () => {
    navigation.navigate('ProfileSetup', {user: user || {}});
  };

  if (!isInitialTabReady) {
    return null;
  }

  return (
    <>
      {showHeader && (
        <Header
          user={user}
          onProfileUpdate={handleProfileUpdate}
        />
      )}
      {showSetupRibbon ? (
        <TouchableOpacity
          style={styles.setupRibbon}
          activeOpacity={0.85}
          onPress={handleSetupNowPress}>
          <Text style={styles.setupRibbonText}>
            Complete profile setup to unlock all features.
          </Text>
          <Text style={styles.setupRibbonCta}>Setup now</Text>
        </TouchableOpacity>
      ) : null}
      <Tab.Navigator
        initialRouteName={initialTab}
        screenOptions={{
          headerShown: false,
          detachInactiveScreens: true,
          freezeOnBlur: true,
          tabBarActiveTintColor: '#FFFFFF',
          tabBarInactiveTintColor: '#FFFFFF',
          tabBarBackground,
          tabBarStyle: baseTabBarStyle,
          tabBarLabelStyle: {
            fontSize: fontSize.small,
            fontWeight: '500',
          },
        }}
        backBehavior="history">
        <Tab.Screen
          name="Dashboard"
          component={DashboardStackNavigator}
          initialParams={{user, showTutorial, suppressSetupPopupOnce}}
          options={{
            tabBarIcon: ({color, size, focused}) => (
              <Icon name={focused ? 'home' : 'home-outline'} size={size} color={color} />
            ),
          }}
          listeners={{
            tabPress: () => setShowHeader(true),
            focus: () => setShowHeader(true),
          }}
        />
        <Tab.Screen
          name="Ledger"
          component={LedgerStackNavigator}
          options={{
            tabBarLabel: 'Legder Talk',
            tabBarIcon: ({color, size, focused}) => (
              <Icon
                name={focused ? 'chatbox-ellipses' : 'chatbox-ellipses-outline'}
                size={size}
                color={color}
              />
            ),
          }}
          listeners={{
            tabPress: () => setShowHeader(true),
            focus: () => setShowHeader(true),
          }}
        />
        <Tab.Screen
          name="More"
          component={MoreTabPlaceholder}
          options={{
            tabBarIcon: ({color, size, focused}) => (
              <Icon name={focused ? 'grid' : 'grid-outline'} size={size} color={color} />
            ),
          }}
          listeners={({navigation}) => ({
            tabPress: e => {
              e.preventDefault();
              setShowHeader(true);
              navigation.getParent()?.navigate('MoreNative', {user});
            },
          })}
        />
      </Tab.Navigator>
    </>
  );
};

