        </Text>
      </View>

      <View style={[styles.section, backupLocked && styles.sectionInactive]}>
        <View style={styles.row}>
          <Text style={styles.sectionTitle}>Auto Backup</Text>
          <ToggleSwitch
            value={backupEnabled}
