const DEFAULT_MONTH_START_DAY = 1;
const QUICK_PERIOD_STORAGE_KEY = 'dashboardQuickPeriodV1';
const DASHBOARD_SHOW_SAVINGS_BALANCE_KEY = 'dashboard_show_savings_balance_in_net';
const DASHBOARD_HIDE_SAVING_ACCOUNTS_KEY = 'dashboard_hide_saving_accounts';

const METRIC_ICON_SIZE = 24;
const METRIC_LABEL_GAP = 8;
const METRIC_LABEL_OFFSET = METRIC_ICON_SIZE + METRIC_LABEL_GAP;

const renderAccountIcon = (iconName, size, color) => {
  if (iconName === 'bs-cash-coin') {
    return <BsCashCoin size={size} color={color} />;
  }
  return <Icon name={iconName} size={size} color={color} />;
};

const DashboardScreen = ({navigation, route}) => {
  const insets = useSafeAreaInsets();

  // Period selection states
  const [quickPeriod, setQuickPeriod] = useState('10days');
  const [selectedMonth, setSelectedMonth] = useState(null);
  const [selectedYear, setSelectedYear] = useState(null);
  const [isBottomSheetVisible, setBottomSheetVisible] = useState(false);
  const [bottomSheetContent, setBottomSheetContent] = useState(null);

  // Available years (will be populated from transactions)
  const [availableYears, setAvailableYears] = useState([]);

  // Filtered data states
  const [filteredEarning, setFilteredEarning] = useState(0);
  const [filteredWithdrawals, setFilteredWithdrawals] = useState(0);
  const [hasRecords, setHasRecords] = useState(true);
  const [periodAccountAmounts, setPeriodAccountAmounts] = useState({});
  const [periodAccountExpenses, setPeriodAccountExpenses] = useState({});
  const [closingAccountBalances, setClosingAccountBalances] = useState({});
  const [fabExpanded, setFabExpanded] = useState(false);

  // Other states
  const [accounts, setAccounts] = useState([]);
  const [monthStartDay, setMonthStartDay] = useState(DEFAULT_MONTH_START_DAY);
  const [showSavingsBalanceInDashboard, setShowSavingsBalanceInDashboard] =
    useState(true);
  const [hideSavingAccountsOnDashboard, setHideSavingAccountsOnDashboard] =
    useState(false);
  const [contextMenuVisible, setContextMenuVisible] = useState(false);
  const [selectedAccount, setSelectedAccount] = useState(null);
  const selectedAccountRef = useRef(null);
  const deletePressGuardRef = useRef(false);
  const renameInputRef = useRef(null);
  const [renameModalVisible, setRenameModalVisible] = useState(false);
  const [renameTargetAccount, setRenameTargetAccount] = useState(null);
  const [newAccountName, setNewAccountName] = useState('');
  const {showToast} = useToast();
  const currencySymbol = useCurrencySymbol();

  // Setup completion popup states
  const [showSetupPopup, setShowSetupPopup] = useState(false);
  const [popupDismissedThisSession, setPopupDismissedThisSession] =
    useState(false);
  const [startupNeverShowChecked, setStartupNeverShowChecked] = useState(false);
  const [showStartupNeverShowCheckbox, setShowStartupNeverShowCheckbox] =
    useState(false);
  const startupNeverShowKeyRef = useRef('');
  const startupPopupShowCountKeyRef = useRef('');
  const suppressSetupPopupOnceRef = useRef(
    route?.params?.suppressSetupPopupOnce === true
  );

  const fabRef = useRef(null);
  const fabAnim = useRef(new Animated.Value(0)).current;
  const bottomInsetWithFallback =
    insets.bottom > 0 ? insets.bottom : Platform.OS === 'android' ? 18 : 0;
  const fabBottomOffset = spacing.lg + bottomInsetWithFallback;
  const fabActionsBottomOffset = fabBottomOffset + 64;

  const focusRenameInput = useCallback(() => {
    const focus = () => renameInputRef.current?.focus();
    InteractionManager.runAfterInteractions(() => {
      requestAnimationFrame(focus);
      setTimeout(focus, 120);
    });
  }, []);

  const renameModalStyles = {
    ...styles,
    modalOverlay: styles.renameModalOverlay,
    modalBackdrop: styles.renameModalBackdrop,
    modalSheet: styles.renameModalSheet,
    modalHandle: styles.renameModalHandle,
    modalTitle: styles.renameModalTitle,
    modalTextInput: styles.renameModalTextInput,
    modalAddButton: styles.renameModalAddButton,
    modalAddButtonText: styles.renameModalAddButtonText,
  };

  const netBalance = React.useMemo(() => {
    let endTime = Date.now();
    if (selectedMonth !== null && selectedYear !== null) {
      const end = new Date(selectedYear, selectedMonth + 1, monthStartDay);
      end.setHours(0, 0, 0, 0);
      end.setMilliseconds(end.getMilliseconds() - 1);
      endTime = end.getTime();
    }

    let total = 0;
    accounts.forEach(account => {
      const isSavingAccount =
        String(account?.account_type || '').toLowerCase() === 'saving';
      if (!showSavingsBalanceInDashboard && isSavingAccount) {
        return;
      }
      const txns = getTransactionsByAccount(account.id);
      txns.forEach(txn => {
        if (Number(txn?.is_deleted) === 1) {
          return;
        }
        if (Number(txn?.transaction_date) <= endTime) {
          total += Number(txn?.amount) || 0;
        }
      });
    });
    return total;
  }, [
    accounts,
    selectedMonth,
    selectedYear,
    monthStartDay,
    showSavingsBalanceInDashboard,
  ]);

  const loadShowSavingsBalancePreference = useCallback(async () => {
    try {
      const stored = await AsyncStorage.getItem(DASHBOARD_SHOW_SAVINGS_BALANCE_KEY);
      if (stored === '0') {
        setShowSavingsBalanceInDashboard(false);
        return;
      }
      setShowSavingsBalanceInDashboard(true);
    } catch (error) {
      console.error('Failed to load dashboard savings visibility setting:', error);
      setShowSavingsBalanceInDashboard(true);
    }
  }, []);

  const loadHideSavingAccountsPreference = useCallback(async () => {
    try {
      const stored = await AsyncStorage.getItem(DASHBOARD_HIDE_SAVING_ACCOUNTS_KEY);
      setHideSavingAccountsOnDashboard(stored === '1');
    } catch (error) {
      console.error('Failed to load hide saving accounts setting:', error);
      setHideSavingAccountsOnDashboard(false);
    }
  }, []);

  const handleAddAccountPress = () => {
    const next = !fabExpanded;
    setFabExpanded(next);
    Animated.timing(fabAnim, {
      toValue: next ? 1 : 0,
      duration: 200,
      useNativeDriver: true,
    }).start();
  };

  const closeFabMenu = () => {
    setFabExpanded(false);
    Animated.timing(fabAnim, {
      toValue: 0,
      duration: 200,
      useNativeDriver: true,
    }).start();
  };

  const openAddAccount = type => {
    closeFabMenu();
    navigation.navigate('AddAccount', {accountType: type});
  };

  const selectedAccountIndex = React.useMemo(() => {
    if (!selectedAccount) {
      return -1;
    }
    return accounts.findIndex(
      account => String(account.id) === String(selectedAccount.id)
    );
  }, [accounts, selectedAccount]);

  const selectedAccountType = selectedAccount?.account_type;
  const accountsOfType = React.useMemo(() => {
    if (!selectedAccountType) {
      return [];
    }
    return accounts.filter(
      account => account.account_type === selectedAccountType
    );
  }, [accounts, selectedAccountType]);
  const selectedAccountTypeIndex = React.useMemo(() => {
    if (!selectedAccount) {
      return -1;
    }
    return accountsOfType.findIndex(
      account => String(account.id) === String(selectedAccount.id)
    );
  }, [accountsOfType, selectedAccount]);
  const canMoveWithinType = accountsOfType.length >= 2;
  const isMoveUpDisabled = !canMoveWithinType || selectedAccountTypeIndex <= 0;
  const isMoveDownDisabled =
    !canMoveWithinType ||
    selectedAccountTypeIndex < 0 ||
    selectedAccountTypeIndex >= accountsOfType.length - 1;

  // Animation values
  const overlayOpacity = useRef(new Animated.Value(0)).current;
  const contentTranslateY = useRef(new Animated.Value(300)).current;

  // Initialize database and load accounts on mount
  useEffect(() => {
    try {
      initAccountsDatabase();
      initTransactionsDatabase();
      loadMonthStartDay();
      loadAccounts();
      loadShowSavingsBalancePreference();
      loadHideSavingAccountsPreference();
    } catch (error) {
      console.error('Failed to initialize accounts database:', error);
    }
  }, [loadShowSavingsBalancePreference, loadHideSavingAccountsPreference]);

  useEffect(() => {
    if (Platform.OS === 'android') {
      UIManager.setLayoutAnimationEnabledExperimental?.(true);
    }
  }, []);

  useEffect(() => {
    const loadQuickPeriodPreference = async () => {
      try {
        const storedPeriod = await AsyncStorage.getItem(QUICK_PERIOD_STORAGE_KEY);
        const validValues = QUICK_PERIODS.map(item => item.value);
        if (storedPeriod && validValues.includes(storedPeriod)) {
          setQuickPeriod(storedPeriod);
        }
      } catch (error) {
        console.error('Failed to load quick period preference:', error);
      }
    };

    loadQuickPeriodPreference();
  }, []);

  const runPinReorderAnimation = () => {
    LayoutAnimation.configureNext({
      duration: 600,
      update: {type: LayoutAnimation.Types.easeInEaseOut},
      create: {
        type: LayoutAnimation.Types.easeInEaseOut,
        property: LayoutAnimation.Properties.scaleXY,
      },
      delete: {
        type: LayoutAnimation.Types.easeInEaseOut,
        property: LayoutAnimation.Properties.opacity,
      },
    });
  };

  // Refresh accounts when screen comes into focus
  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', () => {
      loadMonthStartDay();
      loadAccounts();
      loadShowSavingsBalancePreference();
      loadHideSavingAccountsPreference();
      // generateAvailableYears and updateFilteredData are already derived from state effects.
      // Avoid triggering duplicate heavy calculations on every focus.
    });

    return unsubscribe;
  }, [navigation, loadShowSavingsBalancePreference, loadHideSavingAccountsPreference]);

  // Update filtered data when period selection changes
  useEffect(() => {
    updateFilteredData();
  }, [quickPeriod, selectedMonth, selectedYear, accounts, monthStartDay]);

  // Generate years when accounts load
  useEffect(() => {
    generateAvailableYears();
  }, [accounts]);

  useEffect(() => {
    if (!renameModalVisible) {
      return;
    }
    const timer = setTimeout(() => {
      focusRenameInput();
    }, 250);
    return () => clearTimeout(timer);
  }, [renameModalVisible, focusRenameInput]);

  const hasBasicDetails = userData => {
    const name = String(userData?.displayName || userData?.name || '').trim();
    const phone = String(
      userData?.phoneNumber || userData?.mobile || ''
    ).trim();
    const currency = String(
      userData?.currencySymbol ||
        userData?.currency ||
        userData?.currency_symbol ||
        ''
    ).trim();
    return Boolean(name) && Boolean(phone) && Boolean(currency);
  };

  const getStartupNeverShowKey = userData => {
    const firebaseUid = String(userData?.firebaseUid || '').trim();
    if (firebaseUid) {
      return `startupSetupPopup.neverShow.${firebaseUid}`;
    }
    const email = String(userData?.email || '').trim().toLowerCase();
    if (email) {
      return `startupSetupPopup.neverShow.${email}`;
    }
    return '';
  };

  const getStartupPopupShowCountKey = userData => {
    const firebaseUid = String(userData?.firebaseUid || '').trim();
    if (firebaseUid) {
      return `startupSetupPopup.showCount.${firebaseUid}`;
    }
    const email = String(userData?.email || '').trim().toLowerCase();
    if (email) {
      return `startupSetupPopup.showCount.${email}`;
    }
    return '';
  };

  // Check setup completion status on screen focus
  useFocusEffect(
    React.useCallback(() => {
      const checkSetupStatus = async () => {
        try {
          if (suppressSetupPopupOnceRef.current) {
            suppressSetupPopupOnceRef.current = false;
            setShowSetupPopup(false);
            setPopupDismissedThisSession(true);
            return;
          }
          const storedUser = await AsyncStorage.getItem('user');
          if (storedUser) {
            const userData = JSON.parse(storedUser);
            const neverShowKey = getStartupNeverShowKey(userData);
            const showCountKey = getStartupPopupShowCountKey(userData);
            startupNeverShowKeyRef.current = neverShowKey;
            startupPopupShowCountKeyRef.current = showCountKey;
            const neverShowValue = neverShowKey
              ? await AsyncStorage.getItem(neverShowKey)
              : null;
            const neverShowEnabled = neverShowValue === 'true';
            setStartupNeverShowChecked(neverShowEnabled);
            if (neverShowEnabled) {
              setShowSetupPopup(false);
              setShowStartupNeverShowCheckbox(false);
              return;
            }
            const setupComplete = Boolean(userData?.setupComplete);
            const missingDetails = !hasBasicDetails(userData);
            if (!setupComplete && missingDetails && !popupDismissedThisSession) {
              let nextShowCount = 1;
              if (showCountKey) {
                const rawCount = await AsyncStorage.getItem(showCountKey);
                const parsedCount =
                  Number.parseInt(String(rawCount || '0'), 10) || 0;
                nextShowCount = parsedCount + 1;
                await AsyncStorage.setItem(showCountKey, String(nextShowCount));
              }
              setShowStartupNeverShowCheckbox(nextShowCount >= 3);
              setShowSetupPopup(true);
            } else {
              setShowStartupNeverShowCheckbox(false);
            }
          }
        } catch (error) {
          console.error('Error checking setup status:', error);
        }
      };

      checkSetupStatus();
    }, [popupDismissedThisSession])
  );

  const handleToggleStartupNeverShow = async () => {
    const nextValue = !startupNeverShowChecked;
    setStartupNeverShowChecked(nextValue);
    try {
      const key = startupNeverShowKeyRef.current;
      if (!key) {
        return;
      }
      await AsyncStorage.setItem(key, nextValue ? 'true' : 'false');
    } catch (error) {
      console.error('Failed to save startup popup never-show preference:', error);
    }
  };

  const handleOpenProfileSetup = async () => {
    setShowSetupPopup(false);
    try {
      const storedUser = await AsyncStorage.getItem('user');
      const parsedUser = storedUser ? JSON.parse(storedUser) : {};
      navigation.navigate('ProfileSetup', {user: parsedUser || {}});
    } catch (error) {
      console.error('Failed to open profile setup from startup popup:', error);
      navigation.navigate('ProfileSetup', {user: {}});
    }
  };

  const handleRemindLater = () => {
    setShowSetupPopup(false);
    setPopupDismissedThisSession(true);
  };

  const normalizeMonthStartDay = value => {
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) {
      return DEFAULT_MONTH_START_DAY;
    }
    return Math.min(28, Math.max(1, Math.floor(parsed)));
  };

  const loadMonthStartDay = async () => {
    try {
      const stored = await AsyncStorage.getItem(MONTH_START_DAY_KEY);
      setMonthStartDay(normalizeMonthStartDay(stored));
    } catch (error) {
      console.error('Failed to load month start day:', error);
    }
  };

  const getMonthlyRangeFromStartDay = (startDay, referenceDate = new Date()) => {
    const start = new Date(
      referenceDate.getFullYear(),
      referenceDate.getMonth(),
      startDay
    );
    if (referenceDate.getDate() < startDay) {
      start.setMonth(start.getMonth() - 1);
    }
    start.setHours(0, 0, 0, 0);
    const end = new Date(start);
    end.setMonth(end.getMonth() + 1);
    end.setMilliseconds(end.getMilliseconds() - 1);
    return {startTime: start.getTime(), endTime: end.getTime()};
  };

  const getMonthYearRange = (month, year, startDay) => {
    const start = new Date(year, month, startDay);
    start.setHours(0, 0, 0, 0);
    const end = new Date(year, month + 1, startDay);
    end.setHours(0, 0, 0, 0);
    end.setMilliseconds(end.getMilliseconds() - 1);
    return {startTime: start.getTime(), endTime: end.getTime()};


  };

  // Load accounts from database with updated balances
  const loadAccounts = () => {
    try {
      const accountsList = getAllAccounts();

      // Update each account with current balance from transactions
      const accountsWithBalance = accountsList.map(account => {
        const balance = calculateAccountBalance(account.id);
        return {
          ...account,
          balance: balance,
        };
      });

      console.log('Loaded accounts with balances:', accountsWithBalance);
      setAccounts(accountsWithBalance);
      // Note: Filtered earning/withdrawal data will be calculated by updateFilteredData()
    } catch (error) {
      console.error('Failed to load accounts:', error);
    }
  };

  // Generate available years from user registration or first transaction
  // Generate available years list from 2015 to current year
  const generateAvailableYears = () => {
    try {
      const currentYear = new Date().getFullYear();
      const startYear = 2015;
      const years = [];
      for (let year = currentYear; year >= startYear; year--) {
        years.push(year);
      }
      setAvailableYears(years);
    } catch (error) {
      console.error('Failed to generate years:', error);
      setAvailableYears([new Date().getFullYear()]);
    }
  };

  const isTransferTransaction = txn => {
    const remark = String(txn?.remark || '').trim().toLowerCase();
    return (
      remark.startsWith('transferred to ') ||
      remark.startsWith('transferred from ') ||
      remark.startsWith('requested to ') ||
      remark.startsWith('requested from ') ||
      remark.startsWith('requested by ')
    );
  };

  const buildPeriodAccountSummaries = (startTime, endTime) => {
    const netByAccount = {};
    const expenseByAccount = {};
    const closingByAccount = {};
    const resolvedEndTime = endTime ?? Date.now();
    const accountsList = getAllAccounts();

    accountsList.forEach(account => {
      let netTotal = 0;
      let expenseTotal = 0;
      let closingTotal = 0;
      const txns = getTransactionsByAccount(account.id);

      txns.forEach(txn => {
        if (Number(txn.is_deleted) === 1) {
          return;
        }
        const amount = Number(txn.amount) || 0;
        if (txn.transaction_date <= resolvedEndTime) {
          closingTotal += amount;
        }
        if (
          txn.transaction_date < startTime ||
          (endTime !== null && txn.transaction_date > endTime)
        ) {
          return;
        }

        netTotal += amount;
        if (amount < 0) {
          expenseTotal += Math.abs(amount);
        }
      });

      netByAccount[account.id] = netTotal;
      expenseByAccount[account.id] = expenseTotal;
      closingByAccount[account.id] = closingTotal;
    });

    return {netByAccount, expenseByAccount, closingByAccount};
  };
  // Calculate data for Quick Period
  const calculateQuickPeriodData = period => {
    try {
      const now = new Date();
      let startTime;
      let endTime = null;

      switch (period) {
        case '1week': {
          const start = new Date(now);
          start.setDate(now.getDate() - 4);
          start.setHours(0, 0, 0, 0);
          startTime = start.getTime();
          break;
        }
        case '10days': {
          const start = new Date(now);
          start.setDate(now.getDate() - 9);
          start.setHours(0, 0, 0, 0);
          startTime = start.getTime();
          break;
        }
        case '15days': {
          const start = new Date(now);
          start.setDate(now.getDate() - 14);
          start.setHours(0, 0, 0, 0);
          startTime = start.getTime();
          break;
        }
        case '30days': {
          const start = new Date(now);
          start.setDate(now.getDate() - 29);
          start.setHours(0, 0, 0, 0);
          startTime = start.getTime();
          break;
        }
        case '1month': {
          const range = getMonthlyRangeFromStartDay(monthStartDay, now);
          startTime = range.startTime;
          endTime = range.endTime;
          break;
        }
        case '3months':
          startTime = now.getTime() - 90 * 24 * 60 * 60 * 1000;
          break;
        case '6months':
          startTime = now.getTime() - 180 * 24 * 60 * 60 * 1000;
          break;
        case '1year':
          startTime = now.getTime() - 365 * 24 * 60 * 60 * 1000;
          break;
        default:
          startTime = now.getTime() - 30 * 24 * 60 * 60 * 1000;
      }

      let earning = 0;
      let withdrawals = 0;
      let recordCount = 0;

      const accountsList = getAllAccounts();
      accountsList.forEach(account => {
        const txns = getTransactionsByAccount(account.id);
        txns.forEach(txn => {
          if (Number(txn.is_deleted) === 1) {
            return;
          }
          if (
            txn.transaction_date >= startTime &&
            (endTime === null || txn.transaction_date <= endTime)
          ) {
            recordCount++;
            const amount = Number(txn.amount) || 0;
            const isTransfer = isTransferTransaction(txn);
            if (isTransfer) {
              return;
            }
            if (amount > 0 && account.account_type === 'earning') {
              earning += amount;
            } else if (amount < 0) {
              withdrawals += Math.abs(amount);
            }
          }
        });
      });

      setFilteredEarning(earning);
      setFilteredWithdrawals(withdrawals);
      setHasRecords(recordCount > 0);
      const {netByAccount, expenseByAccount, closingByAccount} = buildPeriodAccountSummaries(startTime, endTime);
      setPeriodAccountAmounts(netByAccount);
      setPeriodAccountExpenses(expenseByAccount);
      setClosingAccountBalances(closingByAccount);
    } catch (error) {
      console.error('Failed to calculate quick period data:', error);
      setFilteredEarning(0);
      setFilteredWithdrawals(0);
      setHasRecords(false);
      setPeriodAccountAmounts({});
      setPeriodAccountExpenses({});
      setClosingAccountBalances({});
    }
  };

  // Calculate data for specific Month + Year
  const calculateMonthYearData = (month, year) => {
    try {
      if (month === null || year === null) {
        return;
      }

      const {startTime, endTime} = getMonthYearRange(
        month,
        year,
        monthStartDay
      );

      let earning = 0;
      let withdrawals = 0;
      let recordCount = 0;

      const accountsList = getAllAccounts();
      accountsList.forEach(account => {
        const txns = getTransactionsByAccount(account.id);
        txns.forEach(txn => {
          if (Number(txn.is_deleted) === 1) {
            return;
          }
          if (
            txn.transaction_date >= startTime &&
            txn.transaction_date <= endTime
          ) {
            recordCount++;
            const amount = Number(txn.amount) || 0;
            const isTransfer = isTransferTransaction(txn);
            if (isTransfer) {
              return;
            }
            if (amount > 0 && account.account_type === 'earning') {
              earning += amount;
            } else if (amount < 0) {
              withdrawals += Math.abs(amount);
            }
          }
        });
      });

      setFilteredEarning(earning);
      setFilteredWithdrawals(withdrawals);
      setHasRecords(recordCount > 0);
      const {netByAccount, expenseByAccount, closingByAccount} = buildPeriodAccountSummaries(startTime, endTime);
      setPeriodAccountAmounts(netByAccount);
      setPeriodAccountExpenses(expenseByAccount);
      setClosingAccountBalances(closingByAccount);
    } catch (error) {
      console.error('Failed to calculate month/year data:', error);
      setFilteredEarning(0);
      setFilteredWithdrawals(0);
      setHasRecords(false);
      setPeriodAccountAmounts({});
      setPeriodAccountExpenses({});
      setClosingAccountBalances({});
    }
  };

  // Update filtered data based on current selection
  const updateFilteredData = () => {
    if (selectedMonth !== null && selectedYear !== null) {
      // Month + Year selected - use them
      calculateMonthYearData(selectedMonth, selectedYear);
    } else {
      // Use Quick Period
      calculateQuickPeriodData(quickPeriod);
    }
  };

  // Handle Quick Period selection
  const handleQuickPeriodSelect = period => {
    setQuickPeriod(period);
    setSelectedMonth(null);
    setSelectedYear(null);
    setBottomSheetVisible(false);
    AsyncStorage.setItem(QUICK_PERIOD_STORAGE_KEY, period).catch(error => {
      console.error('Failed to save quick period preference:', error);
    });
    // Data will update via useEffect
  };

  // Handle Month selection
  const handleMonthSelect = month => {
    setSelectedMonth(month);
    if (selectedYear === null) {
      setSelectedYear(new Date().getFullYear());
    }
    setBottomSheetVisible(false);
    // Data will update via useEffect
  };

  // Handle Year selection
  const handleYearSelect = year => {
    setSelectedYear(year);
    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth();
    if (year === currentYear && selectedMonth !== null && selectedMonth > currentMonth) {
      setSelectedMonth(null);
    }
    setBottomSheetVisible(false);
    // Data will update via useEffect if month is also selected
  };

  const renderBottomSheetContent = () => {
    if (bottomSheetContent === 'quick') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Period</Text>
          {QUICK_PERIODS.map(period => (
            <TouchableOpacity
              key={period.value}
              style={[
                styles.dropdownOption,
                quickPeriod === period.value && styles.dropdownOptionActive,
              ]}
              onPress={() => handleQuickPeriodSelect(period.value)}>
              <Text
                style={[
                  styles.dropdownOptionText,
                  quickPeriod === period.value && styles.dropdownOptionTextActive,
                ]}>
                {period.label}
              </Text>
              {quickPeriod === period.value && (
                <Icon name="checkmark" size={18} color={colors.primary} />
              )}
            </TouchableOpacity>
          ))}
        </>
      );
    }

    if (bottomSheetContent === 'month') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Month</Text>
          {selectedMonth !== null && (
            <TouchableOpacity
              style={styles.dropdownOptionClear}
              onPress={() => {
                setSelectedMonth(null);
                setBottomSheetVisible(false);
              }}>
              <Text style={styles.dropdownOptionClearText}>Clear Selection</Text>
              <Icon name="close-circle" size={18} color={colors.error} />
            </TouchableOpacity>
          )}
          {MONTHS.map(month => {
            const now = new Date();
            const currentYear = now.getFullYear();
            const currentMonth = now.getMonth();
            const effectiveYear = selectedYear ?? currentYear;
            const isFutureMonth =
              effectiveYear === currentYear && month.value > currentMonth;
            const isSelected = !isFutureMonth && selectedMonth === month.value;

            return (
              <TouchableOpacity
                key={month.value}
                style={[
                  styles.dropdownOption,
                  isSelected && styles.dropdownOptionActive,
                  isFutureMonth && styles.dropdownOptionDisabled,
                ]}
                disabled={isFutureMonth}
                onPress={() => handleMonthSelect(month.value)}>
                <Text
                  style={[
                    styles.dropdownOptionText,
                    isSelected && styles.dropdownOptionTextActive,
                    isFutureMonth && styles.dropdownOptionTextDisabled,
                  ]}>
                  {month.label}
                </Text>
                {isSelected && (
                  <Icon name="checkmark" size={18} color={colors.primary} />
                )}
              </TouchableOpacity>
            );
          })}
        </>
      );
    }

    if (bottomSheetContent === 'year') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Year</Text>
          {selectedYear !== null && (
            <TouchableOpacity
              style={styles.dropdownOptionClear}
              onPress={() => {
                setSelectedYear(null);
                setBottomSheetVisible(false);
              }}>
              <Text style={styles.dropdownOptionClearText}>Clear Selection</Text>
              <Icon name="close-circle" size={18} color={colors.error} />
            </TouchableOpacity>
          )}
          {availableYears.map(year => (
            <TouchableOpacity
              key={year}
              style={[
                styles.dropdownOption,
                selectedYear === year && styles.dropdownOptionActive,
              ]}
              onPress={() => handleYearSelect(year)}>
              <Text
                style={[
                  styles.dropdownOptionText,
                  selectedYear === year && styles.dropdownOptionTextActive,
                ]}>
                {year}
              </Text>
              {selectedYear === year && (
                <Icon name="checkmark" size={18} color={colors.primary} />
              )}
            </TouchableOpacity>
          ))}
        </>
      );
    }

    return null;
  };

  const formatCurrency = amount => {
    return `${currencySymbol} ${amount.toLocaleString('en-IN')}`;
  };

  const formatCurrencyRupee = amount => {
    const sign = amount < 0 ? '-' : '';
    const absAmount = Math.abs(amount);
    return `${sign}${currencySymbol} ${absAmount.toLocaleString('en-IN')}`;
  };

  const formatCardPeriodDate = value =>
    new Date(value).toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    });

  const cardPeriodText = React.useMemo(() => {
    if (selectedMonth !== null && selectedYear !== null) {
      let startTime = null;
      let endTime = Date.now();
      const range = getMonthYearRange(selectedMonth, selectedYear, monthStartDay);
      startTime = range.startTime;
      endTime = range.endTime;
      return `Period: ${formatCardPeriodDate(startTime)} - ${formatCardPeriodDate(endTime)}`;
    }

    if (quickPeriod === '1month') {
      const now = new Date();
      const range = getMonthlyRangeFromStartDay(monthStartDay, now);
      return `Period: ${formatCardPeriodDate(range.startTime)} - ${formatCardPeriodDate(
        range.endTime
      )}`;
    }

    const quickPeriodTextMap = {
      '1week': 'Last 5 days transactions',
      '10days': 'Last 10 days transactions',
      '15days': 'Last 15 days transactions',
      '30days': 'Last 30 days transactions',
      '3months': 'Last 3 months transactions',
      '6months': 'Last 6 months transactions',
      '1year': 'Last 1 year transactions',
    };

    return quickPeriodTextMap[quickPeriod] || 'Recent transactions';
  }, [quickPeriod, selectedMonth, selectedYear, monthStartDay]);

  const getAccountExpensesAmount = accountId => {
    const entries = getTransactionsByAccount(accountId);
    return entries.reduce((total, txn) => {
      if (Number(txn?.is_deleted) === 1) {
        return total;
      }
      if (isTransferTransaction(txn)) {
        return total;
      }
      const amount = Number(txn?.amount) || 0;
      return amount < 0 ? total + Math.abs(amount) : total;
    }, 0);
  };

  const getSortIndexValue = (account, fallback) => {
    const value = Number(account?.sort_index);
    return Number.isFinite(value) ? value : fallback;
  };

  const moveSelectedAccount = async direction => {
    const account = selectedAccountRef.current || selectedAccount;
    if (!account) {
      return;
    }
    if (!canMoveWithinType) {
      return;
    }
    const currentIndex =
      selectedAccountIndex >= 0
        ? selectedAccountIndex
        : accounts.findIndex(
            item => String(item.id) === String(account.id)
          );
    if (currentIndex < 0) {
      return;
    }
    const targetIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;
    if (targetIndex < 0 || targetIndex >= accounts.length) {
      return;
    }
    const currentAccount = accounts[currentIndex];
    const targetAccount = accounts[targetIndex];
    const currentSortIndex = getSortIndexValue(currentAccount, currentIndex);
    const targetSortIndex = getSortIndexValue(targetAccount, targetIndex);
    runPinReorderAnimation();
    try {
      await updateAccountSortIndex(currentAccount.id, targetSortIndex);
      await updateAccountSortIndex(targetAccount.id, currentSortIndex);
      loadAccounts();
      showToast(
        `Account moved ${direction === 'up' ? 'up' : 'down'}`,
        'success',
        3000
      );
    } catch (error) {
      console.error('Failed to move account:', error);
      showToast('Failed to move account', 'error', 3000);
    } finally {
      closeContextMenu();
    }
  };

  const openContextMenu = account => {
    selectedAccountRef.current = account;
    setSelectedAccount(account);
    setContextMenuVisible(true);
    Animated.parallel([
      Animated.timing(overlayOpacity, {
        toValue: 1,
        duration: 250,
        useNativeDriver: true,
      }),
      Animated.spring(contentTranslateY, {
        toValue: 0,
        tension: 65,
        friction: 10,
        useNativeDriver: true,
      }),
    ]).start();
  };

  const closeContextMenu = () => {
    Animated.parallel([
      Animated.timing(overlayOpacity, {
        toValue: 0,
        duration: 200,
        useNativeDriver: true,
      }),
      Animated.timing(contentTranslateY, {
        toValue: 300,
        duration: 200,
        useNativeDriver: true,
      }),
    ]).start(() => {
      setContextMenuVisible(false);
      setSelectedAccount(null);
      selectedAccountRef.current = null;
    });
  };
  const handleSetPrimary = async () => {
    const account = selectedAccountRef.current || selectedAccount;
    if (!account) {
      return;
    }
    if (account.account_type !== 'earning') {
      return;
    }
    if (Number(account.is_primary) === 1) {
      closeContextMenu();
      return;
    }
    try {
      await updateAccountPrimary(account.id, true);
      showToast('Primary account updated.', 'success', 3000);
      loadAccounts();
    } catch (error) {
      console.error('Failed to update primary status:', error);
      showToast('Failed to update primary account.', 'error', 3000);
    } finally {
      closeContextMenu();
    }
  };

  const handleDeleteAccount = () => {
    const account = selectedAccountRef.current || selectedAccount;
    if (!account) return;
    const isSavingAccount = account.account_type === 'saving';
    if (isSavingAccount) {
      Alert.alert('Not Allowed', 'Saving account cannot be deleted.');
      closeContextMenu();
      return;
    }
    const isPrimaryEarning =
      account.account_type === 'earning' && Number(account.is_primary) === 1;
    if (isPrimaryEarning) {
      Alert.alert(
        'Primary Account',
        'Primary earning account cannot be deleted. Set another earning account as primary first.'
      );
      closeContextMenu();
      return;
    }
    const balance = Number(account?.balance) || 0;
    if (Math.abs(balance) > 0.000001) {
      Alert.alert(
        'Balance Not Settled',
        'This account balance is not settled. Please settle it to 0 before removing the account.'
      );
      return;
    }
    Alert.alert(
      'Delete Account',
      `Are you sure you want to delete the account "${account.account_name}"? All associated transactions will also be deleted. This action cannot be undone.`,
      [
        {text: 'Cancel', style: 'cancel', onPress: closeContextMenu},
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            try {
              await deleteAccountAndTransactions(account.id);
              showToast('Account deleted successfully', 'success', 3000);
              loadAccounts(); // Refresh the list
            } catch (e) {
              Alert.alert('Error', 'Failed to delete account.');
            } finally {
              closeContextMenu();
            }
          },
        },
      ]
    );
  };

  const handleDeletePress = () => {
    if (deletePressGuardRef.current) {
      return;
    }
    deletePressGuardRef.current = true;
    handleDeleteAccount();
    setTimeout(() => {
      deletePressGuardRef.current = false;
    }, 400);
  };

  const openRenameModal = () => {
    const account = selectedAccountRef.current || selectedAccount;
    if (!account) return;
    setRenameTargetAccount(account);
    setNewAccountName(account?.account_name || ''); // Ensure newAccountName is always a string
    setRenameModalVisible(true);
    closeContextMenu();
    setTimeout(() => {
      renameInputRef.current?.focus();
    }, 600);
  };

  const handleContextMenuPersonalize = useCallback(() => {
    closeContextMenu();
    if (selectedAccount?.id) {
      navigation.navigate('PersonalizeAccount', {accountId: selectedAccount.id});
    }
  }, [closeContextMenu, navigation, selectedAccount?.id]);

  const handleAddToHomeScreen = useCallback(async () => {
    const account = selectedAccountRef.current || selectedAccount;
    const shortcutModule = NativeModules?.AccountShortcut;
    if (!account) {
      return;
    }
    if (!shortcutModule?.addToHomeScreen) {
      showToast('Shortcut feature is not available on this device.', 'error', 3000);
      closeContextMenu();
      return;
    }

    try {
      const created = await shortcutModule.addToHomeScreen(
        String(account.id),
        String(account.account_name || 'Account'),
        String(account.account_type || ''),
        String(account.icon || ''),
        String(account.icon_color || ''),
      );
      if (created) {
        showToast('Added to home screen', 'success', 3000);
      } else {
        showToast('Unable to add shortcut on this launcher.', 'error', 3000);
      }
    } catch (error) {
      console.error('Failed to create home screen shortcut:', error);
      showToast('Failed to add shortcut', 'error', 3000);
    } finally {
      closeContextMenu();
    }
  }, [closeContextMenu, selectedAccount, showToast]);

  const dashboardAccountMenuActions = React.useMemo(
    () =>
      buildDashboardAccountMenuActions({
        selectedAccount,
        onSetPrimary: handleSetPrimary,
        onRename: openRenameModal,
        onDelete: handleDeletePress,
        onPersonalize: handleContextMenuPersonalize,
        onAddToHomeScreen: handleAddToHomeScreen,
      }),
    [
      selectedAccount,
      handleSetPrimary,
      openRenameModal,
      handleDeletePress,
      handleContextMenuPersonalize,
      handleAddToHomeScreen,
    ]
  );

  const closeRenameModal = () => {
    setRenameModalVisible(false);
    setRenameTargetAccount(null);
    setNewAccountName('');
  };

  const handleSaveAccountName = async () => {
    const account = renameTargetAccount || selectedAccountRef.current || selectedAccount;
    if (!account || !newAccountName.trim()) {
      Alert.alert('Invalid Name', 'Account name cannot be empty.');
      return;
    }
    try {
      await renameAccount(account.id, newAccountName.trim());
      showToast('Account renamed successfully', 'success', 3000);
      loadAccounts(); // Refresh the list
    } catch (e) {
      Alert.alert('Error', 'Failed to rename account.');
    } finally {
      closeRenameModal();
    }
  };

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <View style={styles.accountMetricsWrapper}>
          <View style={styles.accountMetricsCard}>
            <View style={styles.dropdownGrid}>
              <View style={styles.dropdownContainer}>
                <Text style={styles.dropdownLabel}>Quick Period</Text>
                <TouchableOpacity
                  style={[
                    styles.dropdown,
                    selectedMonth !== null &&
                      selectedYear !== null &&
                      styles.dropdownDisabled,
                  ]}
                  onPress={() => {
                    if (selectedMonth === null || selectedYear === null) {
                      setBottomSheetContent('quick');
                      setBottomSheetVisible(true);
                    }
                  }}
                  disabled={selectedMonth !== null && selectedYear !== null}>
                  <Text
                    style={[
                      styles.dropdownText,
                      selectedMonth !== null &&
                        selectedYear !== null &&
                        styles.dropdownTextDisabled,
                    ]}>
                    {QUICK_PERIODS.find(p => p.value === quickPeriod)?.label ||
                      'This Month'}
                  </Text>
                  <Icon
                    name="chevron-down"
                    size={16}
                    color={
                      selectedMonth !== null && selectedYear !== null
                        ? '#9CA3AF'
                        : '#6B7280'
                    }
                  />
                </TouchableOpacity>
              </View>
              <View style={styles.dropdownContainer}>
                <Text style={styles.dropdownLabel}>Month</Text>
                <TouchableOpacity
                  style={styles.dropdown}
                  onPress={() => {
                    setBottomSheetContent('month');
                    setBottomSheetVisible(true);
                  }}>
                  <Text style={styles.dropdownText}>
                    {selectedMonth !== null
                      ? MONTHS[selectedMonth].label
                      : 'Month'}
                  </Text>
                  <Icon
                    name="chevron-down"
                    size={16}
                    color="#6B7280"
                  />
                </TouchableOpacity>
              </View>
              <View style={styles.dropdownContainer}>
                <Text style={styles.dropdownLabel}>Year</Text>
                <TouchableOpacity
                  style={styles.dropdown}
                  onPress={() => {
                    setBottomSheetContent('year');
                    setBottomSheetVisible(true);
                  }}>
                  <Text style={styles.dropdownText}>
                    {selectedYear !== null ? selectedYear : 'Year'}
                  </Text>
                  <Icon
                    name="chevron-down"
                    size={16}
                    color="#6B7280"
                  />
                </TouchableOpacity>
              </View>
            </View>
            <View style={styles.accountMetricsRow}>
              <View style={styles.accountMetricThird}>
                <View style={styles.accountMetricLabelRow}>
                  <Text style={styles.accountMetricLabel}>Earning</Text>
                </View>
                <Text
                  style={[
                    styles.accountMetricValue,
                    styles.accountMetricValueIndented,
                    styles.accountMetricPositive,
                  ]}>
                  {formatCurrencyRupee(filteredEarning)}
                </Text>
              </View>
              <View style={styles.accountMetricDivider} />
              <View style={styles.accountMetricThird}>
                <View style={styles.accountMetricLabelRow}>
                  <Text style={styles.accountMetricLabel}>Expenses</Text>
                </View>
                <Text
                  style={[
                    styles.accountMetricValue,
                    styles.accountMetricValueIndented,
                    styles.accountMetricNegative,
                  ]}>
                  {formatCurrencyRupee(filteredWithdrawals)}
                </Text>
              </View>
              <View style={styles.accountMetricDivider} />
              <View style={styles.accountMetricThird}>
                <View style={styles.accountMetricLabelRow}>
                  <Text style={styles.accountMetricLabel}>Net Balance</Text>
                </View>
                <Text
                  style={[
                    styles.accountMetricValue,
                    styles.accountMetricValueIndented,
                  ]}>
                  {formatCurrencyRupee(netBalance)}
                </Text>
              </View>
            </View>
          </View>
        </View>
      </View>
      <ScrollView
        style={styles.scrollView}
        showsVerticalScrollIndicator={false}>
        {/* Earning Accounts */}
        <View style={styles.accountsSection}>
          <Text style={styles.sectionTitle}>Earning Accounts</Text>
          {accounts.length > 0 ? (
            <>
              <View style={styles.accountsList}>
                {accounts
                  .filter(account => account.account_type === 'earning')
                  .map(account => (
                    <TapEffect
                      key={account.id}
                      style={styles.accountItem}
                      onPress={() => {
                        navigation.navigate('AccountDetail', {account});
                      }}
                      onLongPress={() => openContextMenu(account)}>
                      <View style={styles.badgeContainer}>
                        {account.is_primary === 1 && (
                          <View
                            style={[
                              styles.badge,
                              {backgroundColor: colors.text.light},
                            ]}>
                            <Icon name="star" size={12} color={fabExpanded ? colors.error : colors.white} />
                          </View>
                        )}
                      </View>

                      <View style={styles.accountRow}>
                        <View
                          style={[
                            styles.accountIcon,
                            {
                              backgroundColor:
                                account.icon_color || colors.successLight,
                            },
                          ]}>
                          {renderAccountIcon(
                            account.icon || 'trending-up',
                            22,
                            account.icon_color
                              ? colors.white
                              : colors.text.primary
                          )}
                        </View>

                        <View style={styles.accountDetails}>
                          <View style={styles.accountHeader}>
                            <View style={styles.accountHeaderContent}>
                              <Text style={styles.accountName}>
                                {account.account_name}
                              </Text>
                            </View>
                          </View>
                          <Text style={styles.accountBalanceRow}>
                            <Text style={styles.accountBalanceLabel}>
                              Balance{' '}
                            </Text>
                            <Text
                              style={[
                                styles.accountBalanceAmount,
                                account.icon_color && {
                                  color: account.icon_color,
                                },
                              ]}>
                              {formatCurrency(closingAccountBalances[account.id] ?? 0)}
                            </Text>
                          </Text>
                          <Text style={styles.accountDate}>{cardPeriodText}</Text>
                        </View>
                      </View>
                    </TapEffect>
                  ))}
              </View>

              {!hideSavingAccountsOnDashboard && (
                <>
                  <View style={styles.accountsDivider} />
                  <Text style={styles.sectionTitle}>Savings Accounts</Text>
                  <View style={styles.accountsList}>
                    {accounts
                      .filter(account => account.account_type === 'saving')
                      .map(account => (
                        <TapEffect
                          key={account.id}
                          style={styles.accountItem}
                          onPress={() => {
                            navigation.navigate('ExpensesAccountDetail', {account});
                          }}
                          onLongPress={() => openContextMenu(account)}>
                          <View style={styles.badgeContainer} />

                          <View style={styles.accountRow}>
                            <View
                              style={[
                                styles.accountIcon,
                                {
                                  backgroundColor:
                                    account.icon_color || colors.warningLight,
                                },
                              ]}>
                              {renderAccountIcon(
                                account.icon || 'wallet',
                                22,
                                account.icon_color
                                  ? colors.white
                                  : colors.text.primary
                              )}
                            </View>

                            <View style={styles.accountDetails}>
                              <View style={styles.accountHeader}>
                                <View style={styles.accountHeaderContent}>
                                  <Text style={styles.accountName}>
                                    {account.account_name}
                                  </Text>
                                </View>
                              </View>
                              <Text style={styles.accountBalanceRow}>
                                <Text style={styles.accountBalanceLabel}>
                                  Savings{' '}
                                </Text>
                                <Text
                                  style={[
                                    styles.accountBalanceAmount,
                                    account.icon_color && {
                                      color: account.icon_color,
                                    },
                                  ]}>
                                  {formatCurrency(closingAccountBalances[account.id] ?? 0)}
                                </Text>
                              </Text>
                              <Text style={styles.accountDate}>{cardPeriodText}</Text>
                            </View>
                          </View>
                        </TapEffect>
                      ))}
                  </View>
                </>
              )}

              <View style={styles.accountsDivider} />

              <Text style={styles.sectionTitle}>Expenses Accounts</Text>
              <View style={styles.accountsList}>
                {accounts
                  .filter(account => account.account_type === 'expenses')
                  .map(account => (
                    <TapEffect
                      key={account.id}
                      style={styles.accountItem}
                      onPress={() => {
                        navigation.navigate('ExpensesAccountDetail', {account});
                      }}
                      onLongPress={() => openContextMenu(account)}>
                      <View style={styles.badgeContainer} />

                      <View style={styles.accountRow}>
                        <View
                          style={[
                            styles.accountIcon,
                            {
                              backgroundColor:
                                account.icon_color || colors.warningLight,
                            },
                          ]}>
                          {renderAccountIcon(
                            account.icon || 'wallet',
                            22,
                            account.icon_color
                              ? colors.white
                              : colors.text.primary
                          )}
                        </View>

                        <View style={styles.accountDetails}>
                          <View style={styles.accountHeader}>
                            <View style={styles.accountHeaderContent}>
                              <Text style={styles.accountName}>
                                {account.account_name}
                              </Text>
                            </View>
                          </View>
                          <Text style={styles.accountBalanceRow}>
                            <Text style={styles.accountBalanceLabel}>
                              Expenses{' '}
                            </Text>
                            <Text
                              style={[
                                styles.accountBalanceAmount,
                                account.icon_color && {
                                  color: account.icon_color,
                                },
                              ]}>
                              {formatCurrency(periodAccountExpenses[account.id] ?? 0)}
                            </Text>
                          </Text>
                          <Text style={styles.accountDate}>{cardPeriodText}</Text>
                        </View>
                      </View>
                    </TapEffect>
                  ))}
              </View>
            </>
          ) : (
            <View style={styles.emptyAccounts}>
              <Icon name="wallet-outline" size={48} color={colors.border} />
              <Text style={styles.emptyText}>No accounts yet</Text>
              <Text style={styles.emptySubtext}>
                Create your first account to get started
              </Text>
            </View>
          )}
        </View>
      </ScrollView>

      

      {fabExpanded && (
        <TouchableOpacity
          style={styles.fabBackdrop}
          activeOpacity={1}
          onPress={closeFabMenu}
        />
      )}

      <Animated.View
        pointerEvents={fabExpanded ? 'auto' : 'none'}
        style={[
          styles.fabActions,
          {bottom: fabActionsBottomOffset},
          {
            opacity: fabAnim,
            transform: [
              {
                translateY: fabAnim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [16, 0],
                }),
              },
            ],
          },
        ]}>
        <TouchableOpacity
          style={styles.fabActionRow}
          onPress={() => openAddAccount('earning')}>
          <Text style={styles.fabActionLabel}>Add Earning Account</Text>
          <View style={[styles.fabActionButton, styles.fabActionButtonEarning]}>
            <Icon name="person-add" size={20} color={colors.white} />
          </View>
        </TouchableOpacity>
        <TouchableOpacity
          style={styles.fabActionRow}
          onPress={() => openAddAccount('expenses')}>
          <Text style={styles.fabActionLabel}>Add Expenses Account</Text>
          <View style={[styles.fabActionButton, styles.fabActionButtonExpenses]}>
            <Icon name="person-add" size={20} color={colors.white} />
          </View>
        </TouchableOpacity>
      </Animated.View>
      <TouchableOpacity
        ref={fabRef}
        style={[styles.fab, {bottom: fabBottomOffset}, fabExpanded && styles.fabOpen]}
        onPress={handleAddAccountPress}>
        <Icon name={fabExpanded ? 'close' : 'person-add'} size={22} color={colors.white} />
      </TouchableOpacity>

      {/* Bottom Sheet for Period/Month/Year */}
      <BottomSheet
        visible={isBottomSheetVisible}
        onClose={() => setBottomSheetVisible(false)}>
        {renderBottomSheetContent()}
      </BottomSheet>

      {/* Context Menu Modal */}
      <Modal
        visible={contextMenuVisible}
        transparent
        animationType="none"
        statusBarTranslucent
        onRequestClose={closeContextMenu}>
        <Animated.View
          style={[
            styles.contextMenuOverlay,
            {opacity: overlayOpacity},
          ]}>
          <TouchableOpacity
            style={styles.contextMenuOverlayTouchable}
            activeOpacity={1}
            onPress={closeContextMenu}
          />
          <Animated.View
            style={[
              styles.contextMenuContainer,
              {transform: [{translateY: contentTranslateY}]},
            ]}>
            <View style={styles.contextMenuHeader}>
              <Text style={styles.contextMenuTitle}>
                {selectedAccount?.account_name}
              </Text>
            </View>
            {canMoveWithinType && (
              <>
                <TouchableOpacity
                  style={[
                    styles.contextMenuItem,
                    isMoveUpDisabled && styles.contextMenuItemDisabled,
                  ]}
                  hitSlop={{top: 6, bottom: 6, left: 8, right: 8}}
                  disabled={isMoveUpDisabled}
                  onPress={() => moveSelectedAccount('up')}>
                  <Icon
                    name="arrow-up"
                    size={22}
                    color={
                      isMoveUpDisabled ? colors.text.light : colors.text.primary
                    }
                  />
                  <Text
                    style={[
                      styles.contextMenuItemText,
                      isMoveUpDisabled && styles.contextMenuItemTextDisabled,
                    ]}>
                    Move Up
                  </Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[
                    styles.contextMenuItem,
                    isMoveDownDisabled && styles.contextMenuItemDisabled,
                  ]}
                  hitSlop={{top: 6, bottom: 6, left: 8, right: 8}}
                  disabled={isMoveDownDisabled}
                  onPress={() => moveSelectedAccount('down')}>
                  <Icon
                    name="arrow-down"
                    size={22}
                    color={
                      isMoveDownDisabled
                        ? colors.text.light
                        : colors.text.primary
                    }
                  />
                  <Text
                    style={[
                      styles.contextMenuItemText,
                      isMoveDownDisabled &&
                        styles.contextMenuItemTextDisabled,
                    ]}>
                    Move Down
                  </Text>
                </TouchableOpacity>
              </>
            )}
            {dashboardAccountMenuActions.map(action => (
              <TouchableOpacity
                key={action.id}
                style={[
                  styles.contextMenuItem,
                  action.disabled && styles.contextMenuItemDisabled,
                ]}
                hitSlop={{top: 6, bottom: 6, left: 8, right: 8}}
                onPressIn={action.id === 'delete' ? handleDeletePress : undefined}
                onPress={action.onPress}
                disabled={action.disabled}>
                <Icon
                  name={action.icon}
                  size={22}
                  color={
                    action.variant === 'danger'
                      ? colors.error
                      : action.selected
                        ? '#10B981'
                        : colors.text.primary
                  }
                />
                <Text
                  style={[
                    styles.contextMenuItemText,
                    action.variant === 'danger' && {color: colors.error},
                    action.selected && styles.contextMenuItemTextSelected,
                  ]}>
                  {action.label}
                </Text>
                {action.trailingIcon ? (
                  <Icon name={action.trailingIcon} size={18} color="#10B981" />
                ) : null}
              </TouchableOpacity>
            ))}
            <TouchableOpacity
              style={[styles.contextMenuItem, styles.contextMenuItemCancel]}
              hitSlop={{top: 6, bottom: 6, left: 8, right: 8}}
              onPress={closeContextMenu}>
              <Icon name="close" size={22} color={colors.text.secondary} />
              <Text style={styles.contextMenuItemTextCancel}>Cancel</Text>
            </TouchableOpacity>
          </Animated.View>
        </Animated.View>
      </Modal>

      {/* Rename Account Modal */}
      <RenameAccountModal
        visible={renameModalVisible}
        value={newAccountName}
        onChange={setNewAccountName}
        onSave={handleSaveAccountName}
        onClose={closeRenameModal}
        loading={false}
        inputRef={renameInputRef}
        styles={renameModalStyles}
      />

      <SetupRequirePopup
        visible={showSetupPopup}
        title="Complete your basic details"
        description="Finish profile setup to unlock all features of app."
        primaryText="Update Profile Setup"
        secondaryText="Remind me later"
        showNeverShowCheckbox={showStartupNeverShowCheckbox}
        neverShowChecked={startupNeverShowChecked}
        neverShowLabel="Never show this msg again"
        onNeverShowToggle={handleToggleStartupNeverShow}
        onPrimaryPress={handleOpenProfileSetup}
        onSecondaryPress={handleRemindLater}
        onClose={handleRemindLater}
      />

    </View>
  );
};

