const AnimatedTouchableOpacity = Animated.createAnimatedComponent(TouchableOpacity);
import BottomSheet from '../components/BottomSheet';
import {
  initTransactionsDatabase,
  createTransaction,
  deleteTransaction,
  getTransactionsByAccount,
  calculateAccountBalance,
  updateTransactionAmount,
  updateTransactionRemark,
  deleteTransactionsByAccount,
} from '../services/transactionsDatabase';
import {canWithdrawAtTimestampWithEntries} from '../services/transactionTimeline';
import {
  initRecurringDatabase,
  createRecurringSchedule,
  processDueSchedules,
} from '../services/recurringDatabase';
import {
  deleteAccount,
  getAllAccounts,
  getAccountsByType,
  renameAccount,
  updateAccountPrimary,
} from '../services/accountsDatabase';
import {
  ensureOffModeFirstTransactionConsent,
  getStrictEcoEnabled,
} from '../services/strictEcoService';

const SCHEDULE_TYPES = [
  {label: 'Once', value: 'once'},
  {label: 'Weekly', value: 'weekly'},
  {label: '2 Weeks', value: '2weeks'},
  {label: 'Monthly', value: 'monthly'},
  {label: '2 Months', value: '2months'},
  {label: '3 Months', value: '3months'},
  {label: '6 Months', value: '6months'},
];

const DAYS_OF_WEEK = [
  {label: 'Monday', value: 'monday'},
  {label: 'Tuesday', value: 'tuesday'},
  {label: 'Wednesday', value: 'wednesday'},
  {label: 'Thursday', value: 'thursday'},
  {label: 'Friday', value: 'friday'},
  {label: 'Saturday', value: 'saturday'},
  {label: 'Sunday', value: 'sunday'},
];

const DATES_OF_MONTH = Array.from({length: 31}, (_, i) => ({
  label: `${i + 1}`,
