        title: 'Proceed in Free Flow mode?',
        message:
          'If you create a transaction while Strict Eco is OFF, you must settle earning/expenses accounts (0 balance) before enabling Strict Eco again.',
      });
      if (!hasConsent) {
        return false;
      }
      const amountValue = parseFloat(nextAmount);
      if (isFutureEntryDate(nextEntryDate)) {
        showToast('Future entry not allowed.', 'error');
        return false;
      }
      const entryTimestamp = nextEntryDate.getTime();

      if (scheduleType === 'once') {
        // Create immediate transaction
        await createTransaction(account.id, amountValue, remark, entryTimestamp);
        showToast('Amount added successfully', 'success');
      } else {
        // Create recurring schedule
        const needsDay = scheduleType === 'weekly' || scheduleType === '2weeks';
        const needsDate = ['monthly', '2months', '3months', '6months'].includes(scheduleType);

        await createRecurringSchedule(
          account.id,
          amountValue,
          remark,
          scheduleType,
          needsDay ? selectedDay : null,
          needsDate ? selectedDate : null
        );

        showToast(`Recurring ${scheduleType} schedule created.`, 'success');
      }

      // Reset form
      setAmount('');
      setScheduleType('once');
      setAddNote('');

      // Reload transactions
      loadTransactions();
      return true;
    } catch (error) {
      console.error('Failed to add entry:', error);
      Alert.alert('Error', 'Failed to add entry. Please try again.');
      return false;
    } finally {
      setLoading(false);
    }
  };

  const handleWithdraw = async (overrides = {}) => {
    const nextAmount = overrides.amount ?? withdrawAmount;
    const nextEntryDate = overrides.entryDate ?? entryDate;
    const nextReceiptUri = overrides.receiptUri ?? withdrawReceiptUri;

    if (!nextAmount || parseFloat(nextAmount) <= 0) {
      showToast('Please enter a valid amount.', 'error');
      return false;
    }

    const remark = (overrides.note ?? withdrawNote).trim();

    setLoading(true);
    try {
      const hasConsent = await ensureOffModeFirstTransactionConsent({
        title: 'Proceed in Free Flow mode?',
        message:
          'If you create a transaction while Strict Eco is OFF, you must settle earning/expenses accounts (0 balance) before enabling Strict Eco again.',
      });
      if (!hasConsent) {
        return false;
      }
      const strictEcoEnabled = await getStrictEcoEnabled();
      const amountValue = Math.abs(parseFloat(nextAmount));
      if (isFutureEntryDate(nextEntryDate)) {
        showToast('Future entry not allowed.', 'error');
        return false;
      }
      const entryTimestamp = nextEntryDate.getTime();
      if (strictEcoEnabled) {
        if (!canWithdrawAtTimestamp(amountValue, entryTimestamp)) {
          showToast(
            'Withdrawal not allowed. Balance was insufficient at that time.',
