  const isTransferTransaction = txn => {
    const entryKind = String(txn?.entry_kind || '').trim().toLowerCase();
    if (entryKind) {
      return (
        entryKind === 'transfer' ||
        entryKind === 'legacy_transfer' ||
        entryKind === 'request'
      );
    }
    const remark = String(txn?.remark || '').trim().toLowerCase();
    return (
      remark.startsWith('transferred to ') ||
      remark.startsWith('transferred from ') ||
      remark.startsWith('requested to ') ||
      remark.startsWith('requested from ') ||
      remark.startsWith('requested by ')
    );
  };

  const isEarningWithdrawLogTransaction = txn => {
    const entryKind = String(txn?.entry_kind || '').trim().toLowerCase();
    if (entryKind) {
      return entryKind === 'earning_withdraw_log';
    }
    const remark = String(txn?.remark || '').trim().toLowerCase();
    const amount = Number(txn?.amount) || 0;
    return (
      Math.abs(amount) < 0.000001 &&
      remark.startsWith(EARNING_WITHDRAW_LOG_TOKEN)
    );
  };

  const formatEarningWithdrawLogRemark = remarkValue => {
    const raw = String(remarkValue || '').trim();
    if (!raw) {
      return '';
    }
    if (!raw.toLowerCase().startsWith(EARNING_WITHDRAW_LOG_TOKEN)) {
      return raw;
    }
    return raw.slice(EARNING_WITHDRAW_LOG_TOKEN.length).trim();
  };

  const formatTransferTimelineRemark = txn => {
    const remark = String(txn?.remark || '').trim();
    const amount = Math.abs(Number(txn?.amount) || 0);
    const amountLabel = formatCurrency(amount);
    if (!remark) {
      return `Transfer ${amountLabel}`;
    }

    const lower = remark.toLowerCase();
    const directionByPrefix = {
      'transferred to ': 'to',
      'transferred from ': 'from',
      'requested by ': 'to',
      'requested to ': 'to',
      'requested from ': 'from',
    };
    const prefixes = Object.keys(directionByPrefix);
    const matchedPrefix = prefixes.find(prefix => lower.startsWith(prefix));
    if (!matchedPrefix) {
      return `Transfer ${amountLabel}`;
    }

    const remainder = remark.slice(matchedPrefix.length).trim();
    if (!remainder) {
      return `Transfer ${amountLabel}`;
    }

    const separatorIndex = remainder.indexOf(' - ');
    const accountName =
      separatorIndex === -1
        ? remainder
        : remainder.slice(0, separatorIndex).trim();
    const note =
      separatorIndex === -1 ? '' : remainder.slice(separatorIndex + 3).trim();
    const direction = directionByPrefix[matchedPrefix] || 'to';

    if (note) {
      return `Transfer ${amountLabel} ${direction} ${accountName} - ${note}`;
    }
    return `Transfer ${amountLabel} ${direction} ${accountName}`;
  };

  const formatTimelineEntryRemark = txn => {
    if (isEarningWithdrawLogTransaction(txn)) {
      return formatEarningWithdrawLogRemark(txn?.remark);
    }
    if (isTimelineTransferTransaction(txn)) {
      return formatTransferTimelineRemark(txn);
    }
    return String(txn?.remark || '').trim();
  };

  const isTimelineTransferTransaction = txn => {
    const entryKind = String(txn?.entry_kind || '').trim().toLowerCase();
    if (entryKind) {
      return (
        entryKind === 'transfer' ||
        entryKind === 'legacy_transfer' ||
        entryKind === 'request'
      );
    }
    const remark = String(txn?.remark || '').trim().toLowerCase();
    return (
      remark.startsWith('transferred to ') ||
      remark.startsWith('transferred from ') ||
      remark.startsWith('requested to ') ||
      remark.startsWith('requested from ') ||
      remark.startsWith('requested by ')
    );
  };

  const isActualTransferTransaction = txn => {
    const entryKind = String(txn?.entry_kind || '').trim().toLowerCase();
    if (entryKind) {
      return entryKind === 'transfer';
    }
    const remark = String(txn?.remark || '').trim().toLowerCase();
    return (
      remark.startsWith('transferred to ') ||
      remark.startsWith('transferred from ')
    );
  };

  const getLinkedRemarkType = remarkValue => {
    const remark = String(remarkValue || '').trim().toLowerCase();
    if (remark.startsWith('transferred to ')) {
      return 'transfer_to';
    }
    if (remark.startsWith('transferred from ')) {
      return 'transfer_from';
    }
    if (remark.startsWith('requested by ')) {
      return 'request_by';
    }
    if (remark.startsWith('requested from ')) {
      return 'request_from';
    }
    if (remark.startsWith('requested to ')) {
      return 'request_to';
    }
    return null;
  };

  const extractLinkedAccountName = remarkValue => {
    const remark = String(remarkValue || '').trim();
    if (!remark) {
      return '';
    }
    const lower = remark.toLowerCase();
    const prefixes = [
      'transferred to ',
      'transferred from ',
      'requested by ',
      'requested from ',
      'requested to ',
    ];
    const prefix = prefixes.find(item => lower.startsWith(item));
    if (!prefix) {
      return '';
    }
    const withoutPrefix = remark.slice(prefix.length).trim();
    if (!withoutPrefix) {
      return '';
    }
    const separatorIndex = withoutPrefix.indexOf(' - ');
    const name =
      separatorIndex === -1
        ? withoutPrefix
        : withoutPrefix.slice(0, separatorIndex);
    return name.trim().toLowerCase();
  };

  const isLinkedRemarkPair = (sourceType, candidateType) => {
    if (!sourceType || !candidateType) {
      return true;
    }
    if (sourceType === 'transfer_to') {
      return candidateType === 'transfer_from';
    }
    if (sourceType === 'transfer_from') {
      return candidateType === 'transfer_to';
    }
    if (sourceType === 'request_by') {
      return candidateType === 'request_from' || candidateType === 'request_to';
    }
    if (sourceType === 'request_from') {
      return candidateType === 'request_by';
    }
    if (sourceType === 'request_to') {
      return candidateType === 'request_by';
    }
    return true;
  };

  const isLockedTransaction = txn => isTransferTransaction(txn);

  const getLinkedExpensesTransaction = txn => {
    if (!txn) {
      return null;
    }
    const remark = String(txn.remark || '').trim();
    if (!remark) {
      return null;
    }
    if (!isLockedTransaction(txn)) {
      return null;
    }
    const amountValue = Math.abs(Number(txn.amount) || 0);
    if (!amountValue) {
      return null;
    }
    const txnAmount = Number(txn.amount) || 0;
    const txnType = getLinkedRemarkType(remark);
    const preferredLinkedName = extractLinkedAccountName(remark);
    const linkedAccounts = [
      ...getAccountsByType('expenses'),
      ...getAccountsByType('saving'),
    ];

    const pickBestMatch = accountsList => {
      let bestMatch = null;
      let bestDelta = Number.POSITIVE_INFINITY;
      accountsList.forEach(linkedAccount => {
        const linkedTxns = getTransactionsByAccount(linkedAccount.id);
        linkedTxns.forEach(entry => {
          if (Number(entry?.is_deleted) === 1) {
            return;
          }
          const entryAmountNumeric = Number(entry.amount) || 0;
          const entryAmountAbs = Math.abs(entryAmountNumeric);
          if (entryAmountAbs !== amountValue) {
            return;
          }
          if (
            txnAmount !== 0 &&
            entryAmountNumeric !== 0 &&
            Math.sign(txnAmount) === Math.sign(entryAmountNumeric)
          ) {
            return;
          }
          const entryType = getLinkedRemarkType(entry.remark);
          if (!isLinkedRemarkPair(txnType, entryType)) {
            return;
          }
          const delta = Math.abs(
            Number(entry.transaction_date) - Number(txn.transaction_date)
          );
          if (
            delta < bestDelta ||
            (delta === bestDelta &&
              String(entry.id).localeCompare(String(bestMatch?.id || '')) < 0)
          ) {
            bestDelta = delta;
            bestMatch = entry;
          }
        });
      });
      return bestMatch;
    };

    const preferredAccounts =
      preferredLinkedName.length > 0
        ? linkedAccounts.filter(
            item =>
              String(item?.account_name || '').trim().toLowerCase() ===
              preferredLinkedName
          )
        : [];
    return pickBestMatch(preferredAccounts) || pickBestMatch(linkedAccounts);
  };

  const openRenameModal = () => {
    setNewAccountName(account.account_name || '');
    setRenameModalVisible(true);
    setTimeout(() => {
      renameInputRef.current?.focus();
