    }
    return formatCurrency(Number(value) || 0);
  };

  const buildDeleteHistory = txn => {
    const editCount = Number(txn?.edit_count) || 0;
    if (!editCount) {
      return null;
    }
    const history = parseEditHistory(txn);
    const amountAbs = Math.abs(Number(txn?.amount) || 0);
    const base = history.length ? history : [amountAbs];
    return JSON.stringify([...base, 'Deleted']);
  };

  const getLatestTransactionId = () => {
    if (!transactions || transactions.length === 0) {
      return null;
    }
    let latest = null;
    for (let i = 0; i < transactions.length; i += 1) {
      const txn = transactions[i];
      if (Number(txn.is_deleted) === 1) {
        continue;
      }
      const currentDate = Number(txn.transaction_date) || 0;
      const latestDate = Number(latest?.transaction_date) || 0;
      if (
        !latest ||
        currentDate > latestDate ||
        (currentDate === latestDate && Number(txn.id) > Number(latest.id))
      ) {
        latest = txn;
      }
    }
    return latest?.id ?? null;
  };

  const canApplyAmountEditWithEntries = (entries, transactionId, nextAmount) => {
    if (!transactionId) {
      return false;
    }
    if (!Number.isFinite(nextAmount)) {
      return false;
    }
    const timeline = entries
      .filter(entry => Number(entry?.is_deleted) !== 1)
      .map(entry =>
        entry.id === transactionId ? {...entry, amount: nextAmount} : entry
      )
      .sort(compareTimelineEntries);

    let running = 0;
    for (const entry of timeline) {
      running += Number(entry.amount) || 0;
      if (running < 0) {
        return false;
      }
    }
    return true;
  };

  const canDeleteWithoutNegative = (entries, transactionId) => {
    if (!transactionId) {
      return false;
    }
    const targetId = String(transactionId);
    const activeEntries = entries.filter(entry => Number(entry?.is_deleted) !== 1);
    const timeline = activeEntries
      .filter(entry => String(entry.id) !== targetId)
      .sort(compareTimelineEntries);

    if (__DEV__) {
      const removedCount = activeEntries.length - timeline.length;
      console.log('[EARN-DELETE][CHECK-START]', {
        targetId,
        inputCount: entries.length,
        activeCount: activeEntries.length,
        timelineCount: timeline.length,
        removedCount,
      });
      if (removedCount !== 1) {
        console.log('[EARN-DELETE][ID-MISMATCH-SUSPECT]', {
          targetId,
          activeIdsSample: activeEntries.slice(-8).map(item => ({
            id: item.id,
            idType: typeof item.id,
            amount: Number(item.amount) || 0,
            ts: Number(item.transaction_date) || 0,
          })),
        });
      }
    }

    let running = 0;
    let minRunning = Number.POSITIVE_INFINITY;
    let firstNegativeIndex = -1;
    let firstNegativeEntry = null;
    for (let index = 0; index < timeline.length; index += 1) {
      const entry = timeline[index];
      running += Number(entry.amount) || 0;
      if (running < minRunning) {
        minRunning = running;
      }
      if (running < 0 && firstNegativeIndex === -1) {
        firstNegativeIndex = index;
        firstNegativeEntry = entry;
      }
      if (running < 0) {
        if (__DEV__) {
          const start = Math.max(0, index - 2);
          const end = Math.min(timeline.length, index + 3);
          console.log('[EARN-DELETE][CHECK-FAILED]', {
            targetId,
            firstNegativeIndex,
            minRunning,
            firstNegativeEntry: firstNegativeEntry
              ? {
                  id: firstNegativeEntry.id,
                  amount: Number(firstNegativeEntry.amount) || 0,
                  ts: Number(firstNegativeEntry.transaction_date) || 0,
                }
              : null,
            nearbyEntries: timeline.slice(start, end).map(item => ({
              id: item.id,
              amount: Number(item.amount) || 0,
              ts: Number(item.transaction_date) || 0,
            })),
          });
        }
        return false;
      }
    }
    if (__DEV__) {
      console.log('[EARN-DELETE][CHECK-PASSED]', {
        targetId,
        minRunning,
        finalRunning: running,
      });
    }
    return true;
  };

  const canEditAmount = txn => {
    if (!txn) {
      return false;
    }
    if (isEarningWithdrawLogTransaction(txn)) {
      return false;
    }
    if (Number(txn.is_deleted) === 1) {
      return false;
    }
    const latestId = getLatestTransactionId();
    if (!latestId || txn.id !== latestId) {
      return false;
    }
    if (isTransferTransaction(txn) && !isActualTransferTransaction(txn)) {
      return false;
    }
    const editCount = Number(txn.edit_count) || 0;
    if (editCount >= 3) {
      return false;
    }
    const amount = Number(txn.amount);
    return Number.isFinite(amount);
  };

  const canDeleteTransaction = txn => {
    if (!txn) {
      return false;
    }
    if (isEarningWithdrawLogTransaction(txn)) {
      return false;
    }
    if (Number(txn.is_deleted) === 1) {
      return false;
    }
    const latestId = getLatestTransactionId();
    if (!latestId || txn.id !== latestId) {
      return false;
    }
    const amount = Number(txn.amount);
    return Number.isFinite(amount);
  };

  const openTransactionMenu = txn => {
    setSelectedTransaction(txn);
    setOptionsVisible(true);
  };

  const isDeletedTransaction = txn => Number(txn?.is_deleted) === 1;

  const handleUpdateAmount = async () => {
    if (!selectedTransaction) {
      return;
    }
    const parsedAmount = parseFloat(
      String(editAmount).replace(/[^0-9.]/g, '')
    );
    if (!parsedAmount || parsedAmount <= 0) {
      showToast('Please enter a valid amount.', 'error');
      return;
    }
    const editCount = Number(selectedTransaction.edit_count) || 0;
    if (editCount >= 3) {
      showToast('Edit limit reached.', 'error');
      return;
    }
    if (Number(selectedTransaction.amount) < 0) {
      const currentAbs = Math.abs(Number(selectedTransaction.amount) || 0);
      const availableBalance = totalBalance + currentAbs;
      if (parsedAmount > availableBalance) {
        showToast('Balance is low. Add amount first to withdraw.', 'error');
        return;
      }
    }
    setLoading(true);
    try {
      const nextAmount =
        Number(selectedTransaction.amount) < 0 ? -parsedAmount : parsedAmount;
      const linkedTransfer = isActualTransferTransaction(selectedTransaction)
        ? getLinkedExpensesTransaction(selectedTransaction)
        : null;
      if (isActualTransferTransaction(selectedTransaction)) {
        if (!linkedTransfer) {
          showToast(
            'Linked transfer entry not found. Unable to edit amount.',
            'error'
          );
          return;
        }
        const linkedEditCount = Number(linkedTransfer.edit_count) || 0;
        if (linkedEditCount >= 3) {
          showToast('Edit limit reached for linked entry.', 'error');
          return;
        }
        const linkedNextAmount = -nextAmount;
        const linkedTransactions = getTransactionsByAccount(
          linkedTransfer.account_id
        );
        if (
          !canApplyAmountEditWithEntries(
            linkedTransactions,
            linkedTransfer.id,
            linkedNextAmount
          )
        ) {
          showToast(
            'Edit not allowed. Linked account balance was insufficient at that time.',
            'error'
          );
          return;
        }
      }
      if (!canApplyAmountEdit(selectedTransaction.id, nextAmount)) {
        showToast(
          'Edit not allowed. Balance was insufficient at that time.',
          'error'
        );
        return;
      }
      const currentHistory = parseEditHistory(selectedTransaction);
      const originalAbs = Math.abs(Number(selectedTransaction.amount) || 0);
      const nextAbs = Math.abs(nextAmount);
      const nextHistory =
        currentHistory.length > 0
          ? [...currentHistory, nextAbs]
          : [originalAbs, nextAbs];
      await updateTransactionAmount(
        selectedTransaction.id,
        account.id,
        nextAmount,
        JSON.stringify(nextHistory),
        editCount + 1
      );
      if (isActualTransferTransaction(selectedTransaction) && linkedTransfer) {
          const linkedNextAmount = -nextAmount;
          const linkedHistory = parseEditHistory(linkedTransfer);
          const linkedOriginalAbs = Math.abs(
            Number(linkedTransfer.amount) || 0
          );
          const linkedNextAbs = Math.abs(linkedNextAmount);
          const linkedNextHistory =
            linkedHistory.length > 0
              ? [...linkedHistory, linkedNextAbs]
              : [linkedOriginalAbs, linkedNextAbs];
          await updateTransactionAmount(
            linkedTransfer.id,
            linkedTransfer.account_id,
            linkedNextAmount,
            JSON.stringify(linkedNextHistory),
            (Number(linkedTransfer.edit_count) || 0) + 1
          );
      }
      const remainingEdits = Math.max(0, 2 - editCount);
      showToast(`${remainingEdits} edits remaining.`, 'success');
      setEditAmountVisible(false);
      setSelectedTransaction(null);
      setEditAmount('');
      loadTransactions();
    } catch (error) {
      console.error('Failed to update amount:', error);
      Alert.alert('Error', 'Failed to update amount. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateRemark = async () => {
    if (!selectedTransaction) {
      return;
    }
    setLoading(true);
    try {
      await updateTransactionRemark(selectedTransaction.id, editRemark.trim());
      setEditRemarkVisible(false);
      setSelectedTransaction(null);
      setEditRemark('');
      loadTransactions();
    } catch (error) {
      console.error('Failed to update remark:', error);
      Alert.alert('Error', 'Failed to update remark. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = value => {
    return `${currencySymbol} ${value.toLocaleString('en-IN')}`;
  };

  const formatEntryDate = value => {
    return value.toLocaleDateString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    });
  };

  const formatEntryTime = value => {
    return value.toLocaleTimeString('en-IN', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const handleEntryDateChange = (event, selectedDate) => {
    setShowEntryDatePicker(false);
    if (event?.type === 'dismissed' || !selectedDate) {
      return;
    }
    const updated = new Date(entryDate);
    updated.setFullYear(
      selectedDate.getFullYear(),
      selectedDate.getMonth(),
      selectedDate.getDate()
    );
    updated.setSeconds(0, 0);
    if (isFutureEntryDate(updated)) {
      showToast('Future date not allowed.', 'error');
      setEntryDate(new Date());
      return;
    }
    setEntryDate(updated);
  };

  const handleEntryTimeChange = (event, selectedDate) => {
    setShowEntryTimePicker(false);
    if (event?.type === 'dismissed' || !selectedDate) {
      return;
    }
    const updated = new Date(entryDate);
    updated.setHours(selectedDate.getHours(), selectedDate.getMinutes(), 0, 0);
    if (isFutureEntryDate(updated)) {
      showToast('Future time not allowed.', 'error');
      setEntryDate(new Date());
      return;
    }
    setEntryDate(updated);
  };

  const formatDateTime = timestamp => {
    const date = new Date(timestamp);
    return date.toLocaleString('en-IN', {
      day: 'numeric',
      month: 'short',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true,
    });
  };

  const formatDateLabel = timestamp => {
    const date = new Date(timestamp);
    return date.toLocaleDateString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    });
  };

  const formatTimeLabel = timestamp => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('en-IN', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const calculateQuickPeriodData = period => {
    const now = new Date();
    let startTime = now.getTime() - 30 * 24 * 60 * 60 * 1000;
    let endTime = null;

    switch (period) {
      case '1week': {
        const start = new Date(now);
        start.setDate(now.getDate() - 4);
        start.setHours(0, 0, 0, 0);
        startTime = start.getTime();
        break;
      }
      case '10days': {
        const start = new Date(now);
        start.setDate(now.getDate() - 9);
        start.setHours(0, 0, 0, 0);
        startTime = start.getTime();
        break;
      }
      case '15days': {
        const start = new Date(now);
        start.setDate(now.getDate() - 14);
        start.setHours(0, 0, 0, 0);
        startTime = start.getTime();
        break;
      }
      case '30days': {
        const start = new Date(now);
        start.setDate(now.getDate() - 29);
        start.setHours(0, 0, 0, 0);
        startTime = start.getTime();
        break;
      }
      case '1month': {
        const range = getMonthlyRangeFromStartDay(monthStartDay, now);
        startTime = range.startTime;
        endTime = range.endTime;
        break;
      }
      case '3months':
        startTime = now.getTime() - 90 * 24 * 60 * 60 * 1000;
        break;
      case '6months':
        startTime = now.getTime() - 180 * 24 * 60 * 60 * 1000;
        break;
      case '1year':
        startTime = now.getTime() - 365 * 24 * 60 * 60 * 1000;
        break;
      default:
        startTime = now.getTime() - 30 * 24 * 60 * 60 * 1000;
    }

    let added = 0;
    let withdrawals = 0;
    const filtered = [];

    transactions.forEach(txn => {
      if (Number(txn.is_deleted) === 1) {
        return;
      }
      if (
        txn.transaction_date >= startTime &&
        (endTime === null || txn.transaction_date <= endTime)
      ) {
        const amount = Number(txn.amount) || 0;
        if (amount > 0) {
          added += amount;
        } else if (amount < 0) {
          withdrawals += Math.abs(amount);
        }
        filtered.push(txn);
      }
    });

    setFilteredAdded(added);
    setFilteredWithdrawals(withdrawals);
    setFilteredTransactions(filtered);
  };

  const calculateMonthYearData = (month, year) => {
    if (month === null || year === null) {
      return;
    }

    const {startTime, endTime} = getMonthYearRange(
      month,
      year,
      monthStartDay
    );
    let added = 0;
    let withdrawals = 0;
    const filtered = [];

    transactions.forEach(txn => {
      if (Number(txn.is_deleted) === 1) {
        return;
      }
      if (
        txn.transaction_date >= startTime &&
        txn.transaction_date <= endTime
      ) {
        const amount = Number(txn.amount) || 0;
        if (amount > 0) {
          added += amount;
        } else if (amount < 0) {
          withdrawals += Math.abs(amount);
        }
        filtered.push(txn);
      }
    });

    setFilteredAdded(added);
    setFilteredWithdrawals(withdrawals);
    setFilteredTransactions(filtered);
  };

  const updateFilteredData = () => {
    setIsFiltering(true);

    if (selectedMonth !== null && selectedYear !== null) {
      calculateMonthYearData(selectedMonth, selectedYear);
    } else {
      calculateQuickPeriodData(quickPeriod);
    }
    setIsFiltering(false);
    setHasAppliedFilter(true);
  };

  const handleQuickPeriodSelect = period => {
    setQuickPeriod(period);
    setSelectedMonth(null);
    setSelectedYear(null);
    setBottomSheetVisible(false);
  };

  const handleMonthSelect = month => {
    setSelectedMonth(month);
    setBottomSheetVisible(false);
  };

  const handleYearSelect = year => {
    setSelectedYear(year);
    setBottomSheetVisible(false);
  };

  const renderBottomSheetContent = () => {
    if (bottomSheetContent === 'quick') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Period</Text>
          {QUICK_PERIODS.map(period => (
            <TouchableOpacity
              key={period.value}
              style={[
                styles.periodDropdownOption,
                quickPeriod === period.value && styles.periodDropdownOptionActive,
              ]}
              onPress={() => handleQuickPeriodSelect(period.value)}>
              <Text
                style={[
                  styles.periodDropdownOptionText,
                  quickPeriod === period.value &&
                    styles.periodDropdownOptionTextActive,
                ]}>
                {period.label}
              </Text>
              {quickPeriod === period.value && (
                <Icon name="checkmark" size={18} color={colors.primary} />
              )}
            </TouchableOpacity>
          ))}
        </>
      );
    }

    if (bottomSheetContent === 'month') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Month</Text>
          {selectedMonth !== null && (
            <TouchableOpacity
              style={styles.periodDropdownOptionClear}
              onPress={() => {
                setSelectedMonth(null);
                setBottomSheetVisible(false);
              }}>
              <Text style={styles.periodDropdownOptionClearText}>
                Clear Selection
              </Text>
              <Icon name="close-circle" size={18} color="#EF4444" />
            </TouchableOpacity>
          )}
          {MONTHS.map(month => (
            <TouchableOpacity
              key={month.value}
              style={[
                styles.periodDropdownOption,
                selectedMonth === month.value &&
                  styles.periodDropdownOptionActive,
              ]}
              onPress={() => handleMonthSelect(month.value)}>
              <Text
                style={[
                  styles.periodDropdownOptionText,
                  selectedMonth === month.value &&
                    styles.periodDropdownOptionTextActive,
                ]}>
                {month.label}
              </Text>
              {selectedMonth === month.value && (
                <Icon name="checkmark" size={18} color={colors.primary} />
              )}
            </TouchableOpacity>
          ))}
        </>
      );
    }

    if (bottomSheetContent === 'year') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Year</Text>
          {selectedYear !== null && (
            <TouchableOpacity
              style={styles.periodDropdownOptionClear}
              onPress={() => {
                setSelectedYear(null);
                setBottomSheetVisible(false);
              }}>
              <Text style={styles.periodDropdownOptionClearText}>
                Clear Selection
              </Text>
              <Icon name="close-circle" size={18} color="#EF4444" />
            </TouchableOpacity>
          )}
          {availableYears.map(year => (
            <TouchableOpacity
              key={year}
              style={[
                styles.periodDropdownOption,
                selectedYear === year && styles.periodDropdownOptionActive,
              ]}
              onPress={() => handleYearSelect(year)}>
              <Text
                style={[
                  styles.periodDropdownOptionText,
                  selectedYear === year &&
                    styles.periodDropdownOptionTextActive,
                ]}>
                {year}
              </Text>
              {selectedYear === year && (
                <Icon name="checkmark" size={18} color={colors.primary} />
              )}
            </TouchableOpacity>
          ))}
        </>
      );
    }

    return null;
  };

  const renderAddReceiptSheet = () => {
    return (
      <View style={styles.receiptSheetContainer}>
        <Text style={styles.receiptSheetTitle}>Attach Bill Photo</Text>
        <Text style={styles.receiptSheetSubtitle}>Choose a source</Text>
        <View style={styles.receiptSheetOptions}>
          <TouchableOpacity
            style={styles.receiptSheetOption}
            onPress={() => {
              setAddReceiptSheetVisible(false);
              handlePickReceiptImage('camera');
            }}>
            <Icon name="camera-outline" size={32} color={colors.primary} />
            <Text style={styles.receiptSheetOptionText}>Camera</Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={styles.receiptSheetOption}
            onPress={() => {
              setAddReceiptSheetVisible(false);
              handlePickReceiptImage('gallery');
            }}>
            <Icon name="image-outline" size={32} color={colors.primary} />
            <Text style={styles.receiptSheetOptionText}>Gallery</Text>
          </TouchableOpacity>
        </View>
        <TouchableOpacity
          style={styles.receiptSheetCancel}
          onPress={() => setAddReceiptSheetVisible(false)}>
          <Text style={styles.receiptSheetCancelText}>Cancel</Text>
        </TouchableOpacity>
      </View>
    );
  };

  useEffect(() => {
    updateFilteredData();
  }, [quickPeriod, selectedMonth, selectedYear, transactions, monthStartDay]);

  const normalizeMonthStartDay = value => {
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) {
      return DEFAULT_MONTH_START_DAY;
    }
    return Math.min(28, Math.max(1, Math.floor(parsed)));
  };

  const loadMonthStartDay = async () => {
    try {
      const stored = await AsyncStorage.getItem(MONTH_START_DAY_KEY);
      setMonthStartDay(normalizeMonthStartDay(stored));
    } catch (error) {
      console.error('Failed to load month start day:', error);
    }
  };

  const getMonthlyRangeFromStartDay = (startDay, referenceDate = new Date()) => {
    const start = new Date(
      referenceDate.getFullYear(),
      referenceDate.getMonth(),
      startDay
    );
    if (referenceDate.getDate() < startDay) {
      start.setMonth(start.getMonth() - 1);
    }
    start.setHours(0, 0, 0, 0);
    const end = new Date(start);
    end.setMonth(end.getMonth() + 1);
    end.setMilliseconds(end.getMilliseconds() - 1);
    return {startTime: start.getTime(), endTime: end.getTime()};
  };

  const getMonthYearRange = (month, year, startDay) => {
    const start = new Date(year, month, startDay);
    start.setHours(0, 0, 0, 0);
    const end = new Date(year, month + 1, startDay);
    end.setHours(0, 0, 0, 0);
    end.setMilliseconds(end.getMilliseconds() - 1);
    return {startTime: start.getTime(), endTime: end.getTime()};
  };

  const activityTimelineEntries = useMemo(() => {
    return transactions
      .filter(
        txn =>
          Number(txn?.is_deleted) !== 1 &&
          (isEarningWithdrawLogTransaction(txn) ||
            (!showTransferEntries && isTimelineTransferTransaction(txn)))
      )
      .sort((a, b) => {
        const timeDiff = Number(b.transaction_date) - Number(a.transaction_date);
        if (timeDiff !== 0) {
          return timeDiff;
        }
        const aIdNum = Number(a.id);
        const bIdNum = Number(b.id);
        if (Number.isFinite(aIdNum) && Number.isFinite(bIdNum)) {
          return bIdNum - aIdNum;
        }
        return String(b.id).localeCompare(String(a.id));
      });
  }, [transactions, showTransferEntries]);

  const ledgerTransactions = useMemo(
    () => transactions.filter(txn => !isEarningWithdrawLogTransaction(txn)),
    [transactions]
  );

  const transactionList = useMemo(() => {
    let runningBalance = 0;
    const chronological = ledgerTransactions
      .map(txn => {
        const isDeleted = Number(txn.is_deleted) === 1;
        const txnAmount = isDeleted ? 0 : Number(txn.amount) || 0;
        const balanceAfter = runningBalance + txnAmount;
        runningBalance = balanceAfter;
        return {txn, balanceAfter, isDeleted};
      })
      .filter(
        entry => showTransferEntries || !isTimelineTransferTransaction(entry.txn)
      );
    const reversed = chronological.slice().reverse();
    return reversed.map((entry, index) => {
      const dateKey = new Date(entry.txn.transaction_date).toDateString();
      const nextDateKey =
        index < reversed.length - 1
          ? new Date(reversed[index + 1].txn.transaction_date).toDateString()
          : null;
      const showDate = dateKey !== nextDateKey;
      return {...entry, showDate};
    });
  }, [ledgerTransactions, showTransferEntries]);

  const renderWithdrawTimelineBlock = () => {
    if (activityTimelineEntries.length === 0) {
      return null;
    }

    const latestEntry = activityTimelineEntries[0];
    const olderEntries = withdrawTimelineExpanded
      ? activityTimelineEntries.slice(1)
      : [];
    const shouldScrollWithdrawTimeline =
      withdrawTimelineExpanded &&
      olderEntries.length > WITHDRAW_TIMELINE_VISIBLE_ENTRIES - 1;

    return (
      <View style={styles.withdrawTimelineCard}>
        <TouchableOpacity
          style={styles.withdrawTimelineInlineHeader}
          activeOpacity={0.85}
          onPress={() => setWithdrawTimelineExpanded(prev => !prev)}>
          <View style={styles.withdrawTimelineContent}>
            <Text style={styles.withdrawTimelineText}>
              {formatTimelineEntryRemark(latestEntry)}
            </Text>
            <Text style={styles.withdrawTimelineMeta}>
              {`${formatDateLabel(latestEntry.transaction_date)} ${formatTimeLabel(
                latestEntry.transaction_date
              )}`}
            </Text>
          </View>
          <Icon
            name={withdrawTimelineExpanded ? 'chevron-up' : 'chevron-down'}
            size={18}
            color="#334155"
          />
        </TouchableOpacity>

        {olderEntries.length > 0 ? (
          <ScrollView
            style={styles.withdrawTimelineBody}
            contentContainerStyle={styles.withdrawTimelineBodyContent}
            nestedScrollEnabled
            showsVerticalScrollIndicator={false}
            scrollEnabled={shouldScrollWithdrawTimeline}>
            {olderEntries.map((entry, index) => (
              <View key={String(entry.id)} style={styles.withdrawTimelineItem}>
                <View style={styles.withdrawTimelineMarkerWrap}>
                  <View
                    style={[
                      styles.withdrawTimelineDot,
                      isEarningWithdrawLogTransaction(entry)
                        ? styles.withdrawTimelineDotWithdraw
                        : styles.withdrawTimelineDotTransfer,
                    ]}
                  />
                  {index < olderEntries.length - 1 ? (
                    <View style={styles.withdrawTimelineConnector} />
                  ) : null}
                </View>
                <View style={styles.withdrawTimelineContent}>
                  <Text style={styles.withdrawTimelineText}>
                    {formatTimelineEntryRemark(entry)}
                  </Text>
                  <Text style={styles.withdrawTimelineMeta}>
                    {`${formatDateLabel(entry.transaction_date)} ${formatTimeLabel(
                      entry.transaction_date
                    )}`}
                  </Text>
                </View>
              </View>
            ))}
          </ScrollView>
        ) : null}
      </View>
    );
  };

  const renderTransactions = () => {
    if (!hasLoadedTransactions) {
      return null;
    }
    const hasMainEntries = transactionList.length > 0;

    if (transactions.length === 0) {
      return (
        <View style={[styles.scrollContent, styles.historySection, styles.emptyHistory]}>
          <Icon name="receipt-outline" size={48} color="#D1D5DB" />
          <Text style={styles.emptyText}>No transactions yet</Text>
        </View>
      );
    }

    if (!hasMainEntries) {
      return null;
    }

    return (
      <FlatList
        data={transactionList}
        keyExtractor={item => String(item.txn.id)}
        style={styles.scrollView}
        contentContainerStyle={[
          styles.scrollContent,
          styles.historySection,
          styles.chatList,
        ]}
        showsVerticalScrollIndicator={false}
        inverted
        renderItem={({item}) => {
          const {txn, balanceAfter, isDeleted, showDate} = item;
          const editCount = Number(txn.edit_count) || 0;
          const editHistory = editCount ? parseEditHistory(txn) : [];
          const isTransfer = isTransferTransaction(txn);
          const receiptUri = txn.image_uri
            ? normalizeImageUri(txn.image_uri)
            : '';

          return (
            <View key={txn.id}>
              {showDate && (
                <View style={styles.datePill}>
                  <Text style={styles.datePillText}>
                    {formatDateLabel(txn.transaction_date)}
                  </Text>
                </View>
              )}
              <TapEffect
                style={[
                  styles.chatRow,
                  Number(txn.amount) < 0 && styles.chatRowDebit,
                ]}
                {...getDeletedTapEffectProps(
                  isDeleted,
                  () => openTransactionMenu(txn),
                )}
                delayLongPress={250}>
                <View
                  style={[
                    styles.chatBubble,
                    Number(txn.amount) > 0 && styles.chatBubbleCredit,
                    Number(txn.amount) < 0 && styles.chatBubbleDebit,
                    isDeleted && deletedUiStyles.bubble,
                  ]}>
                  <View style={styles.chatHeader}>
                    <View
                      style={[
                        styles.chatIcon,
                        Number(txn.amount) < 0 && styles.chatIconDebit,
                        isTransfer && styles.chatIconTransfer,
                        isDeleted && deletedUiStyles.iconContainer,
                      ]}>
                      <Icon
                        name={Number(txn.amount) < 0 ? 'arrow-down' : 'arrow-up'}
                        size={16}
                        color={getDeletedIconColor(
                          isDeleted,
                          isTransfer
                            ? '#3B82F6'
                            : Number(txn.amount) < 0
                            ? '#EF4444'
                            : '#10B981',
                        )}
                      />
                    </View>
                    <Text
                      style={withDeletedStyle(
                        isDeleted,
                        [
                          styles.chatAmount,
                          Number(txn.amount) < 0 && styles.chatAmountDebit,
                          isTransfer && styles.chatAmountTransfer,
                        ],
                        deletedUiStyles.amount,
                      )}>
                      {(Number(txn.amount) < 0 ? '-' : '+') +
                        formatCurrency(Math.abs(Number(txn.amount) || 0))}
