                    <Text style={styles.chatBalance}>
                      {formatCurrency(balanceAfter)}
                    </Text>
                    <View style={styles.chatMetaRight}>
                      <Text style={styles.chatTime}>
                        {formatTimeLabel(txn.transaction_date)}
