  const isTransferTransaction = txn => {
    const entryKind = String(txn?.entry_kind || '').trim().toLowerCase();
    if (entryKind) {
      return entryKind === 'transfer';
    }
    const remark = String(txn?.remark || '').trim().toLowerCase();
    return (
      remark.startsWith('transferred to ') ||
      remark.startsWith('transferred from ')
    );
  };

  const isRequestTransaction = txn => {
    const entryKind = String(txn?.entry_kind || '').trim().toLowerCase();
    if (entryKind) {
      return entryKind === 'request' || entryKind === 'legacy_transfer';
    }
    const remark = String(txn?.remark || '').trim().toLowerCase();
    return (
      remark.startsWith('requested from ') ||
      remark.startsWith('requested by ') ||
      remark.startsWith('requested to ')
    );
  };

  const isTransferLogTimelineTransaction = txn => {
    const entryKind = String(txn?.entry_kind || '').trim().toLowerCase();
    if (entryKind) {
      return (
        entryKind === 'transfer' ||
        entryKind === 'request' ||
        entryKind === 'legacy_transfer'
      );
    }
    return isTransferTransaction(txn) || isRequestTransaction(txn);
  };

  const formatTransferLogRemark = txn => {
    const remark = String(txn?.remark || '').trim();
    const amount = Math.abs(Number(txn?.amount) || 0);
    const amountLabel = formatCurrency(amount);
    if (!remark) {
      return `Transfer ${amountLabel}`;
    }

    const lower = remark.toLowerCase();
    const directionByPrefix = {
      'transferred to ': 'to',
      'transferred from ': 'from',
      'requested by ': 'to',
      'requested to ': 'to',
      'requested from ': 'from',
    };
    const prefixes = Object.keys(directionByPrefix);
    const matchedPrefix = prefixes.find(prefix => lower.startsWith(prefix));
    if (!matchedPrefix) {
      return `Transfer ${amountLabel}`;
    }

    const remainder = remark.slice(matchedPrefix.length).trim();
    if (!remainder) {
      return `Transfer ${amountLabel}`;
    }
    const separatorIndex = remainder.indexOf(' - ');
    const accountName =
      separatorIndex === -1
        ? remainder
        : remainder.slice(0, separatorIndex).trim();
    const note =
      separatorIndex === -1 ? '' : remainder.slice(separatorIndex + 3).trim();
    const actionLabel = matchedPrefix.startsWith('requested') ? 'Request' : 'Transfer';
    const direction = directionByPrefix[matchedPrefix] || 'to';

    if (note) {
      return `${actionLabel} ${amountLabel} ${direction} ${accountName} - ${note}`;
    }
    return `${actionLabel} ${amountLabel} ${direction} ${accountName}`;
  };

  const getLinkedRemarkType = remarkValue => {
    const remark = String(remarkValue || '').trim().toLowerCase();
    if (remark.startsWith('transferred to ')) {
      return 'transfer_to';
    }
    if (remark.startsWith('transferred from ')) {
      return 'transfer_from';
    }
    if (remark.startsWith('requested by ')) {
      return 'request_by';
    }
    if (remark.startsWith('requested from ')) {
      return 'request_from';
    }
    if (remark.startsWith('requested to ')) {
      return 'request_to';
    }
    return null;
  };

  const extractLinkedAccountName = remarkValue => {
    const remark = String(remarkValue || '').trim();
    if (!remark) {
      return '';
    }
    const lower = remark.toLowerCase();
    const prefixes = [
      'transferred to ',
      'transferred from ',
      'requested by ',
      'requested from ',
      'requested to ',
    ];
    const prefix = prefixes.find(item => lower.startsWith(item));
    if (!prefix) {
      return '';
    }
    const withoutPrefix = remark.slice(prefix.length).trim();
    if (!withoutPrefix) {
      return '';
    }
    const separatorIndex = withoutPrefix.indexOf(' - ');
    const name =
      separatorIndex === -1
        ? withoutPrefix
        : withoutPrefix.slice(0, separatorIndex);
    return name.trim().toLowerCase();
  };

  const isLinkedRemarkPair = (sourceType, candidateType) => {
    if (!sourceType || !candidateType) {
      return true;
    }
    if (sourceType === 'transfer_to') {
      return candidateType === 'transfer_from';
    }
    if (sourceType === 'transfer_from') {
      return candidateType === 'transfer_to';
    }
    if (sourceType === 'request_by') {
      return candidateType === 'request_from' || candidateType === 'request_to';
    }
    if (sourceType === 'request_from') {
      return candidateType === 'request_by';
    }
    if (sourceType === 'request_to') {
      return candidateType === 'request_by';
    }
    return true;
  };

  const isLockedTransaction = txn =>
    isTransferTransaction(txn) || isRequestTransaction(txn);

  const getLinkedEarningTransaction = txn => {
    if (!txn) {
      return null;
    }
    const remark = String(txn.remark || '').trim();
    if (!remark) {
      return null;
    }
    if (!isLockedTransaction(txn)) {
      return null;
    }
    const amountValue = Math.abs(Number(txn.amount) || 0);
    if (!amountValue) {
      return null;
    }
    const txnAmount = Number(txn.amount) || 0;
    const txnType = getLinkedRemarkType(remark);
    const preferredLinkedName = extractLinkedAccountName(remark);
    const earningAccounts = getAccountsByType('earning');

    const pickBestMatch = accountsList => {
      let bestMatch = null;
      let bestDelta = Number.POSITIVE_INFINITY;
      accountsList.forEach(earning => {
        const earningTxns = getTransactionsByAccount(earning.id);
        earningTxns.forEach(entry => {
          if (Number(entry?.is_deleted) === 1) {
            return;
          }
          const entryAmountNumeric = Number(entry.amount) || 0;
          const entryAmountAbs = Math.abs(entryAmountNumeric);
          if (entryAmountAbs !== amountValue) {
            return;
          }
          if (
            txnAmount !== 0 &&
            entryAmountNumeric !== 0 &&
            Math.sign(txnAmount) === Math.sign(entryAmountNumeric)
          ) {
            return;
          }
          const entryType = getLinkedRemarkType(entry.remark);
          if (!isLinkedRemarkPair(txnType, entryType)) {
            return;
          }
          const delta = Math.abs(
            Number(entry.transaction_date) - Number(txn.transaction_date)
          );
          if (
            delta < bestDelta ||
            (delta === bestDelta &&
              String(entry.id).localeCompare(String(bestMatch?.id || '')) < 0)
          ) {
            bestDelta = delta;
            bestMatch = entry;
          }
        });
      });
      return bestMatch;
    };

    const preferredAccounts =
      preferredLinkedName.length > 0
        ? earningAccounts.filter(
            item =>
              String(item?.account_name || '').trim().toLowerCase() ===
              preferredLinkedName
          )
        : [];
    return pickBestMatch(preferredAccounts) || pickBestMatch(earningAccounts);
  };

  const canEditRemark = txn => {
    if (!txn) {
      return false;
    }
    if (Number(txn.is_deleted) === 1) {
      return false;
    }
    const amount = Number(txn.amount);
    return Number.isFinite(amount);
  };

  const parseEditHistory = txn => {
    if (!txn?.edit_history) {
      return [];
    }
    try {
      const parsed = JSON.parse(txn.edit_history);
      return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
      return [];
    }
  };

  const formatEditHistoryValue = value => {
    if (value === 'Deleted') {
      return 'Deleted';
    }
    return formatCurrency(Number(value) || 0);
  };

  const buildDeleteHistory = txn => {
    const editCount = Number(txn?.edit_count) || 0;
    if (!editCount) {
      return null;
    }
    const history = parseEditHistory(txn);
    const amountAbs = Math.abs(Number(txn?.amount) || 0);
    const base = history.length ? history : [amountAbs];
    return JSON.stringify([...base, 'Deleted']);
  };

  const getLatestTransactionId = () => {
    if (!transactions || transactions.length === 0) {
      return null;
    }
    let latest = null;
    for (let i = 0; i < transactions.length; i += 1) {
      const txn = transactions[i];
      if (Number(txn.is_deleted) === 1) {
        continue;
      }
      if (!latest) {
        latest = txn;
        continue;
      }
      const currentDate = Number(txn.transaction_date) || 0;
      const latestDate = Number(latest.transaction_date) || 0;
      if (
        currentDate > latestDate ||
        (currentDate === latestDate && Number(txn.id) > Number(latest.id))
      ) {
        latest = txn;
      }
    }
    return latest?.id ?? null;
  };

  const canEditAmount = txn => {
    if (!txn) {
      return false;
    }
    if (Number(txn.is_deleted) === 1) {
      return false;
    }
    const latestId = getLatestTransactionId();
    if (!latestId || txn.id !== latestId) {
      return false;
    }
    if (isLockedTransaction(txn)) {
      return false;
    }
    const editCount = Number(txn.edit_count) || 0;
    if (editCount >= 3) {
      return false;
    }
    const amount = Number(txn.amount);
    return Number.isFinite(amount);
  };

  const compareTimelineEntries = (a, b) => {
    const timeDiff = Number(a.transaction_date) - Number(b.transaction_date);
    if (timeDiff !== 0) {
      return timeDiff;
    }
    const aIdNum = Number(a.id);
    const bIdNum = Number(b.id);
    if (Number.isFinite(aIdNum) && Number.isFinite(bIdNum)) {
      return aIdNum - bIdNum;
    }
    return String(a.id).localeCompare(String(b.id));
  };

  const canApplyAmountEditWithEntries = (entries, transactionId, nextAmount) => {
    if (!transactionId) {
      return false;
    }
    if (!Number.isFinite(nextAmount)) {
      return false;
    }
    const timeline = entries
      .filter(entry => Number(entry?.is_deleted) !== 1)
      .map(entry =>
        entry.id === transactionId ? {...entry, amount: nextAmount} : entry
      )
      .sort(compareTimelineEntries);

    let running = 0;
    for (const entry of timeline) {
      running += Number(entry.amount) || 0;
      if (running < 0) {
        return false;
      }
    }
    return true;
  };

  const canDeleteWithoutNegative = (entries, transactionId) => {
    if (!transactionId) {
      return false;
    }
    const timeline = entries
      .filter(entry => Number(entry?.is_deleted) !== 1)
      .filter(entry => entry.id !== transactionId)
      .sort(compareTimelineEntries);

    let running = 0;
    for (const entry of timeline) {
      running += Number(entry.amount) || 0;
      if (running < 0) {
        return false;
      }
    }
    return true;
  };

