    setIsFiltering(true);

    if (selectedMonth !== null && selectedYear !== null) {
      calculateMonthYearData(selectedMonth, selectedYear);
    } else {
      calculateQuickPeriodData(quickPeriod);
    }
    setIsFiltering(false);
    setHasAppliedFilter(true);
  };

  const handleQuickPeriodSelect = period => {
    setQuickPeriod(period);
    setSelectedMonth(null);
    setSelectedYear(null);
    setBottomSheetVisible(false);
  };

  const handleMonthSelect = month => {
    setSelectedMonth(month);
    setBottomSheetVisible(false);
  };

  const handleYearSelect = year => {
    setSelectedYear(year);
    setBottomSheetVisible(false);
  };

  const renderBottomSheetContent = () => {
    if (bottomSheetContent === 'quick') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Period</Text>
          {QUICK_PERIODS.map(period => (
            <TouchableOpacity
              key={period.value}
              style={[
                styles.periodDropdownOption,
                quickPeriod === period.value && styles.periodDropdownOptionActive,
              ]}
              onPress={() => handleQuickPeriodSelect(period.value)}>
              <Text
                style={[
                  styles.periodDropdownOptionText,
                  quickPeriod === period.value &&
                    styles.periodDropdownOptionTextActive,
                ]}>
                {period.label}
              </Text>
              {quickPeriod === period.value && (
                <Icon name="checkmark" size={18} color={colors.primary} />
              )}
            </TouchableOpacity>
          ))}
        </>
      );
    }

    if (bottomSheetContent === 'month') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Month</Text>
          {selectedMonth !== null && (
            <TouchableOpacity
              style={styles.periodDropdownOptionClear}
              onPress={() => {
                setSelectedMonth(null);
                setBottomSheetVisible(false);
              }}>
              <Text style={styles.periodDropdownOptionClearText}>
                Clear Selection
              </Text>
              <Icon name="close-circle" size={18} color="#EF4444" />
            </TouchableOpacity>
          )}
          {MONTHS.map(month => (
            <TouchableOpacity
              key={month.value}
              style={[
                styles.periodDropdownOption,
                selectedMonth === month.value &&
                  styles.periodDropdownOptionActive,
              ]}
              onPress={() => handleMonthSelect(month.value)}>
              <Text
                style={[
                  styles.periodDropdownOptionText,
                  selectedMonth === month.value &&
                    styles.periodDropdownOptionTextActive,
                ]}>
                {month.label}
              </Text>
              {selectedMonth === month.value && (
                <Icon name="checkmark" size={18} color={colors.primary} />
              )}
            </TouchableOpacity>
          ))}
        </>
      );
    }

    if (bottomSheetContent === 'year') {
      return (
        <>
          <Text style={styles.bottomSheetTitle}>Select Year</Text>
          {selectedYear !== null && (
            <TouchableOpacity
              style={styles.periodDropdownOptionClear}
              onPress={() => {
                setSelectedYear(null);
                setBottomSheetVisible(false);
              }}>
              <Text style={styles.periodDropdownOptionClearText}>
                Clear Selection
              </Text>
              <Icon name="close-circle" size={18} color="#EF4444" />
            </TouchableOpacity>
          )}
          {availableYears.map(year => (
            <TouchableOpacity
              key={year}
              style={[
                styles.periodDropdownOption,
                selectedYear === year && styles.periodDropdownOptionActive,
              ]}
              onPress={() => handleYearSelect(year)}>
              <Text
                style={[
                  styles.periodDropdownOptionText,
                  selectedYear === year &&
                    styles.periodDropdownOptionTextActive,
                ]}>
                {year}
              </Text>
              {selectedYear === year && (
                <Icon name="checkmark" size={18} color={colors.primary} />
              )}
            </TouchableOpacity>
          ))}
        </>
      );
    }

    return null;
  };

  const renderAddReceiptSheet = () => {
    return (
      <View style={styles.receiptSheetContainer}>
        <Text style={styles.receiptSheetTitle}>Attach Bill Photo</Text>
        <Text style={styles.receiptSheetSubtitle}>Choose a source</Text>
        <View style={styles.receiptSheetOptions}>
          <TouchableOpacity
            style={styles.receiptSheetOption}
            onPress={() => {
              setAddReceiptSheetVisible(false);
              handlePickReceiptImage('camera');
            }}>
            <Icon name="camera-outline" size={32} color={colors.primary} />
            <Text style={styles.receiptSheetOptionText}>Camera</Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={styles.receiptSheetOption}
            onPress={() => {
              setAddReceiptSheetVisible(false);
              handlePickReceiptImage('gallery');
            }}>
            <Icon name="image-outline" size={32} color={colors.primary} />
            <Text style={styles.receiptSheetOptionText}>Gallery</Text>
          </TouchableOpacity>
        </View>
        <TouchableOpacity
          style={styles.receiptSheetCancel}
          onPress={() => setAddReceiptSheetVisible(false)}>
          <Text style={styles.receiptSheetCancelText}>Cancel</Text>
        </TouchableOpacity>
      </View>
    );
  };

  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(() => {
      updateFilteredData();
    });
    return () => task.cancel();
  }, [quickPeriod, selectedMonth, selectedYear, transactions, monthStartDay]);

  useEffect(() => {
    if (renameModalVisible) {
      setTimeout(() => {
        renameInputRef.current?.focus();
      }, 400);
    }
  }, [renameModalVisible]);

  const normalizeMonthStartDay = value => {
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) {
      return DEFAULT_MONTH_START_DAY;
    }
    return Math.min(28, Math.max(1, Math.floor(parsed)));
  };

  const loadMonthStartDay = async () => {
    try {
      const stored = await AsyncStorage.getItem(MONTH_START_DAY_KEY);
      setMonthStartDay(normalizeMonthStartDay(stored));
    } catch (error) {
      console.error('Failed to load month start day:', error);
    }
  };

  const getMonthlyRangeFromStartDay = (startDay, referenceDate = new Date()) => {
    const start = new Date(
      referenceDate.getFullYear(),
      referenceDate.getMonth(),
      startDay
    );
    if (referenceDate.getDate() < startDay) {
      start.setMonth(start.getMonth() - 1);
    }
    start.setHours(0, 0, 0, 0);
    const end = new Date(start);
    end.setMonth(end.getMonth() + 1);
    end.setMilliseconds(end.getMilliseconds() - 1);
    return {startTime: start.getTime(), endTime: end.getTime()};
  };

  const getMonthYearRange = (month, year, startDay) => {
    const start = new Date(year, month, startDay);
    start.setHours(0, 0, 0, 0);
    const end = new Date(year, month + 1, startDay);
    end.setHours(0, 0, 0, 0);
    end.setMilliseconds(end.getMilliseconds() - 1);
    return {startTime: start.getTime(), endTime: end.getTime()};
  };

  const transferLogEntries = useMemo(() => {
    if (isSavingAccount) {
      return [];
    }
    return transactions
      .filter(
        txn =>
          Number(txn?.is_deleted) !== 1 &&
          isTransferLogTimelineTransaction(txn)
      )
      .sort((a, b) => {
        const timeDiff = Number(b.transaction_date) - Number(a.transaction_date);
        if (timeDiff !== 0) {
          return timeDiff;
        }
        const aIdNum = Number(a.id);
        const bIdNum = Number(b.id);
        if (Number.isFinite(aIdNum) && Number.isFinite(bIdNum)) {
          return bIdNum - aIdNum;
        }
        return String(b.id).localeCompare(String(a.id));
      });
  }, [transactions, isSavingAccount]);

  const ledgerTransactions = useMemo(() => transactions, [transactions]);

  const transactionList = useMemo(() => {
    const shouldHideTransferInMainList =
      !isSavingAccount && !showTransferEntries;
    let runningBalance = 0;
    const chronological = ledgerTransactions
      .map(txn => {
        const isDeleted = Number(txn.is_deleted) === 1;
        const txnAmount = isDeleted ? 0 : Number(txn.amount) || 0;
        const balanceAfter = runningBalance + txnAmount;
        runningBalance = balanceAfter;
        return {txn, balanceAfter, isDeleted};
      })
      .filter(
        entry =>
          !shouldHideTransferInMainList ||
          !isTransferLogTimelineTransaction(entry.txn)
      );
    const reversed = chronological.slice().reverse();
    return reversed.map((entry, index) => {
      const dateKey = new Date(entry.txn.transaction_date).toDateString();
      const nextDateKey =
        index < reversed.length - 1
          ? new Date(reversed[index + 1].txn.transaction_date).toDateString()
          : null;
      const showDate = dateKey !== nextDateKey;
      return {...entry, showDate};
    });
  }, [ledgerTransactions, showTransferEntries, isSavingAccount]);

  const renderTransferLogBlock = () => {
    if (isSavingAccount || transferLogEntries.length === 0 || showTransferEntries) {
      return null;
    }

    const latestEntry = transferLogEntries[0];
    const olderEntries = transferLogExpanded ? transferLogEntries.slice(1) : [];
    const shouldScrollTransferLog =
      transferLogExpanded &&
      olderEntries.length > TRANSFER_LOG_VISIBLE_ENTRIES - 1;

    return (
      <View style={styles.transferLogCard}>
        <TouchableOpacity
          style={styles.transferLogHeader}
          activeOpacity={0.85}
          onPress={() => setTransferLogExpanded(prev => !prev)}>
          <View style={styles.transferLogContent}>
            <Text style={styles.transferLogText}>
              {formatTransferLogRemark(latestEntry)}
            </Text>
            <Text style={styles.transferLogMeta}>
              {`${formatDateLabel(latestEntry.transaction_date)} ${formatTimeLabel(
                latestEntry.transaction_date
              )}`}
            </Text>
          </View>
          <Icon
            name={transferLogExpanded ? 'chevron-up' : 'chevron-down'}
            size={18}
            color="#334155"
          />
        </TouchableOpacity>

        {olderEntries.length > 0 ? (
          <ScrollView
            style={styles.transferLogBody}
            contentContainerStyle={styles.transferLogBodyContent}
            nestedScrollEnabled
            showsVerticalScrollIndicator={false}
            scrollEnabled={shouldScrollTransferLog}>
            {olderEntries.map((entry, index) => (
              <View key={String(entry.id)} style={styles.transferLogItem}>
                <View style={styles.transferLogMarkerWrap}>
                  <View
                    style={[
                      styles.transferLogDot,
                      isRequestTransaction(entry)
                        ? styles.transferLogDotRequest
                        : styles.transferLogDotTransfer,
                    ]}
                  />
                  {index < olderEntries.length - 1 ? (
                    <View style={styles.transferLogConnector} />
                  ) : null}
                </View>
                <View style={styles.transferLogContent}>
                  <Text style={styles.transferLogText}>
                    {formatTransferLogRemark(entry)}
                  </Text>
                  <Text style={styles.transferLogMeta}>
                    {`${formatDateLabel(entry.transaction_date)} ${formatTimeLabel(
                      entry.transaction_date
                    )}`}
                  </Text>
                </View>
              </View>
            ))}
          </ScrollView>
        ) : null}
      </View>
    );
  };

  const renderTransactions = () => {
    if (!hasLoadedTransactions) {
      return null;
    }
    if (transactions.length === 0) {
      return (
        <View style={[styles.scrollContent, styles.historySection, styles.emptyHistory]}>
          <Icon name="receipt-outline" size={48} color="#D1D5DB" />
          <Text style={styles.emptyText}>No transactions yet</Text>
        </View>
      );
    }

    if (transactionList.length === 0) {
      return null;
    }

    return (
      <FlatList
        data={transactionList}
        keyExtractor={item => String(item.txn.id)}
        style={styles.scrollView}
        contentContainerStyle={[
          styles.scrollContent,
          styles.historySection,
          styles.chatList,
        ]}
        showsVerticalScrollIndicator={false}
        inverted
        renderItem={({item}) => {
          const {txn, balanceAfter, isDeleted, showDate} = item;
          const isDebit = Number(txn.amount) < 0;
          const editCount = Number(txn.edit_count) || 0;
          const editHistory = editCount ? parseEditHistory(txn) : [];
          const isTransfer = isTransferTransaction(txn);
          const isRequest = isRequestTransaction(txn);
          const receiptUri = txn.image_uri ? normalizeImageUri(txn.image_uri) : '';

          return (
            <View key={txn.id}>
              {showDate && (
                <View style={styles.datePill}>
                  <Text style={styles.datePillText}>
                    {formatDateLabel(txn.transaction_date)}
                  </Text>
                </View>
              )}
              <TapEffect
                style={[styles.chatRow, isDebit && styles.chatRowDebit]}
                {...getDeletedTapEffectProps(
                  isDeleted,
                  () => openTransactionMenu(txn),
                )}
                delayLongPress={250}>
                <View
                  style={[
                    styles.chatBubble,
                    isDebit && styles.chatBubbleDebit,
                    isDeleted && deletedUiStyles.bubble,
                  ]}>
                  <View style={styles.chatHeader}>
                    <View
                      style={[
                        styles.chatIcon,
                        isDebit && styles.chatIconDebit,
                        isTransfer && styles.chatIconTransfer,
                        isDeleted && deletedUiStyles.iconContainer,
                      ]}>
                      <Icon
                        name={isDebit ? 'arrow-down' : 'arrow-up'}
                        size={16}
                        color={getDeletedIconColor(
                          isDeleted,
                          isTransfer
                            ? '#3B82F6'
                            : isRequest
                            ? '#10B981'
                            : isDebit
                            ? '#EF4444'
                            : '#10B981',
                        )}
                      />
                    </View>
                    <Text
                      style={withDeletedStyle(
                        isDeleted,
                        [
                          styles.chatAmount,
                          isDebit && styles.chatAmountDebit,
                          isTransfer && styles.chatAmountTransfer,
                          isRequest && styles.chatAmountRequest,
                        ],
                        deletedUiStyles.amount,
                      )}>
                      {(isDebit ? '-' : '+') +
                        formatCurrency(Math.abs(Number(txn.amount) || 0))}
                    </Text>
                    {renderDeletedBadge(isDeleted)}
                  </View>
                  {isDeleted ? (
                    renderDeletedNote(isDeleted)
                  ) : txn.remark ? (
                    <Text style={styles.chatRemark}>{txn.remark}</Text>
                  ) : null}
                  {!isDeleted && receiptUri ? (
                    <Pressable
                      style={styles.receiptBubbleThumb}
                      onPress={() => openReceiptPreview(txn.image_uri)}>
                      <Image source={{uri: receiptUri}} style={styles.receiptBubbleImage} />
                    </Pressable>
                  ) : null}
                  <View style={[styles.chatMeta, isDebit && styles.chatMetaDebit]}>
                    <Text style={styles.chatBalance}>
                      {formatCurrency(balanceAfter)}
                    </Text>
                    <View style={styles.chatMetaRight}>
                      <Text style={styles.chatTime}>
                        {formatTimeLabel(txn.transaction_date)}
                      </Text>
                    </View>
                  </View>
                  {editHistory.length > 1 && (
                    <Text style={styles.editHistoryText}>
                      {`Edited: ${editHistory
                        .map(formatEditHistoryValue)
                        .join(' -> ')}`}
                    </Text>
                  )}
                </View>
              </TapEffect>
            </View>
          );
        }}
      />
    );
  };

  return (
    <View
      style={[
        styles.container,
        account.icon_color && {
          backgroundColor: tintWithWhite(account.icon_color, 0.94),
        },
      ]}>
      {/* Sticky Header */}
      <View style={styles.stickyHeader} onLayout={handleStickyHeaderLayout}>
        <TexturedSurface
          style={[
            styles.header,
            {
              paddingTop: spacing.sm + insets.top,
            },
            account.icon_color && {
              borderBottomColor: withAlpha(account.icon_color, 0.3),
            },
          ]}>
          <View style={styles.headerTopRow}>
            <TouchableOpacity
              onPress={handleBackNavigation}
              style={styles.backButton}>
              <Icon name="chevron-back" size={22} color={headerTexture.icon} />
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => navigation.navigate('PersonalizeAccount', {accountId: account.id})}
              style={styles.accountAvatarTap}
              activeOpacity={0.85}>
              <View
                style={[
                  styles.accountAvatar,
                  account.icon_color && {
                    borderColor: withAlpha(account.icon_color, 0.32),
                  },
                ]}>
                {renderAccountHeaderIcon(
                  account?.icon,
                  28,
                  account?.icon_color || headerTexture.icon
                )}
              </View>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => navigation.navigate('PersonalizeAccount', {accountId: account.id})}
              style={styles.headerTitleBlock}
              activeOpacity={0.85}>
              <Text style={styles.headerTitle}>{account.account_name}</Text>
              <Text style={styles.headerSubtitle}>{accountTypeLabel}</Text>
            </TouchableOpacity>
            <View style={styles.headerActions}>
              <ManualBackupButton
                style={styles.backupButton}
                iconWrapperStyle={styles.backupIconWrapper}
                spinnerStyle={styles.backupSpinner}
                iconColor={headerTexture.icon}
              />
              <View ref={menuButtonRef} collapsable={false}>
                <TouchableOpacity onPress={openAccountMenu} style={styles.menuButton}>
                  <Icon
                    name="ellipsis-vertical"
                    size={22}
                    color={headerTexture.icon}
                  />
                </TouchableOpacity>
              </View>
            </View>
          </View>
        </TexturedSurface>
        <View style={styles.headerMetricsSection}>
          <View style={styles.accountMetricsWrapper}>
            <View style={styles.accountMetricsCard}>
              <View style={styles.dropdownGrid}>
              <View style={styles.dropdownContainer}>
                <Text style={styles.dropdownLabel}>Quick Period</Text>
                <TouchableOpacity
                  style={[
                    styles.dropdown,
                    selectedMonth !== null &&
                      selectedYear !== null &&
                      styles.dropdownDisabled,
                  ]}
                  onPress={() => {
                    if (selectedMonth === null || selectedYear === null) {
                      setBottomSheetContent('quick');
                      setBottomSheetVisible(true);
                    }
                  }}
                  disabled={selectedMonth !== null && selectedYear !== null}>
                  <Text
                    style={[
                      styles.dropdownText,
                      selectedMonth !== null &&
                        selectedYear !== null &&
                        styles.dropdownTextDisabled,
                    ]}>
                    {QUICK_PERIODS.find(p => p.value === quickPeriod)?.label ||
                      'This Month'}
                  </Text>
                  <Icon
                    name="chevron-down"
                    size={16}
                    color={
                      selectedMonth !== null && selectedYear !== null
                        ? '#9CA3AF'
                        : '#6B7280'
                    }
                  />
                </TouchableOpacity>
              </View>
              <View style={styles.dropdownContainer}>
                <Text style={styles.dropdownLabel}>Month</Text>
                <TouchableOpacity
                  style={styles.dropdown}
                  onPress={() => {
                    setBottomSheetContent('month');
                    setBottomSheetVisible(true);
                  }}>
                  <Text style={styles.dropdownText}>
                    {selectedMonth !== null
                      ? MONTHS[selectedMonth].label
                      : 'Select'}
                  </Text>
                  <Icon
                    name="chevron-down"
                    size={16}
                    color="#6B7280"
                  />
                </TouchableOpacity>
              </View>
              <View style={styles.dropdownContainer}>
                <Text style={styles.dropdownLabel}>Year</Text>
                <TouchableOpacity
                  style={styles.dropdown}
                  onPress={() => {
                    setBottomSheetContent('year');
                    setBottomSheetVisible(true);
                  }}>
                  <Text style={styles.dropdownText}>
                    {selectedYear !== null ? selectedYear : 'Select'}
                  </Text>
                  <Icon
                    name="chevron-down"
                    size={16}
                    color="#6B7280"
                  />
                </TouchableOpacity>
              </View>
            </View>
              <View style={styles.accountMetricsRow}>
                <View style={styles.accountMetricHalf}>
                  <View style={styles.accountMetricLabelRow}>
                    <Text style={styles.accountMetricLabel}>Added</Text>
                  </View>
                  <Text
                    style={[
                      styles.accountMetricValue,
                      account.icon_color && {color: account.icon_color},
                    ]}>
                    {formatCurrency(filteredAdded)}
                  </Text>
                </View>
                <View style={styles.accountMetricDivider} />
                <View style={styles.accountMetricHalf}>
                  <View style={styles.accountMetricLabelRow}>
                    <Text style={styles.accountMetricLabel}>Withdrawals</Text>
                  </View>
                  <Text
                    style={[
                      styles.accountMetricValue,
                      styles.accountMetricNegative,
                    ]}>
                    {formatCurrency(filteredWithdrawals)}
                  </Text>
                </View>
                <View style={styles.accountMetricDivider} />
                <View style={styles.accountMetricHalf}>
                  <View style={styles.accountMetricLabelRow}>
                    <Text style={styles.accountMetricLabel}>
                      {isSavingAccount ? 'Savings' : 'Balance'}
                    </Text>
                  </View>
                  <Text
                    style={[
                      styles.accountMetricValue,
                      isSavingAccount && styles.accountMetricSavings,
                    ]}>
                    {formatCurrency(totalBalance)}
                  </Text>
                </View>
              </View>
            </View>
          </View>
        </View>
      </View>
      <View style={[styles.listSpacer, {paddingTop: headerHeight}]}>
        {renderTransactions()}
      </View>


      {/* Bottom Fixed Section */}
      <View
        style={[
          styles.bottomSection,
          {
            backgroundColor: '#FFFFFF',
            paddingBottom: spacing.md + insets.bottom,
          },
          account.icon_color && {
            borderTopColor: withAlpha(account.icon_color, 0.3),
          },
        ]}>
        {renderTransferLogBlock()}
        {/* Action Buttons */}
        <View style={styles.actionButtons}>
          {!isSavingAccount && (
            <CTAButton
              label="Withdraw"
              kind="withdraw"
              compact
              style={styles.withdrawCtaButton}
              onPress={() => {
                navigation.navigate('AmountEntry', {
                  mode: 'withdraw',
                  account,
                  prevRouteKey: route.key,
                  initialEntryDate: entryDate.toISOString(),
                });
              }}
            />
          )}
          {isSavingAccount && (
            <CTAButton
              label="Transfer"
              kind="transfer"
              compact
              style={styles.transferButton}
              onPress={() => {
                navigation.navigate('AmountEntry', {
                  mode: 'withdraw',
                  account,
                  prevRouteKey: route.key,
                  initialEntryDate: entryDate.toISOString(),
                  transferOnly: true,
                });
              }}
            />
          )}
          {isSavingAccount ? (
            <CTAButton
              label="Add Savings"
              kind="add"
              compact
              style={styles.givenCtaButton}
              onPress={() => {
                navigation.navigate('AmountEntry', {
                  mode: 'request',
                  account,
                  prevRouteKey: route.key,
                  initialEntryDate: entryDate.toISOString(),
                  enableCalculator: true,
                });
              }}
            />
          ) : (
            <CTAButton
              label="Add Budget"
              kind="add"
              compact
              style={styles.givenCtaButton}
              onPress={() => {
                navigation.navigate('AmountEntry', {
                  mode: 'request',
                  account,
                  prevRouteKey: route.key,
                  initialEntryDate: entryDate.toISOString(),
                  enableCalculator: true,
                });
              }}
            />
          )}
        </View>
      </View>

      <AmountEntryView visible={withdrawModalVisible}>
        <View style={styles.modalOverlay}>
          <TouchableOpacity
            style={styles.modalBackdrop}
            activeOpacity={1}
            onPress={() => {
              setWithdrawModalVisible(false);
              setWithdrawNote('');
              setWithdrawReceiptUri('');
            }}
          />
          <Animated.View
            style={[
              styles.modalSheet,
              {
                transform: [
                  {
                    translateY: modalSlideAnim.interpolate({
                      inputRange: [0, 1],
                      outputRange: [260, 0],
                    }),
                  },
                ],
              },
            ]}>
            <View style={styles.modalHandle} />
            <Text style={styles.modalTitle}>Withdraw</Text>
            <TextInput
              style={styles.modalAmountInput}
              value={withdrawAmount}
              onChangeText={setWithdrawAmount}
              keyboardType="numeric"
              autoFocus
              ref={withdrawAmountInputRef}
              showSoftInputOnFocus
              editable={!loading}
            />
            <View style={styles.entryDateTimeRow}>
              <TouchableOpacity
                style={styles.entryDateTimeButton}
                onPress={() => setShowEntryDatePicker(true)}>
                <Text style={styles.entryDateTimeLabel}>Date</Text>
                <Text style={styles.entryDateTimeValue}>
                  {formatEntryDate(entryDate)}
                </Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={styles.entryDateTimeButton}
                onPress={() => setShowEntryTimePicker(true)}>
                <Text style={styles.entryDateTimeLabel}>Time</Text>
                <Text style={styles.entryDateTimeValue}>
                  {formatEntryTime(entryDate)}
                </Text>
              </TouchableOpacity>
            </View>
            {showEntryDatePicker && (
              <DateTimePicker
                value={entryDate}
                mode="date"
                display="default"
                maximumDate={new Date()}
                onChange={handleEntryDateChange}
              />
            )}
            {showEntryTimePicker && (
              <DateTimePicker
                value={entryDate}
                mode="time"
                display="default"
                maximumDate={new Date()}
                onChange={handleEntryTimeChange}
              />
            )}
              <Text style={styles.modalNoteLabel}>Note (Optional)</Text>
              <View style={styles.noteInputWithAttach}>
                <TextInput
                  style={[styles.modalNoteInput, styles.modalNoteInputPadded]}
                  value={withdrawNote}
                  onChangeText={setWithdrawNote}
                  placeholder="Add a note"
                  placeholderTextColor={colors.text.light}
                  multiline
                  numberOfLines={3}
                  editable={!loading}
                />
                <TouchableOpacity
                  style={styles.attachButton}
                  onPress={handleAddReceipt}>
                  <Icon name="attach-outline" size={20} color={colors.text.secondary} />
                </TouchableOpacity>
              </View>
              {withdrawReceiptUri ? (
                <View style={styles.receiptPreviewRow}>
                  <Image source={{uri: normalizeImageUri(withdrawReceiptUri)}} style={styles.receiptThumb} />
                  <TouchableOpacity
                    style={styles.receiptRemoveButton}
                    onPress={handleRemoveReceipt}>
                    <Text style={styles.receiptRemoveText}>Remove</Text>
                  </TouchableOpacity>
                </View>
              ) : null}

              <AmountActionButton
                label="Withdraw"
                variant="neutralOutline"
                style={[styles.modalAddButton, loading && styles.buttonDisabled]}
                textStyle={styles.modalAddButtonText}
                onPress={async () => {
                  const didWithdraw = await handleWithdraw();
                  if (didWithdraw) {
                    setWithdrawModalVisible(false);
                  }
                }}
                loading={loading}
                activityColor={colors.white}
              />
          </Animated.View>
        </View>
      </AmountEntryView>

      <AmountEntryView visible={transferModalVisible}>
        <View style={styles.modalOverlay}>
          <TouchableOpacity
            style={styles.modalBackdrop}
            activeOpacity={1}
            onPress={() => {
              setTransferModalVisible(false);
              setTransferNote('');
              setTransferSelectVisible(false);
            }}
          />
          <Animated.View
            style={[
              styles.modalSheet,
              {
                transform: [
                  {
                    translateY: modalSlideAnim.interpolate({
                      inputRange: [0, 1],
                      outputRange: [260, 0],
                    }),
                  },
                ],
              },
            ]}>
            {transferSelectVisible && (
              <Pressable
                style={styles.transferDismissOverlay}
                onPress={() => setTransferSelectVisible(false)}
              />
            )}
            <View style={styles.modalContent}>
              <View style={styles.modalHandle} />
              <Text style={styles.modalTitle}>Transfer</Text>
              <View style={styles.amountFieldWrapper}>
                <View
                  style={styles.amountFieldRow}
                  onLayout={event =>
                    setTransferFieldHeight(event.nativeEvent.layout.height)
                  }>
                  <TextInput
                    style={styles.amountInputBare}
                    value={transferAmount}
                    onChangeText={setTransferAmount}
                    keyboardType="numeric"
                    ref={transferAmountInputRef}
                    showSoftInputOnFocus
                    editable={!loading}
                  />
                  <View style={styles.amountFieldDivider} />
                  <TouchableOpacity
                    style={styles.amountAccountButton}
                    onPress={() =>
                      setTransferSelectVisible(current => !current)
                    }
                    onLayout={event =>
                      setTransferAccountWidth(event.nativeEvent.layout.width)
                    }
                    disabled={transferAccounts.length === 0}>
                    <Text
                      style={[
                        styles.amountAccountText,
                        transferTarget?.icon_color && {
                          color: transferTarget.icon_color,
                        },
                      ]}
                      numberOfLines={1}>
                      {transferTarget?.account_name ||
                        (transferAccounts.length
                          ? 'Select account'
                          : 'No accounts')}
                    </Text>
                    <Icon
                      name="chevron-down"
                      size={16}
                      color={colors.text.secondary}
                    />
                  </TouchableOpacity>
                </View>
                {transferSelectVisible && (
                  <View
                    style={[
                      styles.floatingAccountList,
                      {
                        bottom: transferFieldHeight + 6,
                        right: 0,
                        width: transferAccountWidth || 140,
                      },
                    ]}>
                    <ScrollView
                      style={styles.floatingAccountScroll}
                      showsVerticalScrollIndicator={false}
                      keyboardShouldPersistTaps="handled">
                      {transferAccounts.map(item => {
                        const isSelected = transferTarget?.id === item.id;
                        const itemColor =
                          item.icon_color || colors.text.primary;
                        return (
                          <TouchableOpacity
                            key={item.id}
                            style={[
                              styles.floatingAccountItem,
                              isSelected && styles.floatingAccountItemSelected,
                            ]}
                            onPress={() => {
                              setTransferTarget(item);
                              setTransferSelectVisible(false);
                            }}>
                            <Text
                              style={[
                                styles.floatingAccountText,
                                {color: itemColor},
                                isSelected && styles.floatingAccountTextSelected,
                              ]}>
                              {item.account_name}
                            </Text>
                            {isSelected && (
                              <Icon
                                name="checkmark-circle"
                                size={16}
                                color={itemColor}
                              />
                            )}
                          </TouchableOpacity>
                        );
                      })}
                    </ScrollView>
                  </View>
                )}
              </View>
              <View style={styles.entryDateTimeRow}>
                <TouchableOpacity
                  style={styles.entryDateTimeButton}
                  onPress={() => setShowEntryDatePicker(true)}>
                  <Text style={styles.entryDateTimeLabel}>Date</Text>
                  <Text style={styles.entryDateTimeValue}>
                    {formatEntryDate(entryDate)}
                  </Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={styles.entryDateTimeButton}
                  onPress={() => setShowEntryTimePicker(true)}>
                  <Text style={styles.entryDateTimeLabel}>Time</Text>
                  <Text style={styles.entryDateTimeValue}>
                    {formatEntryTime(entryDate)}
                  </Text>
                </TouchableOpacity>
              </View>
              {showEntryDatePicker && (
                <DateTimePicker
                  value={entryDate}
                  mode="date"
                  display="default"
                  maximumDate={new Date()}
                  onChange={handleEntryDateChange}
                />
              )}
              {showEntryTimePicker && (
                <DateTimePicker
                  value={entryDate}
                  mode="time"
                  display="default"
                  maximumDate={new Date()}
                  onChange={handleEntryTimeChange}
                />
              )}
              <Text style={styles.modalNoteLabel}>Note (Optional)</Text>
              <TextInput
                style={styles.modalNoteInput}
                value={transferNote}
                onChangeText={setTransferNote}
                placeholder="Add a note"
                placeholderTextColor={colors.text.light}
                multiline
                numberOfLines={3}
                editable={!loading}
              />
              <AmountActionButton
                label="Transfer"
                variant="neutralOutline"
                style={[
                  styles.modalAddButton,
                  account.icon_color && {backgroundColor: account.icon_color},
                  loading && styles.buttonDisabled,
                ]}
                textStyle={styles.modalAddButtonText}
                onPress={handleTransferFromSaving}
                loading={loading}
                activityColor={colors.white}
              />
            </View>
          </Animated.View>
        </View>
      </AmountEntryView>

      <AmountEntryView visible={requestModalVisible}>
        <View style={styles.modalOverlay}>
          <TouchableOpacity
            style={styles.modalBackdrop}
            activeOpacity={1}
            onPress={() => {
              setRequestModalVisible(false);
              setRequestNote('');
            }}
          />
          <Animated.View
            style={[
              styles.modalSheet,
              {
                transform: [
                  {
                    translateY: modalSlideAnim.interpolate({
                      inputRange: [0, 1],
                      outputRange: [260, 0],
                    }),
                  },
                ],
              },
            ]}>
            {requestSelectVisible && (
              <Pressable
                style={styles.transferDismissOverlay}
                onPress={() => setRequestSelectVisible(false)}
              />
            )}
            <View style={styles.modalContent}>
              <View style={styles.modalHandle} />
              <Text style={styles.modalTitle}>{isSavingAccount ? 'Add Savings' : 'Add Budget'}</Text>
              <View style={styles.amountFieldWrapper}>
                <View
                  style={styles.amountFieldRow}
                  onLayout={event =>
                    setRequestFieldHeight(event.nativeEvent.layout.height)
                  }>
                  <TextInput
                    style={styles.amountInputBare}
                    value={requestAmount}
                    onChangeText={setRequestAmount}
                    keyboardType="numeric"
                    autoFocus
                    ref={requestAmountInputRef}
                    showSoftInputOnFocus
                    editable={!loading}
                  />
                  <View style={styles.amountFieldDivider} />
                  <TouchableOpacity
                    style={styles.amountAccountButton}
                    onPress={() =>
                      setRequestSelectVisible(current => !current)
                    }
                    onLayout={event =>
                      setRequestAccountWidth(event.nativeEvent.layout.width)
                    }
                    disabled={requestAccounts.length === 0}>
                    <Text
                      style={[
                        styles.amountAccountText,
                        requestTarget?.icon_color && {
                          color: requestTarget.icon_color,
                        },
                      ]}
                      numberOfLines={1}>
                      {requestTarget?.account_name ||
                        (requestAccounts.length
                          ? 'Select account'
                          : 'No accounts')}
                    </Text>
                    <Icon
                      name="chevron-down"
                      size={16}
                      color={colors.text.secondary}
                    />
                  </TouchableOpacity>
                </View>
                {requestSelectVisible && (
                  <View
                    style={[
                      styles.floatingAccountList,
                      {
                        bottom: requestFieldHeight + 6,
                        right: 0,
                        width: requestAccountWidth || 140,
                      },
                    ]}>
                    <ScrollView
                      style={styles.floatingAccountScroll}
                      showsVerticalScrollIndicator={false}
                      keyboardShouldPersistTaps="handled">
                      {requestAccounts.map(item => {
                        const isSelected = requestTarget?.id === item.id;
                        const itemColor =
                          item.icon_color || colors.text.primary;
                        return (
                          <TouchableOpacity
                            key={item.id}
                            style={[
                              styles.floatingAccountItem,
                              isSelected && styles.floatingAccountItemSelected,
                            ]}
                            onPress={() => {
                              setRequestTarget(item);
                              setRequestSelectVisible(false);
                            }}>
                            <Text
                              style={[
                                styles.floatingAccountText,
                                {color: itemColor},
                                isSelected && styles.floatingAccountTextSelected,
                              ]}>
                              {item.account_name}
                            </Text>
                            {isSelected && (
                              <Icon
                                name="checkmark-circle"
                                size={16}
                                color={itemColor}
                              />
                            )}
                          </TouchableOpacity>
                        );
                      })}
                    </ScrollView>
                  </View>
                )}
              </View>
              <View style={styles.entryDateTimeRow}>
                <TouchableOpacity
                  style={styles.entryDateTimeButton}
                  onPress={() => setShowEntryDatePicker(true)}>
                  <Text style={styles.entryDateTimeLabel}>Date</Text>
                  <Text style={styles.entryDateTimeValue}>
                    {formatEntryDate(entryDate)}
                  </Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={styles.entryDateTimeButton}
                  onPress={() => setShowEntryTimePicker(true)}>
                  <Text style={styles.entryDateTimeLabel}>Time</Text>
                  <Text style={styles.entryDateTimeValue}>
                    {formatEntryTime(entryDate)}
                  </Text>
                </TouchableOpacity>
              </View>
              {showEntryDatePicker && (
                <DateTimePicker
                  value={entryDate}
                  mode="date"
                  display="default"
                  maximumDate={new Date()}
                  onChange={handleEntryDateChange}
                />
              )}
              {showEntryTimePicker && (
                <DateTimePicker
                  value={entryDate}
                  mode="time"
                  display="default"
                  maximumDate={new Date()}
                  onChange={handleEntryTimeChange}
                />
              )}
              <Text style={styles.modalNoteLabel}>Note (Optional)</Text>
              <TextInput
                style={styles.modalNoteInput}
                value={requestNote}
                onChangeText={setRequestNote}
                placeholder="Add a note"
                placeholderTextColor={colors.text.light}
                multiline
                numberOfLines={3}
                editable={!loading}
              />
              <AmountActionButton
                label={isSavingAccount ? "Add Savings" : "Add Budget"}
                variant="neutralOutline"
                style={[
                  styles.modalAddButton,
                  account.icon_color && {backgroundColor: account.icon_color},
                  loading && styles.buttonDisabled,
                ]}
                textStyle={styles.modalAddButtonText}
                onPress={async () => {
                  const didOpen = await handleRequestStart();
                  if (didOpen) {
                    setRequestModalVisible(false);
                  }
                }}
                loading={loading}
                activityColor={colors.white}
              />
            </View>
          </Animated.View>
        </View>
      </AmountEntryView>

      <Modal
        visible={receiptPreviewVisible}
        transparent
        animationType="fade"
        onRequestClose={closeReceiptPreview}>
        <View style={styles.previewOverlay}>
          <View style={styles.previewViewer}>
            <ImageViewer
              imageUrls={[
                {url: normalizeImageUri(receiptPreviewUri)},
              ]}
              enableSwipeDown
              onSwipeDown={closeReceiptPreview}
              renderHeader={renderReceiptPreviewHeader}
              saveToLocalByLongPress={false}
              backgroundColor="transparent"
            />
          </View>
        </View>
      </Modal>

      <Modal
        visible={optionsVisible}
        transparent
        animationType="none"
        onRequestClose={closeOptionsMenu}>
        <Animated.View
          style={[
            styles.optionsOverlay,
            {opacity: optionsOverlayOpacity},
          ]}>
          <TouchableOpacity
            style={styles.optionsOverlayTouchable}
            activeOpacity={1}
            onPress={closeOptionsMenu}
          />
          <Animated.View
            style={[
              styles.optionsContainer,
              {transform: [{translateY: optionsContentTranslateY}]},
            ]}>
            <View style={styles.optionsHeader}>
              <Text style={styles.optionsTitle}>
                {selectedTransaction
                  ? `Options for ${formatCurrency(
                      Math.abs(Number(selectedTransaction.amount) || 0)
                    )}`
                  : 'Options'}
              </Text>
            </View>
            <TouchableOpacity
              style={[
                styles.optionButton,
                !canEditAmount(selectedTransaction) &&
                  styles.optionButtonDisabled,
              ]}
              disabled={!canEditAmount(selectedTransaction)}
              onPress={() => {
                if (!selectedTransaction) {
                  return;
                }
                closeOptionsMenu(true);
                setEditAmount(
                  String(Math.abs(Number(selectedTransaction.amount) || 0))
                );
                setEditAmountVisible(true);
              }}>
              <View style={styles.optionItemRow}>
                <Icon
                  name="create-outline"
                  size={20}
                  color={
                    canEditAmount(selectedTransaction)
                      ? colors.text.primary
                      : colors.text.light
                  }
                />
                <Text
                  style={[
                    styles.optionText,
                    !canEditAmount(selectedTransaction) &&
                      styles.optionTextDisabled,
                  ]}>
                  Edit Amount
                </Text>
              </View>
            </TouchableOpacity>
            <TouchableOpacity
              style={styles.optionButton}
              onPress={() => {
                if (!selectedTransaction) {
                  return;
                }
                if (!canEditRemark(selectedTransaction)) {
                  return;
                }
                closeOptionsMenu(true);
                setEditRemark(selectedTransaction.remark || '');
                setEditRemarkVisible(true);
              }}>
              <View style={styles.optionItemRow}>
                <Icon
                  name="chatbubble-ellipses-outline"
                  size={20}
                  color={colors.text.primary}
                />
                <Text style={styles.optionText}>Edit Remark</Text>
              </View>
            </TouchableOpacity>
            {selectedTransaction?.image_uri ? (
              <TouchableOpacity
                style={styles.optionButton}
                onPress={() => {
                  if (!selectedTransaction?.image_uri) {
                    return;
                  }
                  closeOptionsMenu(true);
                  openReceiptPreview(selectedTransaction.image_uri);
                }}>
                <View style={styles.optionItemRow}>
                  <Icon
                    name="image-outline"
                    size={20}
                    color={colors.text.primary}
                  />
                  <Text style={styles.optionText}>View Bill Photo</Text>
                </View>
              </TouchableOpacity>
            ) : null}
            <TouchableOpacity
              style={[
                styles.optionButton,
                styles.optionDelete,
                !canDeleteTransaction(selectedTransaction) &&
                  styles.optionButtonDisabled,
              ]}
              disabled={!canDeleteTransaction(selectedTransaction)}
              onPress={() => {
                if (!selectedTransaction) {
                  return;
                }
                const isLinked = isLockedTransaction(selectedTransaction);
                const warningText = isLinked
                  ? 'Deleting here will also delete the linked entry from your earning account. This may cause confusion in your accounts.'
                  : 'Are you sure you want to delete this entry?';
                Alert.alert(
                  'Delete Entry',
                  warningText,
                  [
                    {text: 'Cancel', style: 'cancel'},
                    {
                      text: 'Delete',
                      style: 'destructive',
                      onPress: async () => {
                        closeOptionsMenu(true);
                        try {
                          if (
                            !canDeleteWithoutNegative(
                              transactions,
                              selectedTransaction.id
                            )
                          ) {
                            showUniversalToast(
                              'Delete not allowed. Balance would go negative.',
                              'error'
                            );
                            return;
                          }
                          if (isLinked) {
                            const linked = getLinkedEarningTransaction(
                              selectedTransaction
                            );
                            if (linked) {
                              const linkedTransactions =
                                getTransactionsByAccount(linked.account_id);
                              if (
                                !canDeleteWithoutNegative(
                                  linkedTransactions,
                                  linked.id
                                )
                              ) {
                                showUniversalToast(
                                  'Delete not allowed. Linked account balance would go negative.',
                                  'error'
                                );
                                return;
                              }
                              const linkedHistory = buildDeleteHistory(linked);
                              await deleteTransaction(
                                linked.id,
                                linked.account_id,
                                linkedHistory
                              );
                              await deleteReceiptFileIfPossible(
                                linked.image_uri
                              );
                            }
                          }
                          const deleteHistory =
                            buildDeleteHistory(selectedTransaction);
                          await deleteTransaction(
                            selectedTransaction.id,
                            account.id,
                            deleteHistory
                          );
                          await deleteReceiptFileIfPossible(
                            selectedTransaction.image_uri
                          );
                          loadTransactions();
                          setSelectedTransaction(null);
                        } catch (error) {
                          console.error('Failed to delete entry:', error);
                          Alert.alert(
                            'Error',
                            'Failed to delete entry. Please try again.'
                          );
                        }
                      },
                    },
                  ]
                );
              }}>
              <View style={styles.optionItemRow}>
                <Icon
                  name="trash-outline"
                  size={20}
                  color={
                    canDeleteTransaction(selectedTransaction)
                      ? '#B91C1C'
                      : colors.text.light
                  }
                />
                <Text
                  style={[
                    styles.optionText,
                    styles.optionDeleteText,
                    !canDeleteTransaction(selectedTransaction) &&
                      styles.optionTextDisabled,
                  ]}>
                  Delete Entry
                </Text>
              </View>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.optionButton, styles.optionButtonCancel]}
              onPress={closeOptionsMenu}>
              <View style={styles.optionItemRow}>
                <Icon name="close" size={20} color={colors.text.secondary} />
                <Text style={styles.optionTextCancel}>Cancel</Text>
              </View>
            </TouchableOpacity>
          </Animated.View>
        </Animated.View>
      </Modal>

      <DropdownPopup
        visible={menuVisible}
        onClose={closeAccountMenu}
        cardStyle={[
          styles.accountMenuCard,
          {
            width: menuWidth,
            top: menuTop,
            left: menuLeft,
            opacity: menuAnim,
            transform: [
              {
                translateY: menuAnim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [-14, 0],
                }),
              },
            ],
          },
        ]}>
            {accountMenuPrimaryActions.map(action => {
              if (action.type === 'switch') {
                return (
                  <View
                    key={action.id}
                    style={[
                      styles.accountMenuToggleRow,
                      action.disabled && styles.optionButtonDisabled,
                    ]}>
                    <View style={styles.accountMenuToggleLeft}>
                      <Icon
                        name={action.icon}
                        size={22}
                        color={colors.text.primary}
                      />
                      <Text style={styles.accountMenuToggleLabel}>{action.label}</Text>
                    </View>
                    <ToggleSwitch
                      value={Boolean(action.value)}
                      onValueChange={action.onValueChange}
                      disabled={action.disabled}
                    />
                  </View>
                );
              }

              return (
                <TouchableOpacity
                  key={action.id}
                  style={[
                    styles.optionButton,
                    action.variant === 'danger' && styles.optionDelete,
                  ]}
                  onPress={action.onPress}
                  disabled={action.disabled}>
                  <View style={styles.optionItemRow}>
                    <Icon
                      name={action.icon}
                      size={20}
                      color={action.variant === 'danger' ? '#B91C1C' : colors.text.primary}
                    />
                    <Text
                      style={[
                        styles.optionText,
                        action.variant === 'danger' && styles.optionDeleteText,
                      ]}>
                      {action.label}
                    </Text>
                  </View>
                </TouchableOpacity>
              );
            })}
            {isSavingAccount && (
              <>
                <View style={styles.accountMenuDivider} />
                <View style={styles.accountMenuToggleRow}>
                  <View style={styles.accountMenuToggleLeft}>
                    <Icon name="eye-outline" size={22} color={colors.text.primary} />
                    <Text style={styles.accountMenuToggleLabel}>show balance in dashboard</Text>
                  </View>
                  <ToggleSwitch
                    value={showBalanceInDashboard}
                    onValueChange={handleToggleShowBalanceInDashboard}
                    trackColor={{false: '#D1D5DB', true: '#86EFAC'}}
                    thumbColor={showBalanceInDashboard ? '#16A34A' : '#F9FAFB'}
                  />
                </View>
              </>
            )}
            {accountMenuPersonalizeAction && (
              <TouchableOpacity
                key={accountMenuPersonalizeAction.id}
                style={[
                  styles.optionButton,
                  accountMenuPersonalizeAction.variant === 'danger' && styles.optionDelete,
                ]}
                onPress={accountMenuPersonalizeAction.onPress}
                disabled={accountMenuPersonalizeAction.disabled}>
                <View style={styles.optionItemRow}>
                  <Icon
                    name={accountMenuPersonalizeAction.icon}
                    size={20}
                    color={
                      accountMenuPersonalizeAction.variant === 'danger'
                        ? '#B91C1C'
                        : colors.text.primary
                    }
                  />
                  <Text
                    style={[
                      styles.optionText,
                      accountMenuPersonalizeAction.variant === 'danger' &&
                        styles.optionDeleteText,
                    ]}>
                    {accountMenuPersonalizeAction.label}
                  </Text>
                </View>
              </TouchableOpacity>
            )}
      </DropdownPopup>

      <EditAmountModal
        visible={editAmountVisible}
        value={editAmount}
        onChangeText={setEditAmount}
        onSave={handleUpdateAmount}
        onClose={() => setEditAmountVisible(false)}
        loading={loading}
        autoFocus
      />

      <EditRemarkModalSheet
        visible={editRemarkVisible}
        onClose={() => setEditRemarkVisible(false)}
        value={editRemark}
        onChangeText={setEditRemark}
        onSave={handleUpdateRemark}
        loading={loading}
      />

      <RenameAccountModal
        visible={renameModalVisible}
        value={newAccountName}
        onChange={setNewAccountName}
        onSave={handleSaveAccountName}
        onClose={closeRenameModal}
        loading={loading}
        inputRef={renameInputRef}
        styles={styles}
      />

      <BottomSheet
        visible={isBottomSheetVisible}
        onClose={() => setBottomSheetVisible(false)}>
        {renderBottomSheetContent()}
      </BottomSheet>
      <BottomSheet
        visible={addReceiptSheetVisible}
        onClose={() => setAddReceiptSheetVisible(false)}>
        {renderAddReceiptSheet()}
      </BottomSheet>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: colors.background,
  },
  stickyHeader: {
    backgroundColor: colors.headerBg,
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    zIndex: 20,
    elevation: 4,
  },
  header: {
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.sm,
    backgroundColor: colors.headerBg,
    borderBottomWidth: 1,
    borderBottomColor: headerTexture.border,
    elevation: 2,
  },
  headerTopRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    minHeight: 64,
  },
  backButton: {
    padding: 6,
  },
  headerTitle: {
    fontSize: fontSize.large,
    fontWeight: fontWeight.semibold,
    color: headerTexture.title,
    textAlign: 'left',
  },
  headerTitleBlock: {
    flex: 1,
    alignItems: 'flex-start',
    justifyContent: 'center',
    paddingHorizontal: spacing.xs,
  },
  headerSubtitle: {
    marginTop: 2,
    fontSize: fontSize.small,
    fontWeight: fontWeight.medium,
    color: headerTexture.title,
    textAlign: 'left',
    opacity: 0.78,
  },
  headerActions: {
    flexDirection: 'row',
    alignItems: 'center',
    marginLeft: spacing.xs,
  },
  accountAvatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
    backgroundColor: colors.white,
    borderWidth: 1,
    borderColor: 'rgba(240,253,244,0.38)',
    justifyContent: 'center',
    alignItems: 'center',
    marginLeft: spacing.xs,
    marginRight: spacing.sm,
  },
  accountAvatarTap: {
    marginLeft: spacing.xs,
  },
  backupButton: {
    padding: 6,
  },
  backupIconWrapper: {
    width: 24,
    height: 24,
    alignItems: 'center',
    justifyContent: 'center',
  },
  backupSpinner: {
    position: 'absolute',
    width: 30,
    height: 30,
  },
  menuButton: {
    padding: 6,
  },
