      if (paidDefaultChoice === LEDGER_PAID_DEFAULT_DEBIT) {
        await submitTransaction(true);
        return;
      }
      if (paidDefaultChoice === LEDGER_PAID_DEFAULT_RECORD) {
        await submitTransaction(false);
        return;
      }
      setPaidPromptVisible(true);
      return;
    }

    await submitTransaction(false);
  };

  const formatCurrency = amount => {
    return `${currencySymbol} ${Math.abs(amount).toLocaleString('en-IN')}`;
  };

  const formatSignedBalance = amount => {
    if (amount < 0) {
      return `- ${formatCurrency(amount)}`;
    }
    return formatCurrency(amount);
  };

  const formatDateLabel = timestamp => {
    const date = new Date(timestamp);
    return date.toLocaleDateString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    });
  };

  const canEditTransaction = txn => {
    if (!txn) {
      return false;
    }
    const txnSourceUserId = String(txn.source_user_id || '').trim();
    const currentUserIdValue = String(currentUserId || '').trim();
    if (!txnSourceUserId || !currentUserIdValue || txnSourceUserId !== currentUserIdValue) {
      return false;
    }
    if (Number(txn.is_deleted) === 1) {
      return false;
    }
    if (Number(txn.edit_count) >= 3) {
      return false;
    }
    return txn.id !== null && txn.id !== undefined;
  };

  const canEditRemarkTransaction = txn => {
    if (!txn) {
      return false;
    }
    const txnSourceUserId = String(txn.source_user_id || '').trim();
    const currentUserIdValue = String(currentUserId || '').trim();
    if (!txnSourceUserId || !currentUserIdValue || txnSourceUserId !== currentUserIdValue) {
      return false;
    }
    if (Number(txn.is_deleted) === 1) {
      return false;
    }
    return txn.id !== null && txn.id !== undefined;
  };

  const isCreatorRestrictedEdit = txn => {
    if (!txn) {
      return false;
    }
    const txnSourceUserId = String(txn.source_user_id || '').trim();
    const currentUserIdValue = String(currentUserId || '').trim();
    if (!txnSourceUserId || !currentUserIdValue) {
      return false;
    }
    return txnSourceUserId !== currentUserIdValue;
  };

  const showCreatorOnlyAmountEditWarning = () => {
    Alert.alert(
      'Edit Restricted',
      "Amount can't be edited because you are not the creator."
    );
  };

  const showCreatorOnlyRemarkEditWarning = () => {
    Alert.alert(
      'Edit Restricted',
      "Remark can't be edited because you are not the creator."
    );
  };

  const canDeleteTransaction = txn => {
    if (!txn) {
      return false;
    }
    if (Number(txn.is_deleted) === 1) {
      return false;
    }
    return txn.id !== null && txn.id !== undefined;
  };

  const isOwnLedgerTransaction = txn => {
    if (!txn) {
      return false;
    }
    const txnSourceUserId = String(txn.source_user_id || '').trim();
    if (!txnSourceUserId) {
      return true;
    }
    const currentUserIdValue = String(currentUserId || '').trim();
    if (currentUserIdValue && txnSourceUserId === currentUserIdValue) {
      return true;
    }
    const contactUserIds = new Set(
      [
        appUser?.firebaseUid,
        appUser?.userId,
        contact?.firebaseUid,
        contact?.userId,
      ]
        .map(value => String(value || '').trim())
        .filter(Boolean),
    );
    if (contactUserIds.has(txnSourceUserId)) {
      return false;
    }
    if (!currentUserIdValue) {
      return false;
    }
    return false;
  };

  const canSyncTransaction = txn => {
    if (!txn) {
      return false;
    }
    if (Number(txn.is_deleted) === 1) {
      return false;
    }
    if (!syncAllEntriesEnabled || syncingSelectedEntry) {
      return false;
    }
    return true;
  };

  const parseSourceOriginKey = value => {
    const raw = String(value || '').trim();
    if (!raw) {
      return null;
    }
    const separatorIndex = raw.indexOf(':');
    if (separatorIndex <= 0 || separatorIndex >= raw.length - 1) {
      return null;
    }
    const sourceId = raw.slice(0, separatorIndex).trim();
    const originId = raw.slice(separatorIndex + 1).trim();
    if (!sourceId || !originId) {
      return null;
    }
    return {sourceId, originId};
  };

  const resolveCanonicalOriginForTransaction = async txn => {
    const parsedOrigin = parseSourceOriginKey(txn?.source_origin_key);
    if (parsedOrigin?.sourceId && parsedOrigin?.originId) {
      return {
        canonicalSourceUserId: parsedOrigin.sourceId,
        canonicalOriginTxnId: parsedOrigin.originId,
      };
    }

    const fallbackSourceUserId = String(
      currentUserId || (await AsyncStorage.getItem('firebaseUid')) || '',
    ).trim();
    const fallbackOriginTxnId = String(txn?.id || '').trim();

    if (!fallbackSourceUserId || !fallbackOriginTxnId) {
      return null;
    }

    return {
      canonicalSourceUserId: fallbackSourceUserId,
      canonicalOriginTxnId: fallbackOriginTxnId,
    };
  };

  const encodeCanonicalOriginTxnId = (sourceUserIdValue, originTxnIdValue) => {
    return `canon#${encodeURIComponent(sourceUserIdValue)}#${encodeURIComponent(originTxnIdValue)}`;
  };

  const parseLedgerEditHistory = txn => {
    try {
      const raw = String(txn?.edit_history || '').trim();
      if (!raw) {
        return [];
      }
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) {
        return [];
      }
      return parsed
        .map(value => Number(value))
        .filter(value => Number.isFinite(value) && value >= 0);
    } catch (error) {
      return [];
    }
  };

  const openTransactionMenu = txn => {
    if (!txn || Number(txn.is_deleted) === 1) {
      return;
    }
    setSelectedTransaction(txn);
    setOptionsVisible(true);
  };

  const closeTransactionMenu = () => {
    setOptionsVisible(false);
    setSelectedTransaction(null);
  };

  const handleEditAmount = () => {
    if (!selectedTransaction || !canEditTransaction(selectedTransaction)) {
      return;
    }
    const currentAbs = Math.abs(Number(selectedTransaction.amount) || 0);
    setEditAmount(String(currentAbs || ''));
    setEditAmountVisible(true);
    setOptionsVisible(false);
  };

  const handleEditRemark = () => {
    if (!selectedTransaction || !canEditRemarkTransaction(selectedTransaction)) {
      return;
    }
    setEditRemark(selectedTransaction.note || '');
    setEditRemarkVisible(true);
    setOptionsVisible(false);
  };

  const handleSaveEditAmount = async () => {
    if (!selectedTransaction) {
      return;
    }
    const parsed = parseFloat(String(editAmount).replace(/[^0-9.]/g, ''));
    if (!parsed || parsed <= 0) {
      showToast('Please enter a valid amount.', 'error');
      return;
    }
    if (!canEditTransaction(selectedTransaction)) {
      showToast('Edit not allowed.', 'error');
      return;
    }
    const nextAmount = selectedTransaction.type === 'paid' ? parsed : parsed;
    const nextEditCount = Number(selectedTransaction.edit_count || 0) + 1;
    setLoading(true);
    try {
      await updateLedgerTransactionAmount(selectedTransaction.id, nextAmount, nextEditCount);

      try {
        if (syncAllEntriesEnabled && contact?.recordID) {
          const resolvedSourceUserId = String(
            currentUserId || (await AsyncStorage.getItem('firebaseUid')) || '',
          ).trim();
          const resolvedPeerUserId = await resolvePeerUserIdForSync();
          if (resolvedSourceUserId && resolvedPeerUserId) {
            const updatedTxn = getLedgerTransactionById(selectedTransaction.id) || selectedTransaction;
            const canonicalOrigin = await resolveCanonicalOriginForTransaction(updatedTxn);
            if (
              canonicalOrigin?.canonicalSourceUserId &&
              canonicalOrigin?.canonicalOriginTxnId
            ) {
              const encodedOriginTxnId = encodeCanonicalOriginTxnId(
                canonicalOrigin.canonicalSourceUserId,
                canonicalOrigin.canonicalOriginTxnId,
              );
              const syncEvent = buildLedgerCreateEvent({
                originTxnId: encodedOriginTxnId,
                sourceUserId: resolvedSourceUserId,
                peerUserId: resolvedPeerUserId,
                contactRecordId: contact.recordID,
                type: updatedTxn.type === 'get' ? 'get' : 'paid',
                amount: Math.abs(Number(updatedTxn.amount || 0)),
                note: String(updatedTxn.note || ''),
                editHistory: parseLedgerEditHistory(updatedTxn),
                timestamp: Number(updatedTxn.transaction_date || Date.now()) || Date.now(),
                createdAt: Number(updatedTxn.created_at || 0) || Date.now(),
              });
              await sendLedgerEvent({
                ...syncEvent,
                idempotencyKey: `ledger-edit:${resolvedSourceUserId}:${canonicalOrigin.canonicalSourceUserId}:${canonicalOrigin.canonicalOriginTxnId}:${Date.now()}_${Math.random()
                  .toString(36)
                  .slice(2, 8)}`,
                syncMode: 'single_entry',
                silentSync: true,
              });
            }
          }
        }
      } catch (syncError) {
        console.error('[LEDGER_SYNC] failed to sync edited amount event:', syncError);
      }

      setEditAmountVisible(false);
      setEditAmount('');
      setSelectedTransaction(null);
      await loadData();
    } catch (error) {
      console.error('Failed to update amount:', error);
      Alert.alert('Error', 'Failed to update amount. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEditRemark = async () => {
    if (!selectedTransaction) {
      return;
    }
    if (!canEditRemarkTransaction(selectedTransaction)) {
      showToast('Edit not allowed.', 'error');
      return;
    }
    setLoading(true);
    try {
      await updateLedgerTransactionNote(selectedTransaction.id, editRemark.trim());
      setEditRemarkVisible(false);
      setEditRemark('');
      setSelectedTransaction(null);
      await loadData();
    } catch (error) {
      console.error('Failed to update remark:', error);
      Alert.alert('Error', 'Failed to update remark. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteTransaction = () => {
    if (!selectedTransaction || !canDeleteTransaction(selectedTransaction)) {
      return;
    }
    Alert.alert('Delete Entry', 'Are you sure you want to delete this entry?', [
      {text: 'Cancel', style: 'cancel'},
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          setLoading(true);
          try {
            await deleteTransaction(selectedTransaction.id);
            closeTransactionMenu();
            await loadData();
          } catch (error) {
            console.error('Failed to delete transaction:', error);
            Alert.alert('Error', 'Failed to delete entry.');
          } finally {
            setLoading(false);
          }
        },
      },
    ]);
  };

  const handleSyncThisEntryWithUser = async () => {
    const txn = selectedTransaction;
    if (!txn) {
      return;
    }
    if (!contact?.recordID) {
      showToast('Contact information not found', 'error');
      return;
    }
    if (!syncAllEntriesEnabled) {
      showToast('Turn on sync enteries with user first', 'error');
      return;
    }
    const amountValue = Math.abs(Number(txn.amount || 0));
    if (!amountValue) {
      showToast('Invalid transaction amount', 'error');
      return;
    }

    setSyncingSelectedEntry(true);
    try {
      const resolvedSourceUserId = String(
        currentUserId || (await AsyncStorage.getItem('firebaseUid')) || '',
      ).trim();
      if (!resolvedSourceUserId) {
        throw new Error('Current user not found');
      }

      const resolvedPeerUserId = await resolvePeerUserIdForSync();
      if (!resolvedPeerUserId) {
        throw new Error('Could not resolve contact app user');
      }

      const timestamp =
        Number(txn.transaction_date || txn.created_at || Date.now()) || Date.now();
      const entryType = txn.type === 'get' ? 'get' : 'paid';
      const canonicalOrigin = await resolveCanonicalOriginForTransaction(txn);
      if (!canonicalOrigin?.canonicalSourceUserId || !canonicalOrigin?.canonicalOriginTxnId) {
        throw new Error('Unable to resolve canonical origin');
      }
      const encodedOriginTxnId = encodeCanonicalOriginTxnId(
        canonicalOrigin.canonicalSourceUserId,
        canonicalOrigin.canonicalOriginTxnId,
      );
      const manualSyncNonce = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
      const manualIdempotencyKey = `ledger-manual:${resolvedSourceUserId}:${canonicalOrigin.canonicalSourceUserId}:${canonicalOrigin.canonicalOriginTxnId}:${manualSyncNonce}`;

      const eventPayload = {
        ...buildLedgerCreateEvent({
          originTxnId: encodedOriginTxnId,
          sourceUserId: resolvedSourceUserId,
          peerUserId: resolvedPeerUserId,
          contactRecordId: contact.recordID,
          type: entryType,
          amount: amountValue,
          note: String(txn.note || ''),
          editHistory: parseLedgerEditHistory(txn),
          timestamp,
          createdAt: Number(txn.created_at || 0) || Date.now(),
        }),
        idempotencyKey: manualIdempotencyKey,
        syncMode: 'single_entry',
        silentSync: true,
      };

      const result = await sendLedgerEvent(eventPayload, {withResult: true});
      closeTransactionMenu();

      if (result?.delivered) {
        showToast('Entry synced with user', 'success');
      } else if (result?.queued) {
        showToast('Entry queued for sync', 'success');
      } else if (result?.skipped && result?.reason === 'sync_disabled') {
        showToast('Sync is disabled for this contact', 'error');
      } else {
        showToast('Sync not confirmed. Please retry.', 'error');
      }
    } catch (error) {
      console.error('Failed to sync selected transaction:', error);
      showToast('Failed to sync this entry', 'error');
    } finally {
      setSyncingSelectedEntry(false);
    }
  };

  const formatTimeLabel = timestamp => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('en-IN', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const isBackdatedTransaction = txn => {
    const transactionDate = Number(txn?.transaction_date || 0);
    const createdAt = Number(txn?.created_at || 0);
    if (!Number.isFinite(transactionDate) || transactionDate <= 0) {
      return false;
    }
    if (!Number.isFinite(createdAt) || createdAt <= 0) {
      return false;
    }
    return new Date(transactionDate).toDateString() !== new Date(createdAt).toDateString();
  };

  const balanceAfterById = useMemo(() => {
    const map = {};
    let running = 0;
    const ordered = [...(transactions || [])].sort(
      (a, b) => (a.transaction_date || 0) - (b.transaction_date || 0)
    );
    ordered.forEach(txn => {
      if (Number(txn.is_deleted) === 1) {
        map[txn.id] = running;
        return;
      }
      const amountValue = Number(txn.amount) || 0;
      const isPaid = txn.type === 'paid';
      running += isPaid ? amountValue : -amountValue;
      map[txn.id] = running;
    });
    return map;
  }, [transactions]);

  const getTimelineItemTimestamp = item => {
    if (!item) {
      return null;
    }
    if (item.type === 'transaction') {
      return item?.data?.transaction_date || item?.timestamp || null;
    }
    if (item.type === 'message') {
      return item?.data?.timestamp || item?.timestamp || null;
    }
    return item?.timestamp || null;
  };

  const timelineForList = useMemo(() => {
    const items = unifiedTimeline || [];
    return items.map((item, index) => {
      const currentTs = getTimelineItemTimestamp(item);
      if (!currentTs) {
        return {...item, showDate: false};
      }
      const currentDateKey = new Date(currentTs).toDateString();
      const nextItem = items[index + 1];
      const nextTs = getTimelineItemTimestamp(nextItem);
      const nextDateKey = nextTs ? new Date(nextTs).toDateString() : null;
      const showDate = !nextDateKey || currentDateKey !== nextDateKey;
      return {...item, showDate};
    });
  }, [unifiedTimeline]);

  const selectedCount = useMemo(
    () => Object.keys(selectedMessageIds).length,
    [selectedMessageIds]
  );

  const getMessageId = useCallback(message => {
    const resolvedId = message?.message_id || message?.id;
    return String(resolvedId || '').trim();
  }, []);

  const clearSelectionMode = useCallback(() => {
    setIsSelectionMode(false);
    setSelectedMessageIds({});
  }, []);

  const enterSelectionMode = useCallback(messageId => {
    const id = String(messageId || '').trim();
    if (!id) {
      return;
    }
    setIsSelectionMode(true);
    setSelectedMessageIds(prev => ({...prev, [id]: true}));
  }, []);

  const toggleMessageSelection = useCallback(messageId => {
    const id = String(messageId || '').trim();
    if (!id) {
      return;
    }
    setIsSelectionMode(true);
    setSelectedMessageIds(prev => {
      const next = {...prev};
      if (next[id]) {
        delete next[id];
      } else {
        next[id] = true;
      }
      return next;
    });
  }, []);

  const selectedMessages = useMemo(() => {
    const selected = [];
    timelineForList.forEach(item => {
      if (item?.type !== 'message') {
        return;
      }
      const messageId = getMessageId(item?.data);
      if (messageId && selectedMessageIds[messageId]) {
        selected.push(item.data);
      }
    });
    return selected;
  }, [timelineForList, selectedMessageIds, getMessageId]);

  const handleCopySelectedMessages = () => {
    if (selectedMessages.length === 0) {
      showToast('No messages selected', 'error');
      return;
    }
    const ordered = [...selectedMessages].sort(
      (a, b) => (a?.timestamp || 0) - (b?.timestamp || 0)
    );
    const payload = ordered
      .map(message => {
        const isSent = String(message?.sender_id || '') === String(currentUserId || '');
        const senderName = isSent ? 'You' : getContactFirstName();
        const timeLabel = formatTimeLabel(message?.timestamp);
        const textValue = String(message?.message_text || '').trim();
        return `${senderName} • ${timeLabel}\n${textValue}`;
      })
      .join('\n\n');

    Clipboard.setString(payload);
    showToast(
      `${ordered.length} message${ordered.length > 1 ? 's' : ''} copied`,
      'success'
    );
    clearSelectionMode();
  };

  const handleDeleteSelectedMessages = () => {
    const ids = Object.keys(selectedMessageIds);
    if (ids.length === 0) {
      showToast('No messages selected', 'error');
      return;
    }
    const count = ids.length;
    Alert.alert(
      'Delete Messages',
      `Delete ${count} selected message${count > 1 ? 's' : ''}?`,
      [
        {text: 'Cancel', style: 'cancel'},
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            try {
              setLoading(true);
              deleteMessagesHard(ids);

              if (conversationId) {
                const latestMessage = getLatestConversationMessage(conversationId);
                updateConversation(conversationId, {
                  lastMessageText: latestMessage?.message_text || '',
                  lastMessageTimestamp: latestMessage?.timestamp || 0,
                });
                await loadUnifiedTimeline(conversationId);
              }

              showToast(
                `${count} message${count > 1 ? 's' : ''} deleted`,
                'success'
              );
              clearSelectionMode();
            } catch (error) {
              console.error('Failed to delete selected messages:', error);
              showToast('Failed to delete selected messages', 'error');
            } finally {
              setLoading(false);
            }
          },
        },
      ]
    );
  };

  useEffect(() => {
    if (!isSelectionMode) {
      return;
    }
    setHeaderMenuVisible(false);
    setOptionsVisible(false);
    setShouldHideActionButtons(false);
    chatInputRef.current?.blur?.();
    Keyboard.dismiss();
  }, [isSelectionMode]);

  useEffect(() => {
    const timelineCount = timelineForList.length;
    const emptyVisible = timelineCount === 0 && isAppUser !== null && !loadingChat;

    if (emptyVisible && !emptyVisibleRef.current) {
      emptyVisibleRef.current = true;
      perfLog('render:empty-visible', {
        contactId: String(contact?.recordID || ''),
        timelineCount,
        isAppUser,
        loadingChat,
        sinceMountMs: Date.now() - screenOpenAtRef.current,
      });
    }

    if (!emptyVisible && emptyVisibleRef.current) {
      perfLog('render:empty-hidden', {
        contactId: String(contact?.recordID || ''),
        timelineCount,
        isAppUser,
        loadingChat,
        sinceMountMs: Date.now() - screenOpenAtRef.current,
      });
      emptyVisibleRef.current = false;
    }

    if (timelineCount > 0 && !firstDataVisibleRef.current) {
      firstDataVisibleRef.current = true;
      perfLog('render:first-data-visible', {
        contactId: String(contact?.recordID || ''),
        timelineCount,
        isAppUser,
        loadingChat,
        sinceMountMs: Date.now() - screenOpenAtRef.current,
      });
    }
  }, [timelineForList.length, isAppUser, loadingChat, contact?.recordID]);

  // Render chat message bubble (using currentUserId from state)
  const renderChatMessage = (message, currentUserId, showDate) => {
    const isSent = message.sender_id === currentUserId;
    const messageId = getMessageId(message);
    const isSelected = Boolean(messageId && selectedMessageIds[messageId]);
    const deliveryStatus = String(message?.delivery_status || '').toLowerCase();
    const showDoubleTick = deliveryStatus === 'delivered' || deliveryStatus === 'read';
    const showSingleTick =
      !showDoubleTick &&
      (deliveryStatus === 'sent' ||
        deliveryStatus === 'sending' ||
        deliveryStatus === 'pending' ||
        deliveryStatus === 'queued' ||
        deliveryStatus === 'accepted' ||
        deliveryStatus === 'pushed');
    const tickIconName = showDoubleTick ? 'checkmark-done' : showSingleTick ? 'checkmark' : null;
    const tickColor = deliveryStatus === 'read' ? '#38BDF8' : '#6B7280';

    return (
      <View>
        {showDate && (
          <View style={styles.datePill}>
            <Text style={styles.datePillText}>
              {formatDateLabel(message.timestamp)}
            </Text>
          </View>
        )}
        <TapEffect
          style={styles.chatRow}
          onLongPress={() => enterSelectionMode(messageId)}
          onPress={() => {
            if (!isSelectionMode) {
              return;
            }
            toggleMessageSelection(messageId);
          }}
          delayLongPress={250}>
          <View
            style={[
              styles.messageSelectableRow,
              isSent ? styles.messageSelectableRowSent : styles.messageSelectableRowReceived,
            ]}>
            {isSelectionMode ? (
              <View
                style={[
                  styles.messageSelectionDot,
                  isSelected && styles.messageSelectionDotSelected,
                ]}>
                {isSelected ? (
                  <Icon name="checkmark" size={12} color={colors.white} />
                ) : null}
              </View>
            ) : null}
            <View
              style={[
                styles.chatBubble,
                isSent ? styles.chatBubbleSent : styles.chatBubbleReceived,
                isSelected && styles.chatBubbleSelected,
              ]}>
              <Text style={styles.chatMessageText}>{message.message_text}</Text>
              <View style={styles.chatMetaRow}>
                <Text style={styles.chatTime}>
                  {formatTimeLabel(message.timestamp)}
                </Text>
                {isSent && tickIconName ? (
                  <Icon
                    name={tickIconName}
                    size={14}
                    color={tickColor}
                    style={styles.chatTickIcon}
                  />
                ) : null}
              </View>
            </View>
          </View>
        </TapEffect>
      </View>
    );
  };

  const renderTimelineItem = (item) => {
    if (!item) {
      return null;
    }

    if (item.type === 'message') {
      return renderChatMessage(item.data, currentUserId, item.showDate);
    }

    const transaction = item.data;
    if (!transaction) {
      return null;
    }

    const amountValue = Number(transaction.amount) || 0;
    const isPaid = transaction.type === 'paid';
    const isDeleted = Number(transaction.is_deleted) === 1;
    const isOwnTransaction = isOwnLedgerTransaction(transaction);
    const ownerBadgeLabel = isOwnTransaction ? 'You' : getContactFirstName();
    const hasSyncedTag = String(transaction.sync_tag || '').toLowerCase() === 'synced';
    const hasBackdatedTag = isBackdatedTransaction(transaction);
    const editHistory = parseLedgerEditHistory(transaction);
    const createdOnLabel = hasBackdatedTag
      ? formatDateLabel(transaction.created_at)
      : '';

    return (
      <View>
        {item.showDate && (
          <View style={styles.datePill}>
            <Text style={styles.datePillText}>
              {formatDateLabel(transaction.transaction_date)}
            </Text>
          </View>
        )}
        <TapEffect
          style={[styles.chatRow, isPaid && styles.chatRowDebit]}
          {...getDeletedTapEffectProps(
            isDeleted,
            () => openTransactionMenu(transaction),
          )}
          delayLongPress={250}>
          <View
            style={[
              styles.chatBubble,
              isPaid ? styles.chatBubbleDebit : styles.chatBubbleCredit,
              isDeleted && deletedUiStyles.bubble,
            ]}>
            <View style={styles.chatHeader}>
              <View
                style={[
                  styles.chatIcon,
                  isPaid && styles.chatIconDebit,
                  isDeleted && deletedUiStyles.iconContainer,
                ]}>
                <Icon
                  name={isPaid ? 'arrow-up' : 'arrow-down'}
                  size={16}
                  color={getDeletedIconColor(
                    isDeleted,
                    isPaid ? '#EF4444' : '#10B981',
                  )}
                />
              </View>
              <Text
                style={withDeletedStyle(
                  isDeleted,
                  [styles.chatAmount, isPaid && styles.chatAmountDebit],
                  deletedUiStyles.amount,
                )}>
                {`${isPaid ? '-' : '+'} ${formatCurrency(amountValue)}`}
              </Text>
              <View style={styles.chatHeaderRight}>
                <View style={styles.chatHeaderMetaRow}>
                  <View
                    style={withDeletedStyle(
                      isDeleted,
                      [
                        styles.ownerBadge,
                        isOwnTransaction ? styles.ownerBadgeYou : styles.ownerBadgeOther,
                      ],
                      deletedUiStyles.mutedBadge,
                    )}>
                    <Text
                      style={withDeletedStyle(
                        isDeleted,
                        [
                          styles.ownerBadgeText,
                          isOwnTransaction
                            ? styles.ownerBadgeTextYou
                            : styles.ownerBadgeTextOther,
                        ],
                        deletedUiStyles.mutedText,
                      )}>
                      {ownerBadgeLabel}
                    </Text>
                  </View>
                  <Text style={styles.chatTime}>
                    {formatTimeLabel(transaction.transaction_date)}
                  </Text>
                </View>
                {hasSyncedTag ? (
                  <View
                    style={withDeletedStyle(
                      isDeleted,
                      [styles.syncedTagBadge],
                      deletedUiStyles.mutedBadge,
                    )}>
                    <Text
                      style={withDeletedStyle(
                        isDeleted,
                        [styles.syncedTagText],
                        deletedUiStyles.mutedText,
                      )}>
                      synced
                    </Text>
                  </View>
                ) : null}
                {renderDeletedBadge(isDeleted)}
                {hasBackdatedTag ? (
                  <View
                    style={withDeletedStyle(
                      isDeleted,
                      [styles.backdatedTagBadge],
                      deletedUiStyles.mutedBadge,
                    )}>
                    <Text
                      style={withDeletedStyle(
                        isDeleted,
                        [styles.backdatedTagText],
                        deletedUiStyles.mutedText,
                      )}>
                      backdated
                    </Text>
                  </View>
                ) : null}
                {hasBackdatedTag ? (
                  <View style={styles.backdatedMetaWrap}>
                    <Text
                      style={withDeletedStyle(
                        isDeleted,
                        [styles.backdatedCreatedOnText],
                        deletedUiStyles.mutedMetaText,
                      )}>
                      {`created on ${createdOnLabel}`}
                    </Text>
                  </View>
                ) : null}
              </View>
            </View>
            {isDeleted ? (
              renderDeletedNote(isDeleted)
            ) : transaction.note ? (
              <Text style={styles.chatRemark}>{transaction.note}</Text>
            ) : null}
            {!isDeleted && editHistory.length > 1 ? (
              <Text style={styles.editHistoryText}>
                {`edited amount: ${editHistory
                  .map(value => formatCurrency(Math.abs(Number(value) || 0)))
                  .join(' -> ')}`}
              </Text>
            ) : null}
          </View>
          <View style={[styles.chatMeta, isPaid && styles.chatMetaDebit]}>
            <Text style={styles.chatBalance}>
              {formatSignedBalance(balanceAfterById[transaction.id] || 0)}
            </Text>
          </View>
        </TapEffect>
      </View>
    );
  };

  const shouldShowEmptyHistory =
    !timelineLoading && hasLoadedTimeline && isAppUser !== null && !loadingChat && timelineForList.length === 0;
  const headerAvatarUri = String(
    contact?.thumbnailPath || appUser?.photoURL || appUser?.photo_url || ''
  ).trim();
  const headerInitial = (getContactName().charAt(0) || '?').toUpperCase();

  return (
    <View style={styles.container}>
      <View style={styles.content}>
      {/* Header + Totals */}
      <TexturedSurface
        style={[
          styles.headerBlock,
          {
            paddingTop: spacing.sm + insets.top,
          },
        ]}>
        <View style={styles.headerRow} onLayout={handleHeaderLayout}>
          {isSelectionMode ? (
            <>
              <TouchableOpacity
                style={styles.backButton}
                onPress={clearSelectionMode}
                accessibilityRole="button"
                accessibilityLabel="Cancel selection">
                <Icon name="close" size={24} color={headerTexture.icon} />
              </TouchableOpacity>
              <Text style={styles.selectionHeaderTitle} numberOfLines={1}>
                {`${selectedCount} selected`}
              </Text>
              <View style={styles.selectionHeaderActions}>
                <TouchableOpacity
                  style={styles.selectionHeaderActionButton}
                  onPress={handleCopySelectedMessages}
                  disabled={selectedCount === 0}
                  activeOpacity={0.8}>
                  <Icon
                    name="copy-outline"
                    size={22}
                    color={selectedCount > 0 ? headerTexture.icon : 'rgba(255,255,255,0.6)'}
                  />
                </TouchableOpacity>
                <TouchableOpacity
                  style={styles.selectionHeaderActionButton}
                  onPress={handleDeleteSelectedMessages}
                  disabled={selectedCount === 0}
                  activeOpacity={0.8}>
                  <Icon
                    name="trash-outline"
                    size={22}
                    color={selectedCount > 0 ? '#FCA5A5' : 'rgba(255,255,255,0.6)'}
                  />
                </TouchableOpacity>
              </View>
            </>
          ) : (
            <>
              <TouchableOpacity
                style={styles.backButton}
                onPress={() => {
                  perfLog('back:header-press', {
                    shouldHideActionButtons,
                  });
                  chatInputRef.current?.blur?.();
                  Keyboard.dismiss();
                  setShouldHideActionButtons(false);
                  if (navigation.canGoBack()) {
                    navigation.goBack();
                  } else {
                    navigation.reset({
                      index: 0,
                      routes: [{name: 'Home'}],
                    });
                  }
                }}>
                <Icon name="chevron-back" size={22} color={headerTexture.icon} />
              </TouchableOpacity>
              <TouchableOpacity
                style={styles.headerIdentity}
                activeOpacity={0.8}
                onPress={openContactProfileScreen}>
                <View style={styles.headerAvatar}>
                  {headerAvatarUri ? (
                    <Image
                      source={{uri: headerAvatarUri}}
                      style={styles.headerAvatarImage}
                      resizeMode="cover"
                    />
                  ) : (
                    <Text style={styles.headerAvatarText}>{headerInitial}</Text>
                  )}
                </View>
                <View style={styles.headerTitleBlock}>
                  <Text style={styles.headerTitle} numberOfLines={1}>
                    {getContactName()}
                  </Text>
                  {headerPhone ? (
                    <Text style={styles.headerSubtitle} numberOfLines={1}>
                      {headerPhone}
                    </Text>
                  ) : null}
                </View>
              </TouchableOpacity>
              <View ref={menuButtonRef} collapsable={false}>
                <TouchableOpacity
                  style={styles.menuButton}
                  onPress={handleHeaderMenuPress}
                  accessibilityRole="button"
                  accessibilityLabel="Contact menu"
                  activeOpacity={0.8}>
                  <Icon name="ellipsis-vertical" size={24} color={headerTexture.icon} />
                </TouchableOpacity>
              </View>
            </>
          )}
        </View>
      </TexturedSurface>
      {!isSelectionMode && (
      <View style={styles.metricsSection}>
        <View style={styles.metricsRow}>
          <View style={styles.metricColumn}>
            <View style={styles.metricLabelRow}>
              <Text style={styles.metricLabel}>Total Paid</Text>
            </View>
            <Text style={[styles.metricValue, styles.metricNegative]}>
              {formatCurrency(balance.totalPaid)}
            </Text>
          </View>
          <View style={styles.metricDivider} />
          <View style={styles.metricColumn}>
            <View style={styles.metricLabelRow}>
              <Text style={styles.metricLabel}>Total Received</Text>
            </View>
            <Text style={[styles.metricValue, styles.metricPositive]}>
              {formatCurrency(balance.totalGet)}
            </Text>
          </View>
          <View style={styles.metricDivider} />
          <View style={styles.metricColumn}>
            <View style={styles.metricLabelRow}>
              <Text style={styles.metricLabel}>Net Balance</Text>
            </View>
            <Text
              style={[
                styles.metricValue,
                balance.netBalance < 0
                  ? styles.metricPositive
                  : balance.netBalance > 0
                  ? styles.metricNegative
                  : null,
              ]}>
              {formatSignedBalance(balance.netBalance)}
            </Text>
          </View>
        </View>
      </View>
      )}
      

      <AnimatedFlatList
        ref={listRef}
        data={timelineForList}
        keyExtractor={item => item.id}
        style={styles.scrollView}
        contentContainerStyle={[
          styles.scrollContent,
          styles.historySection,
          styles.chatList,
        ]}
        showsVerticalScrollIndicator={false}
        keyboardShouldPersistTaps="always"
        inverted
        initialNumToRender={16}
        maxToRenderPerBatch={12}
        updateCellsBatchingPeriod={45}
        windowSize={9}
        removeClippedSubviews
        renderItem={({item}) => renderTimelineItem(item)}
        ListHeaderComponent={<View style={{height: listKeyboardSpacerHeight}} />}
        ListFooterComponent={<View style={{height: spacing.md}} />}
        ListEmptyComponent={
          shouldShowEmptyHistory ? (
            <View style={styles.emptyHistory}>
              <Icon name="receipt-outline" size={48} color="#D1D5DB" />
              <Text style={styles.emptyText}>No transactions or messages yet</Text>
            </View>
          ) : null
        }
      />

      {/* Bottom Buttons */}
      {!shouldHideActionButtons && !isSelectionMode && (
        <View style={[styles.bottomButtons, {paddingBottom: spacing.md + insets.bottom}]}>
        <CTAButton
          kind="paid"
          label="Paid"
          compact
          style={styles.actionButton}
          onPress={() => {
            perfLog('actions:paid-press', {
              shouldHideActionButtons,
            });
            openTransactionEntryScreen('paid');
          }}
        />
        <CTAButton
          kind="get"
          label="Get"
          compact
          style={styles.actionButton}
          onPress={() => {
            perfLog('actions:get-press', {
              shouldHideActionButtons,
            });
            openTransactionEntryScreen('get');
          }}
        />
        </View>
      )}

      {/* Chat Input (only if app user) */}
      {isAppUser === true && !isSelectionMode && (
        <AvoidSoftInputView
          style={[
            styles.chatInputContainer,
            {
              paddingBottom: spacing.sm + insets.bottom,
            },
          ]}
          onLayout={event => {
            const nextHeight = Math.max(0, Math.round(event?.nativeEvent?.layout?.height || 0));
            if (nextHeight > 0) {
              setChatComposerHeight(prev => (prev === nextHeight ? prev : nextHeight));
            }
          }}
          avoidOffset={chatInputAvoidOffset}
          easing="linear"
          showAnimationDelay={0}
          hideAnimationDelay={0}
          showAnimationDuration={30}
          hideAnimationDuration={30}
          onSoftInputHeightChange={event => {
            const nextHeight = Math.max(0, event?.nativeEvent?.softInputHeight || 0);
            perfLog('avoidsoftinput:height-change', {
              previousHeight: softInputHeight,
              nextHeight,
              shouldHideActionButtons,
              inputFocused: Boolean(chatInputRef.current?.isFocused?.()),
            });
            setSoftInputHeight(prev => (prev === nextHeight ? prev : nextHeight));
            if (nextHeight > 0) {
              scrollToLatest('softinput-height-change');
            } else {
              setShouldHideActionButtons(false);
            }
          }}
          onSoftInputShown={() => {
            perfLog('avoidsoftinput:shown', {
              softInputHeight,
              listKeyboardSpacerHeight,
              shouldHideActionButtons,
              inputFocused: Boolean(chatInputRef.current?.isFocused?.()),
            });
            scrollToLatest('softinput-shown-sync', 60);
          }}
          onSoftInputHidden={() => {
            perfLog('avoidsoftinput:hidden', {
              softInputHeight,
              listKeyboardSpacerHeight,
              shouldHideActionButtons,
              inputFocused: Boolean(chatInputRef.current?.isFocused?.()),
            });
            setSoftInputHeight(0);
            setShouldHideActionButtons(false);
          }}
          enabled>
          <TextInput
            ref={chatInputRef}
            style={styles.chatInput}
            placeholder="Type a message..."
            value={messageText}
            onChangeText={setMessageText}
            multiline
            blurOnSubmit={false}
            placeholderTextColor={colors.text.secondary}
            editable={true}
            onTouchStart={() => {
              inputTapAtRef.current = Date.now();
              perfLog('chat-input:touch-start', {
                shouldHideActionButtons,
                softInputHeight,
                listKeyboardSpacerHeight,
                inputFocused: Boolean(chatInputRef.current?.isFocused?.()),
              });
              if (!shouldHideActionButtons) {
                setShouldHideActionButtons(true);
              }
            }}
            onFocus={() => {
              const sinceTouchMs = inputTapAtRef.current
                ? Date.now() - inputTapAtRef.current
                : null;
              perfLog('chat-input:focus', {
                sinceTouchMs,
                shouldHideActionButtons,
                softInputHeight,
                listKeyboardSpacerHeight,
                inputFocused: Boolean(chatInputRef.current?.isFocused?.()),
              });
            }}
            onBlur={() => {
              perfLog('chat-input:blur', {
                sinceTouchMs: inputTapAtRef.current ? Date.now() - inputTapAtRef.current : null,
                shouldHideActionButtons,
                softInputHeight,
                listKeyboardSpacerHeight,
                inputFocused: Boolean(chatInputRef.current?.isFocused?.()),
              });
              setSoftInputHeight(0);
              setShouldHideActionButtons(false);
            }}
          />
          <TouchableOpacity
            style={styles.sendButton}
            onPressIn={handleSendMessage}
            disabled={!messageText.trim() || sendingMessage}>
            <Icon
              name="send"
              size={20}
              color={messageText.trim() && !sendingMessage ? colors.primary : colors.text.light}
            />
          </TouchableOpacity>
        </AvoidSoftInputView>
      )}

      {/* Invite Banner (if not app user) */}
      {isAppUser === false && !loadingChat && (
        <View style={[styles.inviteBanner, {paddingBottom: spacing.md + insets.bottom}]}>
          <Text style={styles.inviteText}>
            Invite {getContactName()} to enable chat feature.
          </Text>
          <TouchableOpacity style={styles.inviteButton}>
            <Text style={styles.inviteButtonText}>Invite</Text>
          </TouchableOpacity>
        </View>
      )}

      <DropdownPopup
        visible={headerMenuVisible}
        onClose={closeHeaderMenu}
        cardStyle={[
          styles.menuCard,
          {
            width: menuWidth,
            top: menuTop,
            left: menuLeft,
            opacity: headerMenuAnim,
            transform: [
              {
                translateY: headerMenuAnim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [-14, 0],
                }),
              },
            ],
          },
        ]}>
            <View style={styles.menuRow}>
              <View style={styles.menuItemLeft}>
                <Icon name="sync-outline" size={22} color={colors.text.primary} />
                <Text style={styles.menuRowLabel}>sync enteries with user</Text>
              </View>
              <ToggleSwitch
                value={syncAllEntriesEnabled}
                onValueChange={toggleSyncAllEntries}
                trackColor={{false: '#D1D5DB', true: '#86EFAC'}}
                thumbColor={syncAllEntriesEnabled ? '#16A34A' : '#F9FAFB'}
              />
            </View>
            <View style={styles.menuDivider} />
            <View style={styles.menuStateRow}>
              <Text style={styles.menuStateLabel}>sync mode</Text>
              <Text style={styles.menuStateValue}>
                {syncAllEntriesEnabled ? 'ON' : 'OFF'}
              </Text>
            </View>
      </DropdownPopup>

      {/* Entry Options */}
      <Modal
        visible={optionsVisible}
        transparent
        animationType="none"
        onRequestClose={closeTransactionMenu}>
        <Animated.View
          style={[styles.optionsOverlay, {opacity: optionsOverlayOpacity}]}
        >
          <TouchableOpacity
            style={styles.optionsOverlayTouchable}
            activeOpacity={1}
            onPress={closeTransactionMenu}
          />
          <Animated.View
            style={[
              styles.optionsContainer,
              {transform: [{translateY: optionsContentTranslateY}]},
            ]}>
            <View style={styles.optionsHeader}>
              <Text style={styles.optionsTitle}>
                {selectedTransaction
                  ? `Options for ${formatCurrency(
                      Math.abs(Number(selectedTransaction.amount) || 0)
                    )}`
                  : 'Options'}
              </Text>
            </View>
            <View style={styles.optionRowWithWarning}>
              <TouchableOpacity
                style={[
                  styles.optionButton,
                  styles.optionButtonTightRight,
                  !canEditTransaction(selectedTransaction) &&
                    styles.optionButtonDisabled,
                ]}
                disabled={!canEditTransaction(selectedTransaction)}
                onPress={handleEditAmount}>
                <View style={styles.optionItemRow}>
                  <Icon
                    name="create-outline"
                    size={20}
                    color={
                      canEditTransaction(selectedTransaction)
                        ? colors.text.primary
                        : colors.text.light
                    }
                  />
                  <Text
                    style={[
                      styles.optionText,
                      !canEditTransaction(selectedTransaction) &&
                        styles.optionTextDisabled,
                    ]}>
                    Edit Amount
                  </Text>
                </View>
              </TouchableOpacity>
              {!canEditTransaction(selectedTransaction) &&
                isCreatorRestrictedEdit(selectedTransaction) ? (
                  <TouchableOpacity
                    style={styles.optionWarningButton}
                    onPress={showCreatorOnlyAmountEditWarning}
                    hitSlop={{top: 8, bottom: 8, left: 8, right: 8}}>
                    <Icon name="information-circle" size={18} color="#F59E0B" />
                  </TouchableOpacity>
                ) : null}
            </View>
            <View style={styles.optionRowWithWarning}>
              <TouchableOpacity
                style={[
                  styles.optionButton,
                  styles.optionButtonTightRight,
                  !canEditRemarkTransaction(selectedTransaction) &&
                    styles.optionButtonDisabled,
                ]}
                disabled={!canEditRemarkTransaction(selectedTransaction)}
                onPress={handleEditRemark}>
                <View style={styles.optionItemRow}>
                  <Icon
                    name="chatbubble-ellipses-outline"
                    size={20}
                    color={
                      canEditRemarkTransaction(selectedTransaction)
                        ? colors.text.primary
                        : colors.text.light
                    }
                  />
                  <Text
                    style={[
                      styles.optionText,
                      !canEditRemarkTransaction(selectedTransaction) &&
                        styles.optionTextDisabled,
                    ]}>
                    Edit Remark
                  </Text>
                </View>
              </TouchableOpacity>
              {!canEditRemarkTransaction(selectedTransaction) &&
                isCreatorRestrictedEdit(selectedTransaction) ? (
                  <TouchableOpacity
                    style={styles.optionWarningButton}
                    onPress={showCreatorOnlyRemarkEditWarning}
                    hitSlop={{top: 8, bottom: 8, left: 8, right: 8}}>
                    <Icon name="information-circle" size={18} color="#F59E0B" />
                  </TouchableOpacity>
                ) : null}
            </View>
            <TouchableOpacity
              style={[
                styles.optionButton,
                !canSyncTransaction(selectedTransaction) &&
                  styles.optionButtonDisabled,
              ]}
              disabled={!canSyncTransaction(selectedTransaction)}
              onPress={handleSyncThisEntryWithUser}>
              <View style={styles.optionItemRow}>
                <Icon
                  name="sync-outline"
                  size={20}
                  color={
                    canSyncTransaction(selectedTransaction)
                      ? '#1D4ED8'
                      : colors.text.light
                  }
                />
                <Text
                  style={[
                    styles.optionText,
                    !canSyncTransaction(selectedTransaction) &&
                      styles.optionTextDisabled,
                  ]}>
                  {syncingSelectedEntry
                    ? 'Syncing entry...'
                    : 'sync this entry with user'}
                </Text>
              </View>
            </TouchableOpacity>
            <TouchableOpacity
              style={[
                styles.optionButton,
                styles.optionDelete,
                !canDeleteTransaction(selectedTransaction) &&
                  styles.optionButtonDisabled,
              ]}
              disabled={!canDeleteTransaction(selectedTransaction)}
              onPress={handleDeleteTransaction}>
              <View style={styles.optionItemRow}>
                <Icon
                  name="trash-outline"
                  size={20}
                  color={
                    canDeleteTransaction(selectedTransaction)
                      ? '#B91C1C'
                      : colors.text.light
                  }
                />
                <Text
                  style={[
                    styles.optionText,
                    styles.optionDeleteText,
                    !canDeleteTransaction(selectedTransaction) &&
                      styles.optionTextDisabled,
                  ]}>
                  Delete Entry
                </Text>
              </View>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.optionButton, styles.optionButtonCancel]}
              onPress={closeTransactionMenu}>
              <View style={styles.optionItemRow}>
                <Icon name="close" size={20} color={colors.text.secondary} />
                <Text style={styles.optionTextCancel}>Cancel</Text>
              </View>
            </TouchableOpacity>
          </Animated.View>
        </Animated.View>
      </Modal>

      <EditAmountModal
        visible={editAmountVisible}
        value={editAmount}
        onChangeText={setEditAmount}
        onSave={handleSaveEditAmount}
        onClose={() => setEditAmountVisible(false)}
        loading={loading}
      />

      <EditRemarkModalSheet
        visible={editRemarkVisible}
        onClose={() => {
          setEditRemarkVisible(false);
          setSelectedTransaction(null);
        }}
        value={editRemark}
        onChangeText={setEditRemark}
        onSave={handleSaveEditRemark}
        loading={loading}
      />

      {/* Transaction Modal */}
      <Modal
        visible={transactionModalVisible}
        transparent
        animationType="none"
        onRequestClose={closeTransactionModal}>
        <View style={styles.modalOverlay}>
          <TouchableOpacity
            style={styles.modalBackdrop}
            activeOpacity={1}
            onPress={closeTransactionModal}
          />
          <Animated.View
            style={[
              styles.modalContainer,
              {transform: [{translateY: modalSlideAnim}]},
            ]}>
            <View style={styles.modalContent}>
              <View style={styles.modalHandle} />
              <Text style={styles.modalTitle}>
                {transactionType === 'paid' ? 'Paid' : 'Get'}
              </Text>
              <TextInput
                ref={amountInputRef}
                style={styles.modalAmountInput}
                value={amount}
                onChangeText={setAmount}
                keyboardType="numeric"
                editable={!loading}
                onSubmitEditing={() => noteInputRef.current?.focus()}
              />
              <Text style={styles.modalNoteLabel}>Note (Optional)</Text>
              <TextInput
                ref={noteInputRef}
                style={styles.modalNoteInput}
                value={note}
                onChangeText={setNote}
                placeholder="Add a note"
                placeholderTextColor={colors.text.light}
                multiline
                numberOfLines={3}
                editable={!loading}
              />
              <TouchableOpacity
                style={[
                  styles.modalAddButton,
                  transactionType === 'paid'
                    ? styles.modalAddButtonPaid
                    : styles.modalAddButtonGet,
                  loading && styles.buttonDisabled,
                ]}
                onPress={handleAddTransaction}
                disabled={loading}>
                {loading ? (
                  <ActivityIndicator color={colors.white} />
                ) : (
                  <Text style={styles.modalAddButtonText}>
                    {transactionType === 'paid'
                      ? 'Record Payment'
                      : 'Record Receipt'}
                  </Text>
                )}
              </TouchableOpacity>
            </View>
          </Animated.View>
        </View>
      </Modal>

      <Modal
        visible={getPromptVisible}
        transparent
        animationType="fade"
        onRequestClose={() => setGetPromptVisible(false)}>
        <View style={styles.promptOverlay}>
          <TouchableOpacity
            style={styles.promptBackdrop}
            activeOpacity={1}
            onPress={handleGetPromptCancel}
          />
          <View style={styles.promptCard}>
            <TouchableOpacity
              style={styles.promptCloseButton}
              onPress={handleGetPromptCancel}
              disabled={loading}
              hitSlop={{top: 24, bottom: 24, left: 24, right: 24}}>
              <Icon name="close" size={20} color={colors.text.primary} />
            </TouchableOpacity>
            <Text style={styles.promptTitle}>How should we record this?</Text>
            <Text style={styles.promptMessage}>
              Record{' '}
              <Text style={styles.promptAmount}>
                {formatCurrency(Number(amount) || 0)}
              </Text>{' '}
              or transfer to your primary{' '}
              <Text
                style={[
                  styles.promptAccountName,
                  primaryEarningAccount?.icon_color && {
                    color: primaryEarningAccount.icon_color,
                  },
                ]}>
                {primaryEarningAccount?.account_name || 'earning'}
              </Text>{' '}
              account?
            </Text>
            <TouchableOpacity
              style={styles.promptRemember}
              onPress={() =>
                setRememberGetChoice(current => !current)
              }
              disabled={loading}>
              <View
                style={[
                  styles.promptCheckbox,
                  rememberGetChoice && styles.promptCheckboxChecked,
                  rememberGetChoice &&
                    primaryEarningAccount?.icon_color && {
                      backgroundColor: primaryEarningAccount.icon_color,
                      borderColor: primaryEarningAccount.icon_color,
                    },
                ]}>
                {rememberGetChoice && (
                  <Icon name="checkmark" size={14} color={colors.white} />
                )}
              </View>
              <Text style={styles.promptRememberText}>
                Remember my choice for this contact
              </Text>
            </TouchableOpacity>
            <View style={styles.promptActions}>
              <TouchableOpacity
                style={[styles.promptButton, styles.promptButtonSecondary]}
                onPress={handleGetPromptWithdraw}
                disabled={loading}>
                <Text style={styles.promptButtonTextSecondary}>Withdraw</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[
                  styles.promptButton,
                  styles.promptButtonPrimary,
                  primaryEarningAccount?.icon_color && {
                    backgroundColor: primaryEarningAccount.icon_color,
                  },
                ]}
                onPress={handleGetPromptTransfer}
                disabled={loading}>
                <Text style={styles.promptButtonTextPrimary}>Transfer</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>

      <Modal
        visible={paidPromptVisible}
        transparent
        animationType="fade"
        onRequestClose={() => setPaidPromptVisible(false)}>
        <View style={styles.promptOverlay}>
          <TouchableOpacity
            style={styles.promptBackdrop}
            activeOpacity={1}
            onPress={handlePaidPromptCancel}
          />
          <View style={styles.promptCard}>
            <TouchableOpacity
              style={styles.promptCloseButton}
              onPress={handlePaidPromptCancel}
              disabled={loading}
              hitSlop={{top: 24, bottom: 24, left: 24, right: 24}}>
              <Icon name="close" size={20} color={colors.text.primary} />
            </TouchableOpacity>
            <Text style={styles.promptTitle}>Get from primary account?</Text>
            <Text style={styles.promptMessage}>
              Do you want to get{' '}
              <Text style={styles.promptAmount}>
                {formatCurrency(Number(amount) || 0)}
              </Text>{' '}
              from{' '}
              primary earning account{' '}
              <Text
                style={[
                  styles.promptAccountName,
                  primaryEarningAccount?.icon_color && {
                    color: primaryEarningAccount.icon_color,
                  },
                ]}>
                {primaryEarningAccount?.account_name || 'primary earning account'}
              </Text>{' '}
              for payment to{' '}
              <Text style={styles.promptAccountName}>{getContactName()}</Text>?
            </Text>
            <TouchableOpacity
              style={styles.promptRemember}
              onPress={() =>
                setRememberPaidChoice(current => !current)
              }
              disabled={loading}>
              <View
                style={[
                  styles.promptCheckbox,
                  rememberPaidChoice && styles.promptCheckboxChecked,
                  rememberPaidChoice &&
                    primaryEarningAccount?.icon_color && {
                      backgroundColor: primaryEarningAccount.icon_color,
                      borderColor: primaryEarningAccount.icon_color,
                    },
                ]}>
                {rememberPaidChoice && (
                  <Icon name="checkmark" size={14} color={colors.white} />
                )}
              </View>
              <Text style={styles.promptRememberText}>
                Remember my choice for this contact
              </Text>
            </TouchableOpacity>
            <View style={styles.promptActions}>
              <TouchableOpacity
                style={[styles.promptButton, styles.promptButtonSecondary]}
                onPress={handlePaidPromptNo}
                disabled={loading}>
                <Text style={styles.promptButtonTextSecondary}>Just record</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[
                  styles.promptButton,
                  styles.promptButtonPrimary,
                  primaryEarningAccount?.icon_color && {
                    backgroundColor: primaryEarningAccount.icon_color,
                  },
                ]}
                onPress={handlePaidPromptYes}
                disabled={loading}>
                <Text style={styles.promptButtonTextPrimary}>Get</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
      </View>
    </View>
  );
};

