import React from 'react';
import {useFocusEffect} from '@react-navigation/native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {
  View,
  Text,
  Image,
  Modal,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Alert,
  ActivityIndicator,
  Animated,
  Dimensions,
  Easing,
  PanResponder,
  BackHandler,
  TextInput,
  NativeModules,
  Linking,
} from 'react-native';
import Icon from 'react-native-vector-icons/Ionicons';
import ImagePicker from 'react-native-image-crop-picker';
import AsyncStorage from '@react-native-async-storage/async-storage';
import {auth} from '../config/firebase';
import {GoogleSignin} from '@react-native-google-signin/google-signin';
import {
  colors,
  spacing,
  fontSize,
  fontWeight,
  headerTexture,
} from '../utils/theme';
import {clearLocalData} from '../services/database';
import {clearAllAccountsData} from '../services/accountsDatabase';
import {clearAllLedgerData} from '../services/ledgerDatabase';
import {queueBackupFromStorage} from '../utils/backupQueue';
import BottomSheet from '../components/BottomSheet';
import CollapsibleSection from '../components/CollapsibleSection';
import CollapsibleMenuItem from '../components/CollapsibleMenuItem';
import {updateProfile, fetchUsersByPhones} from '../services/api';
import {useToast} from '../hooks/useToast';
import {COUNTRIES} from '../utils/countries';
import TexturedSurface from '../components/TexturedSurface';
import TapEffect from '../components/ui/TapEffect';
import {
  getVaguePhoneError,
  normalizePhoneForCompare,
} from '../utils/phoneValidation';

const OCCUPATION_OPTIONS = [
  {label: 'Accountant', value: 'Accountant'},
  {label: 'Doctor', value: 'Doctor'},
  {label: 'Driver', value: 'Driver'},
  {label: 'Engineer', value: 'Engineer'},
  {label: 'Farmer', value: 'Farmer'},
  {label: 'Housewife', value: 'Housewife'},
  {label: 'Lawyer', value: 'Lawyer'},
  {label: 'Manager', value: 'Manager'},
  {label: 'Nurse', value: 'Nurse'},
  {label: 'Owner', value: 'Owner'},
  {label: 'Plumber', value: 'Plumber'},
  {label: 'Student', value: 'Student'},
  {label: 'Teacher', value: 'Teacher'},
  {label: 'Technician', value: 'Technician'},
  {label: 'Trader', value: 'Trader'},
  {label: 'Other (Manual)', value: 'manual'},
];
const normalizeImageUri = uri => {
  if (!uri) {
    return '';
  }
  if (
    uri.startsWith('http://') ||
    uri.startsWith('https://') ||
    uri.startsWith('file://') ||
    uri.startsWith('content://')
  ) {
    return uri;
  }
  return `file://${uri}`;
};

const stripToDigits = value => String(value || '').replace(/\D/g, '');

const getCountryDialCode = countryCode => {
  const countryObj = COUNTRIES.find(country => country.code === countryCode);
  return countryObj?.dialCode || '+91';
};

const getCountryFlag = code => {
  if (!code || code.length !== 2) return '🌐';
  return String.fromCodePoint(
    ...[...code.toUpperCase()].map(c => 127397 + c.charCodeAt(0)),
  );
};

const resolveCountryFromPhone = phone => {
  const digits = stripToDigits(phone);
  if (!digits) {
    return null;
  }
  const sorted = [...COUNTRIES].sort(
    (a, b) =>
      stripToDigits(b.dialCode).length - stripToDigits(a.dialCode).length,
  );
  const match = sorted.find(country =>
    digits.startsWith(stripToDigits(country.dialCode)),
  );
  return match?.code || null;
};

const getLocalPhoneNumber = (phone, dialCode) => {
  const digits = stripToDigits(phone);
  const codeDigits = stripToDigits(dialCode);
  if (codeDigits && digits.startsWith(codeDigits) && digits.length > codeDigits.length) {
    return digits.slice(codeDigits.length);
  }
  return digits;
};

const isPhoneAlreadyInUse = async (fullPhoneNumber, selfFirebaseUid) => {
  try {
    const response = await fetchUsersByPhones([fullPhoneNumber]);
    if (!response?.success) {
      return false;
    }
    const target = normalizePhoneForCompare(fullPhoneNumber);
    const users = Array.isArray(response.users) ? response.users : [];

    return users.some(userItem => {
      if (!userItem?.firebaseUid || userItem.firebaseUid === selfFirebaseUid) {
        return false;
      }
      const mobileMatch = normalizePhoneForCompare(userItem.mobile) === target;
      const normalizedMatch =
        normalizePhoneForCompare(userItem.normalizedMobile) === target;
      return mobileMatch || normalizedMatch;
    });
  } catch (error) {
    console.warn('Phone duplicate check failed:', error);
    return false;
  }
};

const MoreScreen = ({navigation, route, user, onProfileUpdate}) => {
  const insets = useSafeAreaInsets();
  const profileOnly = route.params?.profileOnly === true;
  const routeUser = route.params?.user;
  const openProfileOnFocus = route.params?.openProfileOnFocus;
  const returnToDashboardOnSave = route.params?.returnToDashboardOnSave;
  const {showToast} = useToast();
  const [currentUser, setCurrentUser] = React.useState(
    user || routeUser || {},
  );
  const [profileVisible, setProfileVisible] = React.useState(false);
  const [draftName, setDraftName] = React.useState('');
  const [draftPhoto, setDraftPhoto] = React.useState('');
  const [draftPhoneNumber, setDraftPhoneNumber] = React.useState('');
  const [selectedCountry, setSelectedCountry] = React.useState('IN');
  const [countryCode, setCountryCode] = React.useState('+91');
  const [showCountryPicker, setShowCountryPicker] = React.useState(false);
  const [phoneError, setPhoneError] = React.useState('');
  const [checkingPhone, setCheckingPhone] = React.useState(false);
  const [phoneAvailable, setPhoneAvailable] = React.useState(null);
  const [phoneStatusMessage, setPhoneStatusMessage] = React.useState('');
  const [hasPhoneEdited, setHasPhoneEdited] = React.useState(false);
  const [draftGender, setDraftGender] = React.useState('');
  const [draftUsername, setDraftUsername] = React.useState('');
  const [draftBio, setDraftBio] = React.useState('');
  const [occupationChoice, setOccupationChoice] = React.useState('');
  const [manualOccupation, setManualOccupation] = React.useState('');
  const [occupationModalVisible, setOccupationModalVisible] =
    React.useState(false);
  const [genderModalVisible, setGenderModalVisible] = React.useState(false);
  const [saving, setSaving] = React.useState(false);
  const [photoPreviewVisible, setPhotoPreviewVisible] = React.useState(false);
  const screenWidth = Dimensions.get('window').width;
  const profileSlideX = React.useRef(new Animated.Value(screenWidth)).current;
  const profileVisibleRef = React.useRef(false);
  const profileBackRef = React.useRef(() => {});
  const profileOnlyClosingRef = React.useRef(false);

  React.useEffect(() => {
    const dialCode = getCountryDialCode(selectedCountry);
    setCountryCode(dialCode);
  }, [selectedCountry]);
  const openedProfileFromPromptRef = React.useRef(false);
  const profilePanResponder = React.useRef(
    PanResponder.create({
      onMoveShouldSetPanResponder: (_evt, gestureState) => {
        const {dx, dy} = gestureState;
        return Math.abs(dx) > Math.abs(dy) && dx > 10;
      },
      onPanResponderRelease: (_evt, gestureState) => {
        const shouldClose =
          gestureState.dx > screenWidth * 0.25 || gestureState.vx > 0.6;
        if (shouldClose) {
          profileBackRef.current();
        }
      },
    }),
  ).current;

  React.useEffect(() => {
    if (user || routeUser) {
      setCurrentUser(user || routeUser);
    }
  }, [user, routeUser]);

  React.useEffect(() => {
    profileVisibleRef.current = profileVisible;
  }, [profileVisible]);

  React.useEffect(() => {
    if (!hasPhoneEdited) {
      setCheckingPhone(false);
      setPhoneAvailable(null);
      setPhoneStatusMessage('');
      return;
    }

    const cleanedPhone = draftPhoneNumber.replace(/\D/g, '');

    if (cleanedPhone.length !== 10 || !countryCode) {
      setCheckingPhone(false);
      setPhoneAvailable(null);
      setPhoneStatusMessage('');
      return;
    }

    const vaguePhoneError = getVaguePhoneError(cleanedPhone);
    if (vaguePhoneError) {
      setCheckingPhone(false);
      setPhoneAvailable(false);
      setPhoneStatusMessage(vaguePhoneError);
      return;
    }

    let cancelled = false;
    const timeoutId = setTimeout(async () => {
      setCheckingPhone(true);
      setPhoneAvailable(null);
      setPhoneStatusMessage('');
      try {
        const selfFirebaseUid =
          currentUser?.firebaseUid || (await AsyncStorage.getItem('firebaseUid'));
        if (!selfFirebaseUid) {
          if (!cancelled) {
            setCheckingPhone(false);
          }
          return;
        }

        const fullPhoneNumber = `${countryCode}${cleanedPhone}`;
        const alreadyInUse = await isPhoneAlreadyInUse(
          fullPhoneNumber,
          selfFirebaseUid,
        );
        if (cancelled) {
          return;
        }
        setPhoneAvailable(!alreadyInUse);
        setPhoneStatusMessage(
          alreadyInUse
            ? 'This phone number is already in use. Please use another number.'
            : 'Phone number available',
        );
      } catch (error) {
        if (!cancelled) {
          setPhoneAvailable(null);
          setPhoneStatusMessage('');
        }
      } finally {
        if (!cancelled) {
          setCheckingPhone(false);
        }
      }
    }, 450);

    return () => {
      cancelled = true;
      clearTimeout(timeoutId);
    };
  }, [draftPhoneNumber, countryCode, currentUser?.firebaseUid, hasPhoneEdited]);

  const getLatestLocalUser = React.useCallback(async () => {
    try {
      const stored = await AsyncStorage.getItem('user');
      if (stored) {
        const parsedUser = JSON.parse(stored);
        if (parsedUser && typeof parsedUser === 'object') {
          setCurrentUser(parsedUser);
          return parsedUser;
        }
      }
    } catch (error) {
      console.error('Failed to read latest local user:', error);
    }
    return currentUser || routeUser || {};
  }, [currentUser, routeUser]);

  const navigateToProfileSettings = React.useCallback(
    async profileUser => {
      const resolvedUser = profileUser || (await getLatestLocalUser());
      if (profileOnly) {
        openProfile(resolvedUser || currentUser || {});
        return;
      }
      navigation.navigate('ProfileSettingsNative', {
        user: resolvedUser || currentUser || {},
        profileOnly: true,
      });
    },
    [navigation, currentUser, profileOnly, getLatestLocalUser]
  );

  React.useEffect(() => {
    const loadUser = async () => {
      try {
        const stored = await AsyncStorage.getItem('user');
        if (stored) {
          const parsedUser = JSON.parse(stored);
          setCurrentUser(parsedUser);
          return parsedUser;
        }
        const fallbackUser = user || routeUser || {};
        setCurrentUser(fallbackUser);
        return fallbackUser;
      } catch (error) {
        console.error('Failed to load user:', error);
        return user || routeUser || {};
      }
    };
    const handleFocus = () => {
      loadUser().then(loadedUser => {
        if (openProfileOnFocus && !openedProfileFromPromptRef.current) {
          openedProfileFromPromptRef.current = true;
          navigateToProfileSettings(loadedUser);
          navigation.setParams({openProfileOnFocus: false});
        }
      });
    };
    const unsubscribe = navigation.addListener('focus', handleFocus);
    handleFocus();
    return unsubscribe;
  }, [navigation, user, routeUser, openProfileOnFocus, navigateToProfileSettings]);

  const handleLogout = () => {
    Alert.alert('Logout', 'Are you sure you want to logout?', [
      {text: 'Cancel', style: 'cancel'},
      {
        text: 'Logout',
        style: 'destructive',
        onPress: async () => {
          let hadLogoutWarnings = false;
          try {
            try {
              await GoogleSignin.signOut();
            } catch (googleError) {
              hadLogoutWarnings = true;
              console.warn('Google sign-out warning:', googleError);
            }

            try {
              await auth().signOut();
            } catch (firebaseError) {
              hadLogoutWarnings = true;
              console.warn('Firebase sign-out warning:', firebaseError);
            }

            const cleanupResults = await Promise.allSettled([
              AsyncStorage.clear(),
              Promise.resolve(clearLocalData()),
              clearAllAccountsData(),
              clearAllLedgerData(),
            ]);

            const cleanupFailed = cleanupResults.some(
              result => result.status === 'rejected'
            );
            if (cleanupFailed) {
              hadLogoutWarnings = true;
              cleanupResults.forEach(result => {
                if (result.status === 'rejected') {
                  console.warn('Logout cleanup warning:', result.reason);
                }
              });
            }

            navigation.replace('Login');
            if (hadLogoutWarnings) {
              showToast('Logout successful.', 'info');
            }
          } catch (error) {
            console.error('Logout error:', error);
            navigation.replace('Login');
          }
        },
      },
    ]);
  };

  const openProfile = userOverride => {
    const profileUser = userOverride || currentUser || {};
    const currentOccupation = profileUser?.occupation || '';
    const matchedOption = OCCUPATION_OPTIONS.find(
      option => option.value !== 'manual' && option.value === currentOccupation,
    );
    if (matchedOption) {
      setOccupationChoice(matchedOption.value);
      setManualOccupation('');
    } else if (currentOccupation) {
      setOccupationChoice('manual');
      setManualOccupation(currentOccupation);
    } else {
      setOccupationChoice('');
      setManualOccupation('');
    }
    const inferredCountry =
      profileUser?.country ||
      resolveCountryFromPhone(profileUser?.phoneNumber || profileUser?.mobile) ||
      'IN';
    const dialCode = getCountryDialCode(inferredCountry);
    setDraftName(profileUser?.displayName || profileUser?.name || '');
    setDraftPhoto(normalizeImageUri(profileUser?.photoURL || ''));
    setPhoneError('');
    setCheckingPhone(false);
    setPhoneAvailable(null);
    setPhoneStatusMessage('');
    setHasPhoneEdited(false);
    setSelectedCountry(inferredCountry);
    setCountryCode(dialCode);
    setDraftPhoneNumber(
      getLocalPhoneNumber(
        profileUser?.phoneNumber || profileUser?.mobile || '',
        dialCode,
      ),
    );
    setDraftGender(profileUser?.gender || '');
    setDraftUsername(profileUser?.username || '');
    setDraftBio(profileUser?.bio || '');
    setProfileVisible(true);
    if (profileOnly) {
      profileSlideX.setValue(0);
      return;
    }
    profileSlideX.setValue(screenWidth);
    Animated.timing(profileSlideX, {
      toValue: 0,
      duration: 240,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start();
  };

  const closeProfile = React.useCallback(() => {
    if (profileOnly) {
      profileOnlyClosingRef.current = true;
      setPhotoPreviewVisible(false);
      setOccupationModalVisible(false);
      setGenderModalVisible(false);
      navigation.goBack();
      return;
    }
    setPhotoPreviewVisible(false);
    setOccupationModalVisible(false);
    setGenderModalVisible(false);
    Animated.timing(profileSlideX, {
      toValue: screenWidth,
      duration: 200,
      easing: Easing.in(Easing.cubic),
      useNativeDriver: true,
    }).start(() => {
      setProfileVisible(false);
    });
  }, [profileOnly, profileSlideX, screenWidth, navigation]);

  React.useEffect(() => {
    if (!profileOnly || profileVisible || profileOnlyClosingRef.current) {
      return;
    }
    openProfile(currentUser || routeUser || {});
  }, [profileOnly, profileVisible, currentUser, routeUser]);

  const openPhotoPreview = () => {
    if (!draftPhoto) {
      return;
    }
    setPhotoPreviewVisible(true);
  };

  const handlePickImage = async () => {
    try {
      const result = await ImagePicker.openPicker({
        mediaType: 'photo',
        cropping: true,
        freeStyleCropEnabled: true,
        cropperToolbarTitle: 'Crop Photo',
        cropperActiveWidgetColor: colors.primary,
        cropperStatusBarColor: colors.primary,
        cropperToolbarColor: colors.primary,
        cropperToolbarWidgetColor: colors.white,
        compressImageQuality: 0.9,
      });
      if (result?.path) {
        setDraftPhoto(normalizeImageUri(result.path));
        return;
      }
    } catch (error) {
      if (error?.code === 'E_PICKER_CANCELLED') {
        return;
      }
      console.error('Failed to pick image:', error);
      Alert.alert('Error', 'Failed to open photo library.');
    }
  };

  const handleSaveProfile = async () => {
    if (!draftName.trim()) {
      Alert.alert('Error', 'Please enter a name');
      return;
    }

    if (!selectedCountry) {
      Alert.alert('Error', 'Please select a country');
      return;
    }

    if (!draftPhoneNumber.trim()) {
      Alert.alert('Error', 'Please enter a phone number');
      return;
    }

    const cleanedPhone = draftPhoneNumber.replace(/[\s\-\(\)]/g, '');
    if (!/^\d+$/.test(cleanedPhone)) {
      setPhoneError('Phone number can only contain digits, spaces, and dashes');
      Alert.alert('Error', 'Phone number can only contain digits, spaces, and dashes');
      return;
    }

    if (cleanedPhone.length < 7) {
      const errorMessage = `Phone number must be at least 7 digits for ${selectedCountry}`;
      setPhoneError(errorMessage);
      Alert.alert('Error', errorMessage);
      return;
    }

    if (phoneAvailable === false) {
      const message =
        phoneStatusMessage ||
        'This phone number is already in use. Please use another number.';
      setPhoneError(message);
      Alert.alert('Error', message);
      return;
    }

    const vaguePhoneError = getVaguePhoneError(cleanedPhone);
    if (vaguePhoneError) {
      setPhoneError(vaguePhoneError);
      Alert.alert('Error', vaguePhoneError);
      return;
    }

    const selfFirebaseUid =
      currentUser?.firebaseUid || (await AsyncStorage.getItem('firebaseUid'));
    if (!selfFirebaseUid) {
      Alert.alert('Error', 'User authentication error. Please login again.');
      return;
    }

    const fullPhoneNumberForCheck = `${countryCode}${cleanedPhone}`;
    const alreadyInUse = await isPhoneAlreadyInUse(
      fullPhoneNumberForCheck,
      selfFirebaseUid,
    );
    if (alreadyInUse) {
      const duplicateMessage =
        'This phone number is already in use. Please use another number.';
      setPhoneError(duplicateMessage);
      Alert.alert('Error', duplicateMessage);
      return;
    }

    setPhoneError('');
    setSaving(true);
    try {
      const occupationValue =
        occupationChoice === 'manual'
          ? manualOccupation.trim()
          : occupationChoice;
      const normalizedPhoto = normalizeImageUri(draftPhoto || '');

      // Get firebaseUid
      const firebaseUid = selfFirebaseUid;

      if (!firebaseUid) {
        Alert.alert('Error', 'User authentication error. Please login again.');
        return;
      }

      // Call backend API to update profile
      const fullPhoneNumber = `${countryCode}${cleanedPhone}`;

      const response = await updateProfile(firebaseUid, {
        displayName: draftName.trim(),
        mobile: fullPhoneNumber || null,
        country: selectedCountry,
        gender: draftGender || null,
        occupation: occupationValue || null,
        bio: draftBio.trim() || null,
        setupComplete: true, // Mark setup as complete
      });

      if (response.success) {
        // Update Firebase auth profile (photo is managed separately)
        if (auth().currentUser) {
          await auth().currentUser.updateProfile({
            displayName: draftName.trim(),
            photoURL: normalizedPhoto,
          });
        }

        // Merge backend response with local values
        const updatedUser = {
          ...response.user,
          displayName: draftName.trim(),
          photoURL: normalizedPhoto,
          phoneNumber: fullPhoneNumber,
          mobile: fullPhoneNumber,
          country: selectedCountry,
          bio: draftBio.trim() || null,
          setupComplete: true,
        };

        setCurrentUser(updatedUser);
        await AsyncStorage.setItem('user', JSON.stringify(updatedUser));
        if (onProfileUpdate) {
          await onProfileUpdate(updatedUser);
        }
        queueBackupFromStorage();

        showToast('Profile updated successfully!', 'success');
        closeProfile();
        if (returnToDashboardOnSave) {
          navigation.setParams({
            returnToDashboardOnSave: false,
            openProfileOnFocus: false,
          });
          navigation.navigate('Dashboard');
        }
      } else {
        Alert.alert('Error', response.message || 'Failed to update profile');
      }
    } catch (error) {
      console.error('Failed to update profile:', error);
      Alert.alert('Error', error.message || 'Failed to update profile');
    } finally {
      setSaving(false);
    }
  };

  const getDraftOccupationValue = () => {
    return occupationChoice === 'manual'
      ? manualOccupation.trim()
      : occupationChoice;
  };

  const hasProfileChanges = () => {
    const currentCountry = currentUser?.country || 'IN';
    const currentDialCode = getCountryDialCode(currentCountry);
    const currentLocalPhone = getLocalPhoneNumber(
      currentUser?.phoneNumber || currentUser?.mobile || '',
      currentDialCode,
    );
    const nameChanged =
      draftName.trim() !== String(currentUser?.displayName || '').trim();
    const photoChanged =
      normalizeImageUri(draftPhoto || '') !==
      normalizeImageUri(currentUser?.photoURL || '');
    const phoneChanged =
      stripToDigits(draftPhoneNumber) !== stripToDigits(currentLocalPhone);
    const countryChanged = selectedCountry !== currentCountry;
    const genderChanged =
      draftGender !== String(currentUser?.gender || '');
    const occupationChanged =
      getDraftOccupationValue() !== String(currentUser?.occupation || '');
    const bioChanged =
      draftBio.trim() !== String(currentUser?.bio || '').trim();
    return (
      nameChanged ||
      photoChanged ||
      phoneChanged ||
      countryChanged ||
      genderChanged ||
      occupationChanged ||
      bioChanged
    );
  };

  const handleProfileBack = React.useCallback(() => {
    if (!profileVisible) {
      return;
    }
    if (!hasProfileChanges()) {
      closeProfile();
      return;
    }
    Alert.alert('Discard changes?', 'Do you want to save your changes?', [
      {text: 'Cancel', style: 'cancel'},
      {
        text: 'Discard',
        style: 'destructive',
        onPress: () => {
          closeProfile();
        },
      },
      {
        text: 'Save',
        onPress: () => {
          handleSaveProfile();
        },
      },
    ]);
  }, [profileVisible, hasProfileChanges, closeProfile, handleSaveProfile]);

  React.useEffect(() => {
    profileBackRef.current = handleProfileBack;
  }, [handleProfileBack]);
  const canSaveProfile = !saving && hasProfileChanges();

  const menuItems = [
    {
      id: 'settings',
      title: 'Settings',
      icon: 'settings-outline',
      type: 'direct',
      onPress: () => {
        navigation.navigate('Settings');
      },
    },
    {
      id: 'backup',
      title: 'Backup & Restore',
      icon: 'cloud-upload-outline',
      type: 'direct',
      onPress: () => {
        navigation.navigate('Backup');
      },
    },
    // {
    //   id: 'notification-settings',
    //   title: 'Notification Settings',
    //   icon: 'notifications-outline',
    //   type: 'direct',
    //   onPress: () => {
    //     skipNextSlideInRef.current = true;
    //     navigation.navigate('NotificationSettings');
    //   },
    // },
    {
      id: 'help',
      title: 'Help & Support',
      icon: 'help-circle-outline',
      type: 'collapsible',
      subItems: [
        {
          id: 'faqs',
          title: 'FAQs',
          onPress: () => {
            navigation.navigate('FAQs');
          },
        },
        {
          id: 'help-whatsapp',
          title: 'Help on WhatsApp',
          onPress: () => {
            const phoneNumber = '9356393094';
            const message = 'Hello, I would like to learn about Savingo.';
            const whatsappURL = `whatsapp://send?phone=91${phoneNumber}&text=${encodeURIComponent(message)}`;
            Linking.openURL(whatsappURL).catch(err =>
              Alert.alert('Error', 'WhatsApp is not installed on your device.'),
            );
          },
        },
        // {
        //   id: 'call-us',
        //   title: 'Call Us',
        //   onPress: () => {
        //     Linking.openURL('tel:9356393094').catch(err =>
        //       Alert.alert('Error', 'Unable to make call.'),
        //     );
        //   },
        // },
      ],
    },
    {
      id: 'about',
      title: 'About Us',
      icon: 'information-circle-outline',
      type: 'collapsible',
      subItems: [
        {
          id: 'about-app',
          title: 'About App',
          onPress: () => {
            const versionName = NativeModules?.VersionInfo?.versionName ?? 'unknown';
            const versionCode = NativeModules?.VersionInfo?.versionCode ?? 'unknown';
            Alert.alert('Savingo', `Version ${versionName} (${versionCode})`);
          },
        },
        {
          id: 'privacy-policy',
          title: 'Privacy Policy',
          onPress: () => {
            Linking.openURL('https://savingo.merasoftware.com/privacy-policy').catch(err =>
              Alert.alert('Error', 'Unable to open link. Please try again.'),
            );
          },
        },
        {
          id: 'terms-conditions',
          title: 'Terms & Conditions',
          onPress: () => {
             Linking.openURL('https://savingo.merasoftware.com/terms-of-service').catch(err =>
              Alert.alert('Error', 'Unable to open link. Please try again.'),
            );
          },
        },
      ],
    },
  ];

  const handleBack = React.useCallback(() => {
    if (navigation.canGoBack()) {
      navigation.goBack();
      return;
    }
    navigation.navigate('Dashboard');
  }, [navigation]);

  useFocusEffect(
    React.useCallback(() => {
      const onBackPress = () => {
        if (profileVisible) {
          handleProfileBack();
          return true;
        }
        handleBack();
        return true;
      };
      const subscription = BackHandler.addEventListener(
        'hardwareBackPress',
        onBackPress,
      );
      return () => subscription.remove();
    }, [handleBack, profileVisible, handleProfileBack]),
  );

  // Handle gesture-based back navigation (swipe from edge)
  React.useEffect(() => {
    if (profileOnly) {
      return undefined;
    }
    const unsubscribeNavigation = navigation.addListener('beforeRemove', (e) => {
      if (profileVisibleRef.current) {
        e.preventDefault();
        profileBackRef.current();
      }
    });
    return unsubscribeNavigation;
  }, [navigation, profileOnly]);

  const profilePhotoUri = normalizeImageUri(currentUser?.photoURL || '');
  const draftPhotoUri = normalizeImageUri(draftPhoto || '');
  const selectedCountryObj = COUNTRIES.find(
    country => country.code === selectedCountry,
  );

  return (
    <View style={styles.container}>
      <Animated.View style={styles.animatedContainer}>
        <TexturedSurface
          style={[
            styles.moreHeader,
            {
              marginTop: -insets.top,
              paddingTop: 42 + insets.top,
            },
          ]}>
          <TouchableOpacity
            style={styles.backButton}
            onPress={handleBack}
            accessibilityLabel="Go back">
            <Icon name="chevron-back" size={22} color={headerTexture.icon} />
          </TouchableOpacity>
          <Text style={styles.moreHeaderTitle}>More</Text>
          <View style={styles.moreHeaderSpacer} />
        </TexturedSurface>
        <ScrollView style={styles.scrollView}>
          <TapEffect
            style={styles.profileSection}
            onPress={() => {
              void navigateToProfileSettings();
            }}
            accessibilityRole="button"
            accessibilityLabel="Open profile settings">
            {profilePhotoUri ? (
              <Image
                source={{uri: profilePhotoUri}}
                style={styles.profileImage}
              />
            ) : (
              <View style={styles.profilePlaceholder}>
                <Icon name="person" size={28} color={colors.white} />
              </View>
            )}
            <View style={styles.profileInfo}>
              <Text style={styles.profileName}>
                {currentUser?.displayName || 'User'}
              </Text>
              <Text style={styles.profileEmail}>{currentUser?.email || ''}</Text>
            </View>
            <Icon
              name="pencil"
              size={20}
              color={colors.text.light}
              style={styles.profileArrow}
            />
          </TapEffect>

          <View style={styles.menuSection}>
            {menuItems.map(item => {
              if (item.type === 'collapsible') {
                return (
                  <CollapsibleSection
                    key={item.id}
                    title={item.title}
                    icon={item.icon}
                    initialExpanded={false}>
                    <View>
                      {item.subItems?.map((subItem, index) => (
                        <CollapsibleMenuItem
                          key={subItem.id}
                          title={subItem.title}
                          onPress={subItem.onPress}
                        />
                      ))}
                    </View>
                  </CollapsibleSection>
                );
              }

              // Direct menu item
              return (
                <TapEffect
                  key={item.id}
                  style={styles.directMenuItem}
                  onPress={item.onPress}>
                  <View style={styles.menuIconContainer}>
                    <Icon name={item.icon} size={24} color={colors.primary} />
                  </View>
                  <Text style={styles.menuText}>{item.title}</Text>
                  <Icon
                    name="chevron-forward"
                    size={20}
                    color={colors.text.light}
                  />
                </TapEffect>
              );
            })}
          </View>

          <TouchableOpacity style={styles.logoutButton} onPress={handleLogout}>
            <Icon name="log-out-outline" size={24} color={colors.error} />
            <Text style={styles.logoutText}>Logout</Text>
          </TouchableOpacity>
        </ScrollView>
      </Animated.View>
      {profileVisible && (
        <Animated.View
          style={[
            styles.profileScreen,
            {transform: [{translateX: profileSlideX}]},
          ]}
          {...profilePanResponder.panHandlers}>
          <TexturedSurface
            style={[
              styles.profileHeader,
              {
                paddingTop: spacing.sm + insets.top,
              },
            ]}>
            <TouchableOpacity
              style={styles.backButton}
              onPress={handleProfileBack}
              accessibilityLabel="Close profile settings">
              <Icon name="chevron-back" size={22} color={headerTexture.icon} />
            </TouchableOpacity>
            <Text style={styles.profileHeaderTitle}>Profile Settings</Text>
            <View style={styles.moreHeaderSpacer} />
          </TexturedSurface>
          <ScrollView
            style={styles.profileScroll}
            contentContainerStyle={styles.profileContent}>
            <View style={styles.profileIdentityCard}>
              <View style={styles.profileIdentityImageWrap}>
                <View style={styles.profileIdentityImageContainer}>
                  <TouchableOpacity
                    style={styles.profileIdentityImageButton}
                    onPress={openPhotoPreview}
                    activeOpacity={0.8}>
                    {draftPhotoUri ? (
                      <Image
                        source={{uri: draftPhotoUri}}
                        style={styles.profileIdentityImage}
                      />
                    ) : (
                      <View style={styles.profileIdentityPlaceholder}>
                        <Icon name="person" size={38} color={colors.white} />
                      </View>
                    )}
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={styles.profileIdentityCameraBadge}
                    onPress={handlePickImage}
                    accessibilityLabel="Change profile photo">
                    <Icon name="camera" size={13} color={colors.white} />
                  </TouchableOpacity>
                </View>
                <Text style={styles.profileIdentityHintText}>Tap to change</Text>
              </View>
              <View style={styles.profileIdentityInfo}>
                <Text style={styles.profileIdentityLabel}>Email</Text>
                <Text style={styles.profileIdentityValue} numberOfLines={1}>
                  {currentUser?.email || '-'}
                </Text>
                <Text style={[styles.profileIdentityLabel, styles.profileIdentityLabelSpacing]}>
                  Username
                </Text>
                <Text style={styles.profileIdentityValue} numberOfLines={1}>
                  {draftUsername || currentUser?.username || '-'}
                </Text>
              </View>
            </View>

            <View style={styles.profileFormCard}>
              <Text style={styles.profileLabel}>Name</Text>
              <TextInput
                style={styles.profileInput}
                value={draftName}
                onChangeText={setDraftName}
                placeholder="Enter your name"
                editable={!saving}
              />

              <View style={styles.formSectionDivider} />

              <Text style={styles.profileLabel}>Country & Phone Number</Text>
              <View style={[styles.hybridField, phoneError && styles.profileInputError]}>
                <TouchableOpacity
                  style={styles.hybridCountryButton}
                  onPress={() => setShowCountryPicker(true)}
                  disabled={saving}>
                  <Text style={styles.hybridCountryText} numberOfLines={1}>
                    {getCountryFlag(selectedCountry)} {countryCode}
                  </Text>
                  <Icon
                    name="chevron-down"
                    size={16}
                    color={colors.text.secondary}
                  />
                </TouchableOpacity>
                <View style={styles.hybridDivider} />

                <TextInput
                  style={styles.hybridPhoneInput}
                  value={draftPhoneNumber}
                  onChangeText={text => {
                    setDraftPhoneNumber(text);
                    setHasPhoneEdited(true);
                    setPhoneError('');
                    setPhoneAvailable(null);
                    setPhoneStatusMessage('');
                  }}
                  placeholder="Enter phone number"
                  keyboardType="phone-pad"
                  editable={!saving}
                />
              </View>
              {checkingPhone && (
                <View style={styles.profileStatusRow}>
                  <ActivityIndicator size="small" color={colors.primary} />
                  <Text style={styles.profileCheckingText}>
                    Checking phone number...
                  </Text>
                </View>
              )}
              {!checkingPhone && phoneAvailable === true && (
                <View style={styles.profileStatusRow}>
                  <Text style={styles.profileSuccessText}>
                    ✓ Phone number available
                  </Text>
                </View>
              )}
              {!checkingPhone && phoneAvailable === false && !phoneError ? (
                <Text style={styles.profileErrorText}>✗ {phoneStatusMessage}</Text>
              ) : null}
              {phoneError ? (
                <Text style={styles.profileErrorText}>{phoneError}</Text>
              ) : null}

              <View style={styles.formSectionDivider} />

              <Text style={styles.profileLabel}>Gender</Text>
              <TouchableOpacity
                style={styles.occupationPicker}
                onPress={() => setGenderModalVisible(true)}>
                <Text style={styles.occupationPickerText}>
                  {draftGender
                    ? draftGender === 'Other'
                      ? 'I would not prefer'
                      : draftGender
                    : 'Select gender'}
                </Text>
                <Icon
                  name="chevron-down"
                  size={18}
                  color={colors.text.secondary}
                />
              </TouchableOpacity>

              <View style={styles.formSectionDivider} />

              <Text style={styles.profileLabel}>Occupation</Text>
              <TouchableOpacity
                style={styles.occupationPicker}
                onPress={() => setOccupationModalVisible(true)}>
                <Text style={styles.occupationPickerText}>
                  {occupationChoice === 'manual'
                    ? manualOccupation || 'Manual'
                    : occupationChoice || 'Select Occupation (Optional)'}
                </Text>
                <Icon
                  name="chevron-down"
                  size={18}
                  color={colors.text.secondary}
                />
              </TouchableOpacity>
              {occupationChoice === 'manual' && (
                <TextInput
                  style={styles.profileInput}
                  value={manualOccupation}
                  onChangeText={setManualOccupation}
                  placeholder="Enter occupation"
                  editable={!saving}
                />
              )}

              <View style={styles.formSectionDivider} />

              <Text style={styles.profileLabel}>Bio</Text>
              <TextInput
                style={[styles.profileInput, styles.profileInputBio]}
                value={draftBio}
                onChangeText={setDraftBio}
                placeholder="Write something about yourself..."
                editable={!saving}
                multiline
                maxLength={150}
              />
              <Text style={styles.bioCharCount}>{draftBio.length}/150</Text>
            </View>

            <TouchableOpacity
              style={[
                styles.profileSaveButton,
                !canSaveProfile && styles.profileSaveButtonDisabled,
              ]}
              onPress={handleSaveProfile}
              disabled={!canSaveProfile}>
              {saving ? (
                <ActivityIndicator color={colors.white} />
              ) : (
                <Text
                  style={[
                    styles.profileSaveText,
                    !canSaveProfile && styles.profileSaveTextDisabled,
                  ]}>
                  Save
                </Text>
              )}
            </TouchableOpacity>
          </ScrollView>
          <Modal
            visible={photoPreviewVisible}
            transparent
            animationType="fade"
            onRequestClose={() => setPhotoPreviewVisible(false)}>
            <View style={styles.previewOverlay}>
              <TouchableOpacity
                style={styles.previewBackdrop}
                activeOpacity={1}
                onPress={() => setPhotoPreviewVisible(false)}
              />
              {draftPhotoUri ? (
                <Image
                  source={{uri: draftPhotoUri}}
                  style={styles.previewImage}
                  resizeMode="contain"
                />
              ) : null}
              <TouchableOpacity
                style={styles.previewClose}
                onPress={() => setPhotoPreviewVisible(false)}>
                <Icon name="close" size={18} color={colors.white} />
              </TouchableOpacity>
            </View>
          </Modal>
          <BottomSheet
            visible={occupationModalVisible}
            onClose={() => setOccupationModalVisible(false)}>
            <Text style={styles.bottomSheetTitle}>Select Occupation</Text>
            {OCCUPATION_OPTIONS.map(option => {
              const isSelected = occupationChoice === option.value;
              return (
                <TouchableOpacity
                  key={option.value}
                  style={[
                    styles.dropdownOption,
                    isSelected && styles.dropdownOptionActive,
                  ]}
                  onPress={() => {
                    setOccupationChoice(option.value);
                    if (option.value !== 'manual') {
                      setManualOccupation('');
                    }
                    setOccupationModalVisible(false);
                  }}>
                  <Text
                    style={[
                      styles.dropdownOptionText,
                      isSelected && styles.dropdownOptionTextActive,
                    ]}>
                    {option.label}
                  </Text>
                  {isSelected && (
                    <Icon name="checkmark" size={18} color={colors.primary} />
                  )}
                </TouchableOpacity>
              );
            })}
          </BottomSheet>

          <BottomSheet
            visible={showCountryPicker}
            onClose={() => setShowCountryPicker(false)}>
            <Text style={styles.bottomSheetTitle}>Select Country</Text>
            {COUNTRIES.map(country => {
              const isSelected = selectedCountry === country.code;
              return (
                <TouchableOpacity
                  key={country.code}
                  style={[
                    styles.dropdownOption,
                    isSelected && styles.dropdownOptionActive,
                  ]}
                  onPress={() => {
                    setSelectedCountry(country.code);
                    setShowCountryPicker(false);
                  }}>
                  <View style={styles.dropdownOptionRow}>
                    <Text style={styles.countryFlagEmoji}>
                      {getCountryFlag(country.code)}
                    </Text>
                    <Text
                      style={[
                        styles.dropdownOptionText,
                        isSelected && styles.dropdownOptionTextActive,
                      ]}>
                      {country.name} ({country.code}) {country.dialCode}
                    </Text>
                  </View>
                  {isSelected && (
                    <Icon name="checkmark" size={18} color={colors.primary} />
                  )}
                </TouchableOpacity>
              );
            })}
          </BottomSheet>

          <BottomSheet
            visible={genderModalVisible}
            onClose={() => setGenderModalVisible(false)}>
            <Text style={styles.bottomSheetTitle}>Select Gender</Text>
            {[
              {label: 'Male', value: 'Male', icon: 'man-outline'},
              {label: 'Female', value: 'Female', icon: 'woman-outline'},
              {label: 'I would not prefer', value: 'Other', icon: null},
            ].map(option => {
              const isSelected = draftGender === option.value;
              return (
                <TouchableOpacity
                  key={option.value}
                  style={[
                    styles.dropdownOption,
                    isSelected && styles.dropdownOptionActive,
                  ]}
                  onPress={() => {
                    setDraftGender(option.value);
                    setGenderModalVisible(false);
                  }}>
                  <View style={styles.dropdownOptionRow}>
                    {option.icon ? (
                      <View style={styles.dropdownOptionIcon}>
                        <Icon
                          name={option.icon}
                          size={18}
                          color={colors.text.secondary}
                        />
                      </View>
                    ) : null}
                    <Text
                      style={[
                        styles.dropdownOptionText,
                        isSelected && styles.dropdownOptionTextActive,
                      ]}>
                      {option.label}
                    </Text>
                  </View>
                  {isSelected && (
                    <Icon name="checkmark" size={18} color={colors.primary} />
                  )}
                </TouchableOpacity>
              );
            })}
          </BottomSheet>
        </Animated.View>
      )}
    </View>
  );
};

