import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Alert,
  Modal,
  TextInput,
} from 'react-native';
import Icon from 'react-native-vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import {colors, spacing, fontSize, fontWeight, headerTexture} from '../utils/theme';
import {queueBackupFromStorage} from '../utils/backupQueue';
import BottomSheet from '../components/BottomSheet';
import TexturedSurface from '../components/TexturedSurface';
import ToggleSwitch from '../components/ui/ToggleSwitch';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {
  getStrictEcoSnapshot,
  getUnsettledStrictEcoAccounts,
  setStrictEcoEnabled as persistStrictEcoEnabled,
} from '../services/strictEcoService';
import {resetDashboardData} from '../services/dashboardResetService';
import {
  DEFAULT_TAB_DASHBOARD,
  DEFAULT_TAB_FALLBACK,
  DEFAULT_TAB_LEDGER,
  readDefaultTabPreference,
  writeDefaultTabPreference,
} from '../utils/defaultTabPreference';

const MONTH_START_DAY_KEY = 'monthStartDay';
const DASHBOARD_SHOW_SAVINGS_BALANCE_KEY = 'dashboard_show_savings_balance_in_net';
const DASHBOARD_HIDE_SAVING_ACCOUNTS_KEY = 'dashboard_hide_saving_accounts';
const MONTH_START_DAY_OPTIONS = Array.from({length: 28}, (_, index) => index + 1);
const DEFAULT_TAB_OPTIONS = [
  {label: 'Dashboard', value: DEFAULT_TAB_DASHBOARD},
  {label: 'Ledger', value: DEFAULT_TAB_LEDGER},
];

const COMMON_SETTINGS = [
  {id: 'language', title: 'Language', icon: 'globe-outline'},
  {id: 'notifications', title: 'Notifications', icon: 'notifications-outline'},
  {id: 'privacy', title: 'Privacy', icon: 'lock-closed-outline'},
];

const SettingsScreen = ({navigation}) => {
  const insets = useSafeAreaInsets();
  const [monthStartDay, setMonthStartDay] = React.useState(1);
  const [monthStartModalVisible, setMonthStartModalVisible] = React.useState(false);
  const [defaultTab, setDefaultTab] = React.useState(DEFAULT_TAB_FALLBACK);
  const [defaultTabModalVisible, setDefaultTabModalVisible] = React.useState(false);
  const [strictEcoEnabled, setStrictEcoEnabled] = React.useState(true);
  const [strictEcoOffHasTxn, setStrictEcoOffHasTxn] = React.useState(false);
  const [showSavingsBalanceInDashboard, setShowSavingsBalanceInDashboard] =
    React.useState(true);
  const [hideSavingAccountOnDashboard, setHideSavingAccountOnDashboard] =
    React.useState(false);
  const [resetModalVisible, setResetModalVisible] = React.useState(false);
  const [resetCaptchaA, setResetCaptchaA] = React.useState(0);
  const [resetCaptchaB, setResetCaptchaB] = React.useState(0);
  const [resetCaptchaAnswer, setResetCaptchaAnswer] = React.useState('');
  const [isResettingDashboard, setIsResettingDashboard] = React.useState(false);

  React.useEffect(() => {
    const loadSettings = async () => {
      try {
        const stored = await AsyncStorage.getItem(MONTH_START_DAY_KEY);
        const parsed = Number(stored);
        if (Number.isFinite(parsed) && parsed >= 1 && parsed <= 28) {
          setMonthStartDay(parsed);
        } else {
          setMonthStartDay(1);
        }

        const strictSnapshot = await getStrictEcoSnapshot();
        setStrictEcoEnabled(Boolean(strictSnapshot.enabled));
        setStrictEcoOffHasTxn(Boolean(strictSnapshot.offHasTxn));

        const showSavingsStored = await AsyncStorage.getItem(
          DASHBOARD_SHOW_SAVINGS_BALANCE_KEY,
        );
        setShowSavingsBalanceInDashboard(showSavingsStored !== '0');

        const hideSavingsStored = await AsyncStorage.getItem(
          DASHBOARD_HIDE_SAVING_ACCOUNTS_KEY,
        );
        setHideSavingAccountOnDashboard(hideSavingsStored === '1');

        const storedDefaultTab = await readDefaultTabPreference();
        setDefaultTab(storedDefaultTab);
      } catch (error) {
        console.error('Failed to load settings:', error);
        setStrictEcoEnabled(true);
        setStrictEcoOffHasTxn(false);
        setShowSavingsBalanceInDashboard(true);
        setHideSavingAccountOnDashboard(false);
        setDefaultTab(DEFAULT_TAB_FALLBACK);
      }
    };
    const handleFocus = () => {
      loadSettings();
    };
    const unsubscribe = navigation.addListener('focus', handleFocus);
    handleFocus();
    return unsubscribe;
  }, [navigation]);

  const handleMonthStartSelect = async day => {
    setMonthStartDay(day);
    setMonthStartModalVisible(false);
    try {
      await AsyncStorage.setItem(MONTH_START_DAY_KEY, String(day));
      queueBackupFromStorage();
    } catch (error) {
      console.error('Failed to save month start day:', error);
    }
  };

  const handleToggleHideSavingAccount = async nextValue => {
    const previousValue = hideSavingAccountOnDashboard;
    setHideSavingAccountOnDashboard(nextValue);
    try {
      await AsyncStorage.setItem(
        DASHBOARD_HIDE_SAVING_ACCOUNTS_KEY,
        nextValue ? '1' : '0',
      );
      queueBackupFromStorage();
    } catch (error) {
      console.error('Failed to save hide saving account setting:', error);
      setHideSavingAccountOnDashboard(previousValue);
      Alert.alert('Error', 'Failed to update setting.');
    }
  };

  const handleToggleShowSavingsBalance = async nextValue => {
    const previousValue = showSavingsBalanceInDashboard;
    setShowSavingsBalanceInDashboard(nextValue);
    try {
      await AsyncStorage.setItem(
        DASHBOARD_SHOW_SAVINGS_BALANCE_KEY,
        nextValue ? '1' : '0',
      );
      queueBackupFromStorage();
    } catch (error) {
      console.error('Failed to save dashboard savings visibility setting:', error);
      setShowSavingsBalanceInDashboard(previousValue);
      Alert.alert('Error', 'Failed to update setting.');
    }
  };

  const handleStrictEcoToggle = nextValue => {
    if (nextValue) {
      Alert.alert(
        'Enable Strict Eco system',
        'Turning on Eco system will strictly follow earning account balance. Do you want to continue?',
        [
          {text: 'Cancel', style: 'cancel'},
          {
            text: 'OK',
            onPress: async () => {
              try {
                if (strictEcoOffHasTxn) {
                  const unsettled = getUnsettledStrictEcoAccounts();
                  if (unsettled.length > 0) {
                    const lines = unsettled
                      .slice(0, 6)
                      .map(
                        item =>
                          `- ${item.accountName}: ${item.balance > 0 ? '+' : ''}${item.balance.toFixed(2)}`
                      );
                    const extra =
                      unsettled.length > 6
                        ? `\n...and ${unsettled.length - 6} more account(s).`
                        : '';
                    Alert.alert(
                      'Settle accounts first',
                      `Before enabling Strict Eco, all earning/expenses accounts must be settled to a zero balance.\n\n${lines.join(
                        '\n'
                      )}${extra}`
                    );
                    return;
                  }
                }
                const nextState = await persistStrictEcoEnabled(true);
                setStrictEcoEnabled(Boolean(nextState.enabled));
                setStrictEcoOffHasTxn(Boolean(nextState.offHasTxn));
                queueBackupFromStorage();
              } catch (error) {
                console.error('Failed to enable strict eco:', error);
                Alert.alert('Error', 'Unable to enable Strict Eco right now.');
              }
            },
          },
        ]
      );
      return;
    }

    Alert.alert(
      'Disable Strict Eco system?',
      'Turning off Strict Eco system enables free-flow mode, disables automation, and may cause calculation mismatches.',
      [
        {text: 'Cancel', style: 'cancel'},
        {
          text: 'OK',
          onPress: async () => {
            try {
              const nextState = await persistStrictEcoEnabled(false);
              setStrictEcoEnabled(Boolean(nextState.enabled));
              setStrictEcoOffHasTxn(Boolean(nextState.offHasTxn));
              queueBackupFromStorage();
            } catch (error) {
              console.error('Failed to disable strict eco:', error);
              Alert.alert('Error', 'Unable to disable Strict Eco right now.');
            }
          },
        },
      ]
    );
  };

  const handleDefaultTabSelect = async selectedTab => {
    const previousDefaultTab = defaultTab;
    const normalized =
      selectedTab === DEFAULT_TAB_LEDGER
        ? DEFAULT_TAB_LEDGER
        : DEFAULT_TAB_DASHBOARD;
    setDefaultTab(normalized);
    setDefaultTabModalVisible(false);
    try {
      await writeDefaultTabPreference(normalized);
      queueBackupFromStorage();
    } catch (error) {
      console.error('Failed to save default tab:', error);
      setDefaultTab(previousDefaultTab);
      Alert.alert('Error', 'Failed to update default tab.');
    }
  };

  const prepareResetCaptcha = () => {
    const left = Math.floor(Math.random() * 9) + 2;
    const right = Math.floor(Math.random() * 9) + 2;
    setResetCaptchaA(left);
    setResetCaptchaB(right);
    setResetCaptchaAnswer('');
  };

  const openResetDashboardFlow = () => {
    Alert.alert(
      'Reset Dashboard Data?',
      'This action will permanently remove dashboard financial data. Ledger data will NOT be deleted.',
      [
        {text: 'Cancel', style: 'cancel'},
        {
          text: 'Continue',
          style: 'destructive',
          onPress: () => {
            Alert.alert(
              'Final Warning',
              'This will delete all Accounts, Transactions, Recurring schedules, and Dashboard preferences. Login and Ledger will remain safe.',
              [
                {text: 'Cancel', style: 'cancel'},
                {
                  text: 'Proceed',
                  style: 'destructive',
                  onPress: () => {
                    prepareResetCaptcha();
                    setResetModalVisible(true);
                  },
                },
              ]
            );
          },
        },
      ]
    );
  };

  const closeResetModal = () => {
    if (isResettingDashboard) {
      return;
    }
    setResetModalVisible(false);
    setResetCaptchaAnswer('');
  };

  const handleResetDashboardConfirm = async () => {
    const expected = String(resetCaptchaA + resetCaptchaB);
    const provided = String(resetCaptchaAnswer || '').trim();
    if (provided !== expected) {
      Alert.alert('Invalid CAPTCHA', 'Please solve the captcha correctly.');
      return;
    }

    setIsResettingDashboard(true);
    try {
      await resetDashboardData();
      setMonthStartDay(1);
      setShowSavingsBalanceInDashboard(true);
      setHideSavingAccountOnDashboard(false);
      setResetModalVisible(false);
      setResetCaptchaAnswer('');
      Alert.alert(
        'Reset Complete',
        'Dashboard data has been reset successfully. Ledger data is unchanged.'
      );
    } catch (error) {
      Alert.alert('Reset Failed', 'Unable to reset dashboard data right now.');
    } finally {
      setIsResettingDashboard(false);
    }
  };

  return (
    <View style={styles.container}>
      <TexturedSurface
        style={[
          styles.header,
          {
            paddingTop: spacing.sm + insets.top,
          },
        ]}>
        <TouchableOpacity
          style={styles.backButton}
          onPress={() => navigation.goBack()}>
          <Icon name="chevron-back" size={22} color={headerTexture.icon} />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Settings</Text>
        <View style={styles.headerSpacer} />
      </TexturedSurface>

      <ScrollView style={styles.scrollView}>
        {/* <View style={styles.section}>
          <Text style={styles.sectionTitle}>Common Settings</Text>
          {COMMON_SETTINGS.map(item => (
            <TouchableOpacity
              key={item.id}
              style={styles.settingRow}
              onPress={() => Alert.alert('Coming Soon', `${item.title} setting`)}>
              <View style={styles.settingLeft}>
                <Icon name={item.icon} size={22} color={colors.text.primary} />
                <Text style={styles.settingText}>{item.title}</Text>
              </View>
              <Icon name="chevron-forward" size={20} color={colors.text.light} />
            </TouchableOpacity>
          ))}
        </View> */}

        <View style={styles.section}>
          <Text style={styles.sectionTitle}>System</Text>
          <TouchableOpacity
            style={styles.settingRow}
            onPress={() => setDefaultTabModalVisible(true)}>
            <View style={styles.settingLeft}>
              <Icon name="albums-outline" size={22} color={colors.text.primary} />
              <Text style={styles.settingText}>Default Tab</Text>
            </View>
            <View style={styles.settingRight}>
              <Text style={styles.settingValue}>{defaultTab}</Text>
              <Icon name="chevron-forward" size={20} color={colors.text.light} />
            </View>
          </TouchableOpacity>
          <View style={styles.settingRow}>
            <View style={styles.settingLeft}>
              <Icon name="leaf-outline" size={22} color={colors.text.primary} />
              <Text style={styles.settingText}>Strict Eco system</Text>
            </View>
            <ToggleSwitch
              value={strictEcoEnabled}
              onValueChange={handleStrictEcoToggle}
              trackColor={{false: '#D1D5DB', true: '#86EFAC'}}
              thumbColor={strictEcoEnabled ? '#16A34A' : '#F9FAFB'}
            />
          </View>
        </View>

        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Dashboard</Text>
          <TouchableOpacity
            style={styles.settingRow}
            onPress={() => setMonthStartModalVisible(true)}>
            <View style={styles.settingLeft}>
              <Icon name="calendar-outline" size={22} color={colors.text.primary} />
              <Text style={styles.settingText}>Quick Period</Text>
            </View>
            <View style={styles.settingRight}>
              <Text style={styles.settingValue}>Day {monthStartDay}</Text>
              <Icon name="chevron-forward" size={20} color={colors.text.light} />
            </View>
          </TouchableOpacity>
          <View style={styles.settingRow}>
            <View style={styles.settingLeft}>
              <Icon name="wallet-outline" size={22} color={colors.text.primary} />
              <Text style={styles.settingText}>Show savings balance in dashboard</Text>
            </View>
            <ToggleSwitch
              value={showSavingsBalanceInDashboard}
              onValueChange={handleToggleShowSavingsBalance}
              trackColor={{false: '#D1D5DB', true: '#86EFAC'}}
              thumbColor={showSavingsBalanceInDashboard ? '#16A34A' : '#F9FAFB'}
            />
          </View>
          <View style={styles.settingRow}>
            <View style={styles.settingLeft}>
              <Icon name="eye-off-outline" size={22} color={colors.text.primary} />
              <Text style={styles.settingText}>Hide Saving Account</Text>
            </View>
            <ToggleSwitch
              value={hideSavingAccountOnDashboard}
              onValueChange={handleToggleHideSavingAccount}
              trackColor={{false: '#D1D5DB', true: '#86EFAC'}}
              thumbColor={hideSavingAccountOnDashboard ? '#16A34A' : '#F9FAFB'}
            />
          </View>
          <TouchableOpacity
            style={styles.settingRow}
            onPress={openResetDashboardFlow}>
            <View style={styles.settingLeft}>
              <Icon name="warning-outline" size={22} color="#B91C1C" />
              <Text style={styles.settingTextDanger}>Reset Dashboard Data</Text>
            </View>
            <Icon name="chevron-forward" size={20} color="#B91C1C" />
          </TouchableOpacity>
        </View>

        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Appearance</Text>
          <TouchableOpacity
            style={styles.settingRow}
            onPress={() => navigation.navigate('ThemeSettings')}>
            <View style={styles.settingLeft}>
              <Icon name="images-outline" size={22} color={colors.text.primary} />
              <Text style={styles.settingText}>Theme</Text>
            </View>
            <Icon name="chevron-forward" size={20} color={colors.text.light} />
          </TouchableOpacity>
        </View>
      </ScrollView>

      <BottomSheet
        visible={monthStartModalVisible}
        onClose={() => setMonthStartModalVisible(false)}>
        <View style={styles.sheetHeaderCentered}>
          <Text style={styles.sheetTitleCentered}>Quick Period Reset Day</Text>
        </View>
        <View style={styles.dayGridContainer}>
          <View style={styles.dayGrid}>
          {MONTH_START_DAY_OPTIONS.map(day => {
            const isActive = day === monthStartDay;
            return (
              <View key={day} style={styles.dayCell}>
                <TouchableOpacity
                  style={[
                    styles.dayButton,
                    isActive && styles.dayButtonActive,
                  ]}
                  onPress={() => handleMonthStartSelect(day)}>
                  <Text
                    style={[styles.dayText, isActive && styles.dayTextActive]}>
                    {day}
                  </Text>
                </TouchableOpacity>
              </View>
            );
          })}
          </View>
        </View>
      </BottomSheet>

      <BottomSheet
        visible={defaultTabModalVisible}
        onClose={() => setDefaultTabModalVisible(false)}>
        <View style={styles.sheetHeaderCentered}>
          <Text style={styles.sheetTitleCentered}>Default Tab</Text>
        </View>
        <View style={styles.defaultTabList}>
          {DEFAULT_TAB_OPTIONS.map(option => {
            const isActive = option.value === defaultTab;
            return (
              <TouchableOpacity
                key={option.value}
                style={styles.defaultTabOption}
                onPress={() => handleDefaultTabSelect(option.value)}>
                <Text
                  style={[
                    styles.defaultTabOptionText,
                    isActive && styles.defaultTabOptionTextActive,
                  ]}>
                  {option.label}
                </Text>
                <Icon
                  name={isActive ? 'checkmark-circle' : 'ellipse-outline'}
                  size={20}
                  color={isActive ? colors.primary : colors.text.light}
                />
              </TouchableOpacity>
            );
          })}
        </View>
      </BottomSheet>

      <Modal
        transparent
        visible={resetModalVisible}
        animationType="fade"
        onRequestClose={closeResetModal}>
        <View style={styles.resetOverlay}>
          <View style={styles.resetCard}>
            <Text style={styles.resetTitle}>Final Security Check</Text>
            <Text style={styles.resetText}>
              This will remove dashboard data only.
            </Text>
            <Text style={styles.resetTextMuted}>
              Ledger and login data will remain safe.
            </Text>
            <Text style={styles.resetCaptchaLabel}>
              Solve: {resetCaptchaA} + {resetCaptchaB} = ?
            </Text>
            <TextInput
              value={resetCaptchaAnswer}
              onChangeText={setResetCaptchaAnswer}
              keyboardType="number-pad"
              editable={!isResettingDashboard}
              style={styles.resetInput}
              placeholder="Enter answer"
              placeholderTextColor={colors.text.light}
            />
            <View style={styles.resetActions}>
              <TouchableOpacity
                style={[styles.resetButton, styles.resetCancelButton]}
                onPress={closeResetModal}
                disabled={isResettingDashboard}>
                <Text style={styles.resetCancelText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.resetButton, styles.resetDangerButton]}
                onPress={handleResetDashboardConfirm}
                disabled={isResettingDashboard}>
                <Text style={styles.resetDangerText}>
                  {isResettingDashboard ? 'Resetting...' : 'Reset Now'}
                </Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </View>
  );
};

